(395900,43989,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, bir A+ daha alırsa gözyaşları yine bütün yeri ..., cidden.'::text,'sular altında bırakacak'::text,'sular altında bırakırdı'::text,'sular altında bıraktı'::text,'Yok, bir A+ daha alırsa gözyaşları yine bütün yeri sular altında bırakacak, cidden.'::text),
(395901,43989,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, ha kap még egy A+-t, a könnyei megint ... az egész padlót, komolyan.'::text,'elárasztják'::text,'elárasztanák'::text,'elárasztották'::text,'Á, ha kap még egy A+-t, a könnyei megint elárasztják az egész padlót, komolyan.'::text),
(395904,43990,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Tränen ..., wenn auf ihrem Blatt 50 stünde.'::text,'würden sofort aufhören'::text,'werden sofort aufhören'::text,'hören sofort auf'::text,'Ihre Tränen würden sofort aufhören, wenn auf ihrem Blatt 50 stünde.'::text),
(395908,43990,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби на її аркуші було 50, її сльози ... одразу.'::text,'припинилися б'::text,'припиняться'::text,'припиняються'::text,'Якби на її аркуші було 50, її сльози припинилися б одразу.'::text),
(395907,43990,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si en su hoja pusiera 50, sus lágrimas ... al instante.'::text,'pararían'::text,'pararán'::text,'paran'::text,'Si en su hoja pusiera 50, sus lágrimas pararían al instante.'::text),
(395906,43990,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sa copie affichait 50, ses larmes ... tout de suite.'::text,'s''arrêteraient'::text,'s''arrêteront'::text,'s''arrêtent'::text,'Si sa copie affichait 50, ses larmes s''arrêteraient tout de suite.'::text),
(395909,43990,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâğıdında 50 yazsaydı, gözyaşları hemen ...'::text,'dururdu'::text,'duracak'::text,'duruyor'::text,'Kâğıdında 50 yazsaydı, gözyaşları hemen dururdu.'::text),
(395910,43990,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha 50 állna a lapján, a könnyei azonnal ...'::text,'elállnának'::text,'el fognak állni'::text,'elállnak'::text,'Ha 50 állna a lapján, a könnyei azonnal elállnának.'::text),
(395913,43991,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine riesige Pfütze um ihre Knie ... von ihren Tränen.'::text,'wurde gebildet'::text,'bildete'::text,'bildet gerade'::text,'Eine riesige Pfütze um ihre Knie wurde gebildet von ihren Tränen.'::text),
(395917,43991,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Величезна калюжа навколо її колін ... її сльозами.'::text,'була утворена'::text,'утворила'::text,'утворює'::text,'Величезна калюжа навколо її колін була утворена її сльозами.'::text),
(395916,43991,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un enorme charco ... por sus lágrimas alrededor de sus rodillas.'::text,'fue formado'::text,'formó'::text,'está formando'::text,'Un enorme charco fue formado por sus lágrimas alrededor de sus rodillas.'::text),
(395915,43991,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une énorme flaque ... par ses larmes autour de ses genoux.'::text,'a été formée'::text,'a formé'::text,'est en train de former'::text,'Une énorme flaque a été formée par ses larmes autour de ses genoux.'::text),
(395918,43991,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dizlerinin etrafında gözyaşlarıyla kocaman bir su birikintisi ...'::text,'oluşturuldu'::text,'oluşturdu'::text,'oluşturuyor'::text,'Dizlerinin etrafında gözyaşlarıyla kocaman bir su birikintisi oluşturuldu.'::text),
(395919,43991,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A térde körül hatalmas tócsa ... a könnyeiből.'::text,'keletkezett'::text,'csinált'::text,'csinál'::text,'A térde körül hatalmas tócsa keletkezett a könnyeiből.'::text),
(395931,43993,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Tränen hören nie auf! Sie ... wegen der A+ weinen!'::text,'muss'::text,'könnte'::text,'sollte'::text,'Diese Tränen hören nie auf! Sie muss wegen der A+ weinen!'::text),
(395935,43993,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці сльози нескінченні! Вона ... плакати через A+!'::text,'мусить'::text,'може'::text,'має'::text,'Ці сльози нескінченні! Вона мусить плакати через A+!'::text),
(395934,43993,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esas lágrimas no se acaban! ¡Ella ... estar llorando por el A+!'::text,'debe de'::text,'podría'::text,'debería'::text,'¡Esas lágrimas no se acaban! ¡Ella debe de estar llorando por el A+!'::text),
(395933,43993,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces larmes sont sans fin ! Elle ... pleurer à cause du A+ !'::text,'doit'::text,'pourrait'::text,'devrait'::text,'Ces larmes sont sans fin ! Elle doit pleurer à cause du A+ !'::text),
(395936,43993,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu gözyaşları bitmiyor! A+ yüzünden ağlıyor ...!'::text,'olmalı'::text,'olabilir'::text,'olmalı'::text,'Bu gözyaşları bitmiyor! A+ yüzünden ağlıyor olmalı!'::text),
(395937,43993,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezek a könnyek végtelenek! ... az A+ miatt sír!'::text,'Biztosan'::text,'Talán'::text,'Bizonyára'::text,'Ezek a könnyek végtelenek! Biztosan az A+ miatt sír!'::text),
(395940,43994,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Babe, angeblich war auf dem Blatt, ... sie zum Weinen gebracht hat, eine A+.'::text,'das'::text,'der'::text,'dessen'::text,'Babe, angeblich war auf dem Blatt, das sie zum Weinen gebracht hat, eine A+.'::text),
(395944,43994,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, на аркуші, ... довів її до сліз, була A+.'::text,'який'::text,'хто'::text,'чий'::text,'Подруго, кажуть, на аркуші, який довів її до сліз, була A+.'::text),
(395943,43994,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer la hoja ... la hizo romper a llorar tenía un A+.'::text,'que'::text,'quien'::text,'cuya'::text,'Tía, al parecer la hoja que la hizo romper a llorar tenía un A+.'::text),
(395942,43994,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment la copie ... l''a fait fondre en larmes avait un A+.'::text,'qui'::text,'qui'::text,'dont'::text,'Meuf, apparemment la copie qui l''a fait fondre en larmes avait un A+.'::text),
(395945,43994,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre ... onu ağlatan kâğıtta A+ varmış.'::text,''::text,NULL::text,NULL::text,'Kızım, duyduğuma göre onu ağlatan kâğıtta A+ varmış.'::text),
(395946,43994,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a lapon, ... sírva fakasztotta, A+ volt.'::text,'ami'::text,'aki'::text,'akinek'::text,'Csajszi, állítólag a lapon, ami sírva fakasztotta, A+ volt.'::text),
(395949,43995,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok also, sie hat mir erzählt, dass sie ..., weil die A+ nicht gereicht hat.'::text,'in Tränen ausgebrochen war'::text,'in Tränen ausgebrochen ist'::text,'in Tränen ausbricht'::text,'Ok also, sie hat mir erzählt, dass sie in Tränen ausgebrochen war, weil die A+ nicht gereicht hat.'::text),
(395953,43995,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, вона сказала мені, що ..., бо A+ було недостатньо.'::text,'розплакалася'::text,'розплакалася'::text,'плаче'::text,'Коротше, вона сказала мені, що розплакалася, бо A+ було недостатньо.'::text),
(395952,43995,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bueno, me dijo que ... a llorar porque el A+ no era suficiente.'::text,'se había echado'::text,'se ha echado'::text,'se echa'::text,'Bueno, me dijo que se había echado a llorar porque el A+ no era suficiente.'::text),
(395951,43995,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, elle m''a dit qu''elle ... en larmes parce que le A+ ne suffisait pas.'::text,'avait fondu'::text,'a fondu'::text,'fond'::text,'Bon alors, elle m''a dit qu''elle avait fondu en larmes parce que le A+ ne suffisait pas.'::text),
(395954,43995,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, bana A+ yetmediği için ... söyledi.'::text,'gözyaşlarına boğulduğunu'::text,'gözyaşlarına boğulduğunu'::text,'gözyaşlarına boğulduğunu'::text,'Neyse, bana A+ yetmediği için gözyaşlarına boğulduğunu söyledi.'::text),
(395955,43995,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, azt mondta, hogy ..., mert az A+ nem volt elég.'::text,'elsírta magát'::text,'elsírta magát'::text,'elsírja magát'::text,'Szóval, azt mondta, hogy elsírta magát, mert az A+ nem volt elég.'::text),
(395958,43996,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, sie ... bei jeder A Freudentränen, nicht so wie jetzt.'::text,'weinte früher'::text,'war es gewohnt zu weinen'::text,'weinte früher'::text,'Bestie, ich hab gehört, sie weinte früher bei jeder A Freudentränen, nicht so wie jetzt.'::text),
(395962,43996,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бесті, я чула, що вона ... плакала від радості через кожну A, а не так.'::text,'раніше'::text,'звикла'::text,'раніше'::text,'Бесті, я чула, що вона раніше плакала від радості через кожну A, а не так.'::text),
(395961,43996,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, oí que ella ... llorar de alegría por cada A, no así.'::text,'solía'::text,'estaba acostumbrada a'::text,'solía'::text,'Bestie, oí que ella solía llorar de alegría por cada A, no así.'::text),
(395960,43996,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, j''ai entendu dire qu''elle ... pleurer de joie pour chaque A, pas comme ça.'::text,'avait l''habitude de'::text,'était habituée à'::text,'avait l''habitude de'::text,'Bestie, j''ai entendu dire qu''elle avait l''habitude de pleurer de joie pour chaque A, pas comme ça.'::text),
(395963,43996,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki her A için sevinç gözyaşları ..., böyle değil.'::text,'dökerdi'::text,'dökmeye alışkındı'::text,'dökerdi'::text,'Kanka, duydum ki her A için sevinç gözyaşları dökerdi, böyle değil.'::text),
(395964,43996,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, úgy hallottam, régen minden A-nál örömkönnyeket ..., nem így.'::text,'sírt'::text,'hozzá volt szokva, hogy sírjon'::text,'sírt'::text,'Csajszi, úgy hallottam, régen minden A-nál örömkönnyeket sírt, nem így.'::text),
(395967,43997,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie kann nicht aufhören, ... wegen einer A+. Ganz klar eine schreckliche Note.'::text,'zu weinen'::text,'zu weinen'::text,'zu weinen'::text,'Sie kann nicht aufhören, zu weinen wegen einer A+. Ganz klar eine schreckliche Note.'::text),
(395971,43997,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона не може перестати ... через A+. Явно жахлива оцінка.'::text,'плакати'::text,'плакати'::text,'плакати'::text,'Вона не може перестати плакати через A+. Явно жахлива оцінка.'::text),
(395970,43997,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No puede parar de ... por un A+. Claramente una nota horrible.'::text,'llorar'::text,'llorar'::text,'llorar'::text,'No puede parar de llorar por un A+. Claramente una nota horrible.'::text),
(395969,43997,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle n''arrête pas de ... pour un A+. Clairement une note horrible.'::text,'pleurer'::text,'pleurer'::text,'pleurer'::text,'Elle n''arrête pas de pleurer pour un A+. Clairement une note horrible.'::text),
(395972,43997,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir A+ yüzünden ... duramıyor. Belli ki berbat bir not.'::text,'ağlamadan'::text,'ağlamadan'::text,'ağlamadan'::text,'Bir A+ yüzünden ağlamadan duramıyor. Belli ki berbat bir not.'::text),
(395973,43997,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem tudja abbahagyni a ... egy A+ miatt. Nyilván szörnyű jegy.'::text,'sírást'::text,'sírást'::text,'sírást'::text,'Nem tudja abbahagyni a sírást egy A+ miatt. Nyilván szörnyű jegy.'::text),
(391242,43472,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann verspricht, dass der Elefant nach der Show sicher von der Bühne ...'::text,'gehen wird'::text,'gehen wird'::text,'geht'::text,'Der Mann verspricht, dass der Elefant nach der Show sicher von der Bühne gehen wird.'::text),
(391246,43472,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік обіцяє, що слон після вистави безпечно ... сцену.'::text,'покине'::text,'покидатиме'::text,'покидає'::text,'Чоловік обіцяє, що слон після вистави безпечно покине сцену.'::text),
(391245,43472,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre promete que el elefante ... el escenario sin peligro después del espectáculo.'::text,'dejará'::text,'estará dejando'::text,'deja'::text,'El hombre promete que el elefante dejará el escenario sin peligro después del espectáculo.'::text),
(391244,43472,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme promet que l''éléphant ... la scène en toute sécurité après le spectacle.'::text,'quittera'::text,'sera en train de quitter'::text,'quitte'::text,'L''homme promet que l''éléphant quittera la scène en toute sécurité après le spectacle.'::text),
(391247,43472,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam, filin gösteriden sonra sahneden güvenle ... söz veriyor.'::text,'ayrılacağına'::text,'ayrılıyor olacağına'::text,'ayrıldığına'::text,'Adam, filin gösteriden sonra sahneden güvenle ayrılacağına söz veriyor.'::text),
(391248,43472,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi megígéri, hogy az elefánt az előadás után biztonságban ... a színpadot.'::text,'el fogja hagyni'::text,'el fogja hagyni'::text,'elhagyja'::text,'A férfi megígéri, hogy az elefánt az előadás után biztonságban el fogja hagyni a színpadot.'::text),
(391251,43473,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Scheinwerfer auf eine Bühne scheint, ... das Publikum, wohin es schauen soll.'::text,'weiß'::text,'wusste'::text,'wird wissen'::text,'Wenn ein Scheinwerfer auf eine Bühne scheint, weiß das Publikum, wohin es schauen soll.'::text),
(391255,43473,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли прожектор світить на сцену, глядачі ..., куди дивитися.'::text,'знають'::text,'знали'::text,'знатимуть'::text,'Коли прожектор світить на сцену, глядачі знають, куди дивитися.'::text),
(391254,43473,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un foco ilumina un escenario, el público ... adónde mirar.'::text,'sabe'::text,'sabía'::text,'sabrá'::text,'Si un foco ilumina un escenario, el público sabe adónde mirar.'::text),
(391253,43473,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un projecteur éclaire une scène, le public ... où regarder.'::text,'sait'::text,'savait'::text,'saura'::text,'Si un projecteur éclaire une scène, le public sait où regarder.'::text),
(391256,43473,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir sahneye spot ışığı vurursa, seyirci nereye bakacağını ...'::text,'bilir'::text,'bildi'::text,'bilecek'::text,'Bir sahneye spot ışığı vurursa, seyirci nereye bakacağını bilir.'::text),
(391257,43473,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy reflektor rávilágít a színpadra, a közönség ..., hová nézzen.'::text,'tudja'::text,'tudta'::text,'tudni fogja'::text,'Ha egy reflektor rávilágít a színpadra, a közönség tudja, hová nézzen.'::text),
(391260,43474,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unglaublich! Der Elefant hat die ganze Bühne mit Blütenblättern bedeckt, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Unglaublich! Der Elefant hat die ganze Bühne mit Blütenblättern bedeckt, oder?'::text),
(391264,43474,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Неймовірно! Слон засипав усю сцену пелюстками, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Неймовірно! Слон засипав усю сцену пелюстками, так?'::text),
(391263,43474,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Increíble! El elefante cubrió todo el escenario de pétalos, ...?'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'¡Increíble! El elefante cubrió todo el escenario de pétalos, ¿verdad?'::text),
(391262,43474,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Incroyable ! L''éléphant a couvert toute la scène de pétales, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Incroyable ! L''éléphant a couvert toute la scène de pétales, non ?'::text),
(391265,43474,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnanılmaz! Fil bütün sahneyi taç yapraklarıyla kapladı, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'İnanılmaz! Fil bütün sahneyi taç yapraklarıyla kapladı, değil mi?'::text),
(391266,43474,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hihetetlen! Az elefánt az egész színpadot beborította szirmokkal, ...?'::text,'nem igaz?'::text,'nem igaz?'::text,'nem igaz?'::text,'Hihetetlen! Az elefánt az egész színpadot beborította szirmokkal, nem igaz?'::text),
(391269,43475,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaos! Das Publikum schrie, als der Elefant die Bühne betrat, und ...'::text,'ich auch'::text,'ich auch'::text,'ich auch'::text,'Chaos! Das Publikum schrie, als der Elefant die Bühne betrat, und ich auch.'::text),
(391273,43475,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хаос! Глядачі закричали, коли слон вийшов на сцену, і ...'::text,'я теж'::text,'я теж'::text,'я теж'::text,'Хаос! Глядачі закричали, коли слон вийшов на сцену, і я теж.'::text),
(391272,43475,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Caos! El público gritó cuando el elefante salió al escenario, y ...'::text,'yo también'::text,'yo también'::text,'yo también'::text,'¡Caos! El público gritó cuando el elefante salió al escenario, y yo también.'::text),
(391271,43475,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chaos ! Le public a crié quand l''éléphant est monté sur scène, et ...'::text,'moi aussi'::text,'moi aussi'::text,'moi aussi'::text,'Le chaos ! Le public a crié quand l''éléphant est monté sur scène, et moi aussi.'::text),
(391274,43475,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaos! Fil sahneye çıktığında seyirci çığlık attı, ...'::text,'ben de'::text,'ben de'::text,'ben de'::text,'Kaos! Fil sahneye çıktığında seyirci çığlık attı, ben de.'::text),
(391275,43475,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Káosz! A közönség felsikoltott, amikor az elefánt színpadra lépett, és ...'::text,'én is'::text,'én is'::text,'én is'::text,'Káosz! A közönség felsikoltott, amikor az elefánt színpadra lépett, és én is.'::text),
(391278,43476,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Show werden diese Blütenblätter jeden Zentimeter der Bühne ..., totales Chaos!'::text,'bedeckt haben'::text,'bedecken'::text,'gerade bedecken'::text,'Bis zum Ende der Show werden diese Blütenblätter jeden Zentimeter der Bühne bedeckt haben, totales Chaos!'::text),
(391282,43476,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця вистави ці пелюстки ... кожен сантиметр сцени. Повний хаос!'::text,'вкриють'::text,'вкриють'::text,'вкриватимуть'::text,'До кінця вистави ці пелюстки вкриють кожен сантиметр сцени. Повний хаос!'::text),
(391281,43476,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final del espectáculo, estos pétalos ... cada centímetro del escenario. ¡Caos total!'::text,'habrán cubierto'::text,'cubrirán'::text,'estarán cubriendo'::text,'Para el final del espectáculo, estos pétalos habrán cubierto cada centímetro del escenario. ¡Caos total!'::text),
(391280,43476,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du spectacle, ces pétales ... chaque centimètre de la scène. Le chaos total !'::text,'auront recouvert'::text,'recouvriront'::text,'seront en train de recouvrir'::text,'D''ici la fin du spectacle, ces pétales auront recouvert chaque centimètre de la scène. Le chaos total !'::text),
(391283,43476,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gösterinin sonuna kadar bu taç yapraklar sahnenin her santimini ..., tam bir kaos!'::text,'kaplamış olacak'::text,'kaplayacak'::text,'kaplıyor olacak'::text,'Gösterinin sonuna kadar bu taç yapraklar sahnenin her santimini kaplamış olacak, tam bir kaos!'::text),
(391284,43476,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az előadás végére ezek a szirmok a színpad minden centiméterét ..., teljes káosz!'::text,'beborítják'::text,'be fogják borítani'::text,'borítani fogják'::text,'Az előadás végére ezek a szirmok a színpad minden centiméterét beborítják, teljes káosz!'::text),
(391287,43477,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Blumen nicht geplatzt wären, hätte das Publikum den echten Elefanten auf der Bühne ...'::text,'nicht gesehen'::text,'nicht sehen'::text,'nicht gesehen'::text,'Wenn die Blumen nicht geplatzt wären, hätte das Publikum den echten Elefanten auf der Bühne nicht gesehen.'::text),
(391291,43477,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби квіти не вибухнули, глядачі ... справжнього слона на сцені.'::text,'не побачили б'::text,'не побачать'::text,'не бачили'::text,'Якби квіти не вибухнули, глядачі не побачили б справжнього слона на сцені.'::text),
(391290,43477,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si las flores no hubieran estallado, el público ... al elefante real en el escenario.'::text,'no habría visto'::text,'no verá'::text,'no vio'::text,'Si las flores no hubieran estallado, el público no habría visto al elefante real en el escenario.'::text),
(391289,43477,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les fleurs n''avaient pas éclaté, le public ... le vrai éléphant sur scène.'::text,'n''aurait pas vu'::text,'ne verra pas'::text,'n''a pas vu'::text,'Si les fleurs n''avaient pas éclaté, le public n''aurait pas vu le vrai éléphant sur scène.'::text),
(391292,43477,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiçekler patlamasaydı, seyirci sahnedeki gerçek fili ...'::text,'görmemiş olurdu'::text,'görmeyecek'::text,'görmedi'::text,'Çiçekler patlamasaydı, seyirci sahnedeki gerçek fili görmemiş olurdu.'::text),
(391293,43477,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a virágok nem pukkantak volna szét, a közönség ... az igazi elefántot a színpadon.'::text,'nem látta volna'::text,'nem fogja látni'::text,'nem látta'::text,'Ha a virágok nem pukkantak volna szét, a közönség nem látta volna az igazi elefántot a színpadon.'::text),
(391296,43478,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Babe, angeblich weigerte er sich, ..., wie der Elefant auf die Bühne kam.'::text,'zu erklären'::text,'zu erklären'::text,'erklärt zu haben'::text,'Babe, angeblich weigerte er sich, zu erklären, wie der Elefant auf die Bühne kam.'::text),
(391300,43478,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він відмовився ..., як слон потрапив на сцену.'::text,'пояснити'::text,'пояснювати'::text,'пояснити'::text,'Подруго, кажуть, він відмовився пояснити, як слон потрапив на сцену.'::text),
(391299,43478,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer se negó a ... cómo llegó el elefante al escenario.'::text,'explicar'::text,'explicar'::text,'haber explicado'::text,'Tía, al parecer se negó a explicar cómo llegó el elefante al escenario.'::text),
(391298,43478,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il a refusé ... comment l''éléphant était arrivé sur scène.'::text,'d''expliquer'::text,'d''expliquer'::text,'d''avoir expliqué'::text,'Meuf, apparemment il a refusé d''expliquer comment l''éléphant était arrivé sur scène.'::text),
(391301,43478,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre filin sahneye nasıl çıktığını ... reddetmiş.'::text,'açıklamayı'::text,'açıklamayı'::text,'açıklamış olmayı'::text,'Kızım, duyduğuma göre filin sahneye nasıl çıktığını açıklamayı reddetmiş.'::text),
(391302,43478,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag nem volt hajlandó ..., hogyan került az elefánt a színpadra.'::text,'elmagyarázni'::text,'elmagyarázni'::text,'elmagyarázni'::text,'Csajszi, állítólag nem volt hajlandó elmagyarázni, hogyan került az elefánt a színpadra.'::text),
(391305,43479,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok also, angeblich war der echte Elefant die ganze Zeit ... unter den Blumen auf der Bühne versteckt.'::text,'bestimmt'::text,'eigentlich'::text,'auf keinen Fall'::text,'Ok also, angeblich war der echte Elefant die ganze Zeit bestimmt unter den Blumen auf der Bühne versteckt.'::text),
(391309,43479,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, справжній слон ... весь час захований під квітами на сцені.'::text,'мусив бути'::text,'мав бути'::text,'не міг бути'::text,'Коротше, кажуть, справжній слон мусив бути весь час захований під квітами на сцені.'::text),
(391308,43479,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bueno, al parecer el elefante real ... escondido bajo las flores en el escenario todo el tiempo.'::text,'debió de estar'::text,'debería haber estado'::text,'no pudo haber estado'::text,'Bueno, al parecer el elefante real debió de estar escondido bajo las flores en el escenario todo el tiempo.'::text),
(391307,43479,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment le vrai éléphant ... caché sous les fleurs sur scène depuis le début.'::text,'devait être'::text,'aurait dû être'::text,'ne pouvait pas être'::text,'Bon alors, apparemment le vrai éléphant devait être caché sous les fleurs sur scène depuis le début.'::text),
(391310,43479,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, duyduğuma göre gerçek fil başından beri sahnede çiçeklerin altında saklanıyor ...'::text,'olmalıymış'::text,'olması gerekirdi'::text,'olamazmış'::text,'Neyse, duyduğuma göre gerçek fil başından beri sahnede çiçeklerin altında saklanıyor olmalıymış.'::text),
(391311,43479,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag az igazi elefánt végig ... a virágok alatt rejtőzött a színpadon.'::text,'biztosan'::text,'elvileg'::text,'biztosan nem'::text,'Szóval, állítólag az igazi elefánt végig biztosan a virágok alatt rejtőzött a színpadon.'::text),
(391323,43481,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... auf die Bühne, als hättest du das schon tausendmal gemacht. Ikonisch.'::text,'kamst'::text,'kamst'::text,'kommst'::text,'Du kamst auf die Bühne, als hättest du das schon tausendmal gemacht. Ikonisch.'::text),
(391327,43481,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... на сцену так, ніби робив це тисячу разів. Культово.'::text,'вийшов'::text,'вийшов'::text,'виходиш'::text,'Ти вийшов на сцену так, ніби робив це тисячу разів. Культово.'::text),
(391326,43481,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... al escenario como si lo hubieras hecho mil veces. Icónico.'::text,'Saliste'::text,'Has salido'::text,'Sales'::text,'Saliste al escenario como si lo hubieras hecho mil veces. Icónico.'::text),
(391325,43481,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... sur scène comme si tu l''avais fait mille fois. Iconique.'::text,'es monté'::text,'es monté'::text,'montes'::text,'Tu es monté sur scène comme si tu l''avais fait mille fois. Iconique.'::text),
(391328,43481,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahneye, bunu bin kez yapmış gibi ..., efsane.'::text,'çıktın'::text,'çıktın'::text,'çıkıyorsun'::text,'Sahneye, bunu bin kez yapmış gibi çıktın, efsane.'::text),
(391329,43481,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy ... fel a színpadra, mintha már ezerszer csináltad volna. Ikonikus.'::text,'sétáltál'::text,'sétáltál'::text,'sétálsz'::text,'Úgy sétáltál fel a színpadra, mintha már ezerszer csináltad volna. Ikonikus.'::text),
(354360,39374,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit wird der Gorilla einen Flat Top ..., weil Frisuren bleiben.'::text,'tragen'::text,'tragen'::text,'trägt'::text,'Morgen um diese Zeit wird der Gorilla einen Flat Top tragen, weil Frisuren bleiben.'::text),
(354364,39374,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час горила ... стрижку з пласким верхом, бо стрижки залишаються.'::text,'носитиме'::text,'носитиме'::text,'носить'::text,'Завтра в цей час горила носитиме стрижку з пласким верхом, бо стрижки залишаються.'::text),
(354363,39374,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, el gorila ... un corte plano por arriba, porque los cortes de pelo se quedan.'::text,'estará llevando'::text,'llevará'::text,'lleva'::text,'Mañana a esta hora, el gorila estará llevando un corte plano por arriba, porque los cortes de pelo se quedan.'::text),
(354362,39374,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, le gorille ... une coupe plate sur le dessus, parce que les coupes de cheveux, ça reste.'::text,'portera'::text,'portera'::text,'porte'::text,'Demain à la même heure, le gorille portera une coupe plate sur le dessus, parce que les coupes de cheveux, ça reste.'::text),
(354365,39374,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte goril düz tepe bir saç ..., çünkü saç kesimleri kalıcı.'::text,'taşıyor olacak'::text,'taşıyacak'::text,'taşıyor'::text,'Yarın bu saatte goril düz tepe bir saç taşıyor olacak, çünkü saç kesimleri kalıcı.'::text),
(354366,39374,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a gorilla lapos tetejű frizurát ..., mert a frizurák maradnak.'::text,'fog viselni'::text,'fog viselni'::text,'visel'::text,'Holnap ilyenkor a gorilla lapos tetejű frizurát fog viselni, mert a frizurák maradnak.'::text),
(354369,39375,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Babe, die Katze schwört, dass sie den Oberkopf komplett flach ...'::text,'schneiden wird'::text,'schneiden wird'::text,'schneidet'::text,'Babe, die Katze schwört, dass sie den Oberkopf komplett flach schneiden wird.'::text),
(354373,39375,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кішка клянеться, що ... верх зовсім пласким.'::text,'підстриже'::text,'підстригатиме'::text,'підстригає'::text,'Подруго, кішка клянеться, що підстриже верх зовсім пласким.'::text),
(354372,39375,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, el gato jura que ... la parte de arriba completamente plana.'::text,'cortará'::text,'estará cortando'::text,'corta'::text,'Tía, el gato jura que cortará la parte de arriba completamente plana.'::text),
(354371,39375,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, le chat jure qu''il ... le dessus complètement plat.'::text,'coupera'::text,'sera en train de couper'::text,'coupe'::text,'Meuf, le chat jure qu''il coupera le dessus complètement plat.'::text),
(354374,39375,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, kedi tepeyi tamamen düz ... yemin ediyor.'::text,'keseceğine'::text,'kesiyor olacağına'::text,'kestiğine'::text,'Kızım, kedi tepeyi tamamen düz keseceğine yemin ediyor.'::text),
(354375,39375,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a macska esküszik, hogy teljesen laposra ... a tetejét.'::text,'le fogja vágni'::text,'vágni fogja'::text,'vágja'::text,'Csajszi, a macska esküszik, hogy teljesen laposra le fogja vágni a tetejét.'::text),
(354378,39376,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Friseur oben gerade drüber schneidet, ... die Haare flach aus.'::text,'sehen'::text,'sahen'::text,'werden'::text,'Wenn ein Friseur oben gerade drüber schneidet, sehen die Haare flach aus.'::text),
(354382,39376,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо перукар стриже рівно по верху, волосся ... пласким.'::text,'виглядає'::text,'виглядало'::text,'виглядатиме'::text,'Якщо перукар стриже рівно по верху, волосся виглядає пласким.'::text),
(354381,39376,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un barbero corta recto por arriba, el pelo ... plano.'::text,'queda'::text,'quedó'::text,'quedará'::text,'Si un barbero corta recto por arriba, el pelo queda plano.'::text),
(354380,39376,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un barbier coupe bien droit sur le dessus, les cheveux ... plats.'::text,'paraissent'::text,'paraissaient'::text,'paraîtront'::text,'Si un barbier coupe bien droit sur le dessus, les cheveux paraissent plats.'::text),
(354383,39376,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Berber tepeyi düz keserse saç düz ...'::text,'görünür'::text,'göründü'::text,'görünecek'::text,'Berber tepeyi düz keserse saç düz görünür.'::text),
(354384,39376,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a borbély egyenesen vágja le a tetejét, a haj laposnak ...'::text,'tűnik'::text,'tűnt'::text,'fog tűnni'::text,'Ha a borbély egyenesen vágja le a tetejét, a haj laposnak tűnik.'::text),
(354387,39377,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gorilla liebt seinen neuen Flat Top natürlich, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Der Gorilla liebt seinen neuen Flat Top natürlich, oder?'::text),
(354391,39377,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Горила, звісно, обожнює свою нову пласку стрижку, ...?'::text,'правда?'::text,'правда?'::text,'правда?'::text,'Горила, звісно, обожнює свою нову пласку стрижку, правда?'::text),
(354390,39377,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente al gorila le encanta su nuevo corte plano, ...?'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'Obviamente al gorila le encanta su nuevo corte plano, ¿verdad?'::text),
(354389,39377,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gorille adore évidemment sa nouvelle coupe plate, ... ?'::text,'pas vrai ?'::text,'pas vrai ?'::text,'pas vrai ?'::text,'Le gorille adore évidemment sa nouvelle coupe plate, pas vrai ?'::text),
(354392,39377,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Goril yeni düz saçına tabii ki bayılıyor, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Goril yeni düz saçına tabii ki bayılıyor, değil mi?'::text),
(354393,39377,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gorilla nyilván imádja az új lapos frizuráját, ...?'::text,'nem?'::text,'nem?'::text,'nem?'::text,'A gorilla nyilván imádja az új lapos frizuráját, nem?'::text),
(354414,39380,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Katze nur die Haarschneidemaschine benutzt hätte, ... der Oberkopf nicht so flach geworden.'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn die Katze nur die Haarschneidemaschine benutzt hätte, wäre der Oberkopf nicht so flach geworden.'::text),
(354418,39380,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби кішка використала лише машинку, верх ... таким пласким.'::text,'не був би'::text,'не буде'::text,'не був'::text,'Якби кішка використала лише машинку, верх не був би таким пласким.'::text),
(354417,39380,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el gato hubiera usado solo la maquinilla, la parte de arriba ... tan plana.'::text,'no habría quedado'::text,'no quedará'::text,'no quedó'::text,'Si el gato hubiera usado solo la maquinilla, la parte de arriba no habría quedado tan plana.'::text),
(354416,39380,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le chat avait utilisé seulement la tondeuse, le dessus ... aussi plat.'::text,'n''aurait pas été'::text,'ne sera pas'::text,'n''était pas'::text,'Si le chat avait utilisé seulement la tondeuse, le dessus n''aurait pas été aussi plat.'::text),
(354419,39380,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi sadece makine kullansaydı, tepe bu kadar düz ...'::text,'olmazdı'::text,'olmayacak'::text,'değildi'::text,'Kedi sadece makine kullansaydı, tepe bu kadar düz olmazdı.'::text),
(354420,39380,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a macska csak gépet használt volna, a teteje ... ilyen lapos.'::text,'nem lett volna'::text,'nem lesz'::text,'nem volt'::text,'Ha a macska csak gépet használt volna, a teteje nem lett volna ilyen lapos.'::text),
(354423,39381,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Katze schlug vor, den Oberkopf flach statt rund ...'::text,'zu schneiden'::text,'zu schneiden'::text,'zu schneiden'::text,'Die Katze schlug vor, den Oberkopf flach statt rund zu schneiden.'::text),
(354427,39381,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кішка запропонувала ... верх пласким, а не круглим.'::text,'підстригти'::text,'підстригти'::text,'підстригти'::text,'Кішка запропонувала підстригти верх пласким, а не круглим.'::text),
(354426,39381,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gato sugirió ... la parte de arriba plana en vez de redonda.'::text,'cortar'::text,'cortar'::text,'cortar'::text,'El gato sugirió cortar la parte de arriba plana en vez de redonda.'::text),
(354425,39381,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chat a proposé de ... le dessus plat plutôt que rond.'::text,'couper'::text,'couper'::text,'couper'::text,'Le chat a proposé de couper le dessus plat plutôt que rond.'::text),
(354428,39381,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi tepeyi yuvarlak yerine düz ... önerdi.'::text,'kesmeyi'::text,'kesmeyi'::text,'kesmeyi'::text,'Kedi tepeyi yuvarlak yerine düz kesmeyi önerdi.'::text),
(354429,39381,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A macska azt javasolta, hogy ... a tetejét laposra kerek helyett.'::text,'vágják'::text,'vágják'::text,'vágják'::text,'A macska azt javasolta, hogy vágják a tetejét laposra kerek helyett.'::text),
(354432,39382,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gorilla hat ... um einen Flat Top gebeten, denn er sieht jetzt unglücklich aus.'::text,'bestimmt nicht'::text,'bestimmt'::text,'lieber nicht'::text,'Der Gorilla hat bestimmt nicht um einen Flat Top gebeten, denn er sieht jetzt unglücklich aus.'::text),
(354436,39382,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Горила ... просити пласку стрижку, бо тепер виглядає нещасною.'::text,'не могла'::text,'мусила'::text,'не мала б'::text,'Горила не могла просити пласку стрижку, бо тепер виглядає нещасною.'::text),
(354435,39382,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gorila ... pedido un corte plano, porque ahora parece triste.'::text,'no puede haber'::text,'debe de haber'::text,'no debería haber'::text,'El gorila no puede haber pedido un corte plano, porque ahora parece triste.'::text),
(354434,39382,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gorille ... demandé une coupe plate, parce qu''il a l''air malheureux maintenant.'::text,'ne peut pas avoir'::text,'doit avoir'::text,'ne devrait pas avoir'::text,'Le gorille ne peut pas avoir demandé une coupe plate, parce qu''il a l''air malheureux maintenant.'::text),
(354437,39382,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Goril düz saç ..., çünkü şimdi mutsuz görünüyor.'::text,'istemiş olamaz'::text,'istemiş olmalı'::text,'istememeli'::text,'Goril düz saç istemiş olamaz, çünkü şimdi mutsuz görünüyor.'::text),
(354438,39382,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gorilla ... lapos frizurát, mert most boldogtalannak tűnik.'::text,'nem kérhetett'::text,'biztosan kért'::text,'nem kellett volna kérnie'::text,'A gorilla nem kérhetett lapos frizurát, mert most boldogtalannak tűnik.'::text),
(354441,39383,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Exemplar ließ sich sein Afro von einem felinen Barbier flach ...'::text,'schneiden'::text,'zu schneiden'::text,'schneidend'::text,'Das Exemplar ließ sich sein Afro von einem felinen Barbier flach schneiden.'::text),
(354445,39383,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Особина попросила котячого перукаря ... її афро пласким.'::text,'підстригти'::text,'підстригти'::text,'підстригання'::text,'Особина попросила котячого перукаря підстригти її афро пласким.'::text),
(354444,39383,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El espécimen se hizo ... el afro plano por un barbero felino.'::text,'cortar'::text,'cortar'::text,'cortando'::text,'El espécimen se hizo cortar el afro plano por un barbero felino.'::text),
(354443,39383,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le spécimen s''est fait ... son afro à plat par un barbier félin.'::text,'couper'::text,'couper'::text,'coupant'::text,'Le spécimen s''est fait couper son afro à plat par un barbier félin.'::text),
(354446,39383,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek afrosunu kedigil bir berbere düz ...'::text,'kestirdi'::text,'kestirdi'::text,'kestiriyordu'::text,'Denek afrosunu kedigil bir berbere düz kestirdi.'::text),
(354447,39383,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A példány egy macskaféle borbéllyal laposra ... az afróját.'::text,'vágatta'::text,'vágatta'::text,'vágatta'::text,'A példány egy macskaféle borbéllyal laposra vágatta az afróját.'::text),
(354450,39384,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gorilla ... sein Afro jahrelang wachsen, bevor die Katze es flach schnitt.'::text,'ließ'::text,'lässt'::text,'lässt'::text,'Der Gorilla ließ sein Afro jahrelang wachsen, bevor die Katze es flach schnitt.'::text),
(354454,39384,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Горила ... своє афро роками, поки кішка не підстригла його пласким.'::text,'відрощувала'::text,'відрощує'::text,'відрощує'::text,'Горила відрощувала своє афро роками, поки кішка не підстригла його пласким.'::text),
(354453,39384,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gorila ... el afro durante años antes de que el gato lo cortara plano.'::text,'había estado dejándose crecer'::text,'ha estado dejándose crecer'::text,'se deja crecer'::text,'El gorila había estado dejándose crecer el afro durante años antes de que el gato lo cortara plano.'::text),
(354452,39384,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gorille ... son afro pendant des années avant que le chat le coupe à plat.'::text,'avait laissé pousser'::text,'a laissé pousser'::text,'laisse pousser'::text,'Le gorille avait laissé pousser son afro pendant des années avant que le chat le coupe à plat.'::text),
(354455,39384,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi onu düz kesmeden önce goril afrosunu yıllardır ...'::text,'uzatıyordu'::text,'uzatıyor'::text,'uzatır'::text,'Kedi onu düz kesmeden önce goril afrosunu yıllardır uzatıyordu.'::text),
(354456,39384,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gorilla évekig ... az afróját, mielőtt a macska laposra vágta.'::text,'növesztette'::text,'növeszti'::text,'növeszti'::text,'A gorilla évekig növesztette az afróját, mielőtt a macska laposra vágta.'::text),
(373008,41446,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Versuchsperson ... gerade den schmalen Pfad hinauf, als sich der Nebel erheblich verdichtete.'::text,'stieg'::text,'stieg'::text,'steigt'::text,'Die Versuchsperson stieg gerade den schmalen Pfad hinauf, als sich der Nebel erheblich verdichtete.'::text),
(373012,41446,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суб''єкт ... вузькою стежкою вгору, коли туман значно згустився.'::text,'підіймався'::text,'піднявся'::text,'піднявся'::text,'Суб''єкт підіймався вузькою стежкою вгору, коли туман значно згустився.'::text),
(373011,41446,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sujeto ... por el estrecho sendero cuando la niebla se espesó considerablemente.'::text,'estaba subiendo'::text,'subió'::text,'ha subido'::text,'El sujeto estaba subiendo por el estrecho sendero cuando la niebla se espesó considerablemente.'::text),
(373010,41446,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet ... le sentier étroit quand le brouillard s''est considérablement épaissi.'::text,'montait'::text,'a monté'::text,'a monté'::text,'Le sujet montait le sentier étroit quand le brouillard s''est considérablement épaissi.'::text),
(373013,41446,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sis önemli ölçüde yoğunlaştığında denek dar patikadan yukarı ...'::text,'tırmanıyordu'::text,'tırmandı'::text,'tırmandı'::text,'Sis önemli ölçüde yoğunlaştığında denek dar patikadan yukarı tırmanıyordu.'::text),
(373014,41446,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany éppen ... a keskeny ösvényen, amikor a köd jelentősen megsűrűsödött.'::text,'kapaszkodott felfelé'::text,'felkapaszkodott'::text,'felkapaszkodott'::text,'Az alany éppen kapaszkodott felfelé a keskeny ösvényen, amikor a köd jelentősen megsűrűsödött.'::text),
(373017,41447,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... schon seit einer Stunde diesen nebligen Pfad hoch und bist immer noch voll dabei. Respekt.'::text,'läufst'::text,'läufst'::text,'läufst'::text,'Ehrlich, du läufst schon seit einer Stunde diesen nebligen Pfad hoch und bist immer noch voll dabei. Respekt.'::text),
(373021,41447,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... цією туманною стежкою вгору вже годину і досі тримаєшся. Респект.'::text,'йдеш'::text,'йдеш'::text,'ходиш'::text,'Чесно, ти йдеш цією туманною стежкою вгору вже годину і досі тримаєшся. Респект.'::text),
(373020,41447,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... por este sendero con niebla desde hace una hora y sigues a tope. Respeto.'::text,'has estado subiendo'::text,'estás subiendo'::text,'subes'::text,'Sinceramente, has estado subiendo por este sendero con niebla desde hace una hora y sigues a tope. Respeto.'::text),
(373019,41447,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... ce sentier brumeux depuis une heure, et tu tiens toujours la forme. Respect.'::text,'montes'::text,'montes'::text,'montes'::text,'Franchement, tu montes ce sentier brumeux depuis une heure, et tu tiens toujours la forme. Respect.'::text),
(373022,41447,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bir saattir bu sisli patikada ... ve hâlâ güçlüsün. Saygı.'::text,'yürüyorsun'::text,'yürüyorsun'::text,'yürürsün'::text,'Açıkçası, bir saattir bu sisli patikada yürüyorsun ve hâlâ güçlüsün. Saygı.'::text),
(373023,41447,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, már egy órája ... ezen a ködös ösvényen, és még mindig bírod. Respekt.'::text,'mész felfelé'::text,'mész felfelé'::text,'jársz'::text,'Őszintén, már egy órája mész felfelé ezen a ködös ösvényen, és még mindig bírod. Respekt.'::text),
(373026,41448,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Irgendwie ikonisch, wie du gestern den ganzen nebligen Pfad in einem Rutsch ...'::text,'gegangen bist'::text,'gegangen bist'::text,'gegangen bist'::text,'Irgendwie ikonisch, wie du gestern den ganzen nebligen Pfad in einem Rutsch gegangen bist.'::text),
(373030,41448,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи культово, як ти вчора ... всю цю туманну стежку за один раз.'::text,'пройшов'::text,'проходив'::text,'пройшов'::text,'Трохи культово, як ти вчора пройшов всю цю туманну стежку за один раз.'::text),
(373029,41448,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bastante icónico cómo ayer ... todo ese sendero con niebla de una vez.'::text,'recorriste'::text,'estabas recorriendo'::text,'has recorrido'::text,'Bastante icónico cómo ayer recorriste todo ese sendero con niebla de una vez.'::text),
(373028,41448,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un peu iconique, la façon dont tu ... tout ce sentier brumeux d''une traite hier.'::text,'as parcouru'::text,'parcourais'::text,'as parcouru'::text,'Un peu iconique, la façon dont tu as parcouru tout ce sentier brumeux d''une traite hier.'::text),
(373031,41448,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün o sisli patikanın tamamını tek seferde ... biraz ikonikti.'::text,'yürümen'::text,'yürüyor olman'::text,'yürümüş olman'::text,'Dün o sisli patikanın tamamını tek seferde yürümen biraz ikonikti.'::text),
(373032,41448,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elég ikonikus, ahogy tegnap egy szuszra ... az egész ködös ösvényt.'::text,'végigmentél'::text,'mentél'::text,'végigmentél'::text,'Elég ikonikus, ahogy tegnap egy szuszra végigmentél az egész ködös ösvényt.'::text),
(373044,41450,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er den Pfad erreichte, ... der Nebel schon alles. Perfekte Aussicht, natürlich.'::text,'verdeckte'::text,'verdeckte'::text,'verdeckt'::text,'Als er den Pfad erreichte, verdeckte der Nebel schon alles. Perfekte Aussicht, natürlich.'::text),
(373048,41450,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він дійшов до стежки, туман уже ... все. Ідеальні краєвиди, звісно.'::text,'накрив'::text,'накрив'::text,'накриває'::text,'Коли він дійшов до стежки, туман уже накрив все. Ідеальні краєвиди, звісно.'::text),
(373047,41450,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegó al sendero, la niebla ya ... todo. Vistas perfectas, obviamente.'::text,'lo había cubierto'::text,'lo ha cubierto'::text,'lo cubre'::text,'Para cuando llegó al sendero, la niebla ya lo había cubierto todo. Vistas perfectas, obviamente.'::text),
(373046,41450,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il a atteint le sentier, le brouillard ... tout. Des vues parfaites, évidemment.'::text,'avait recouvert'::text,'a recouvert'::text,'recouvre'::text,'Quand il a atteint le sentier, le brouillard avait recouvert tout. Des vues parfaites, évidemment.'::text),
(373049,41450,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Patikaya vardığında sis her şeyi çoktan ..., mükemmel manzara tabii.'::text,'kaplamıştı'::text,'kapladı'::text,'kaplıyor'::text,'Patikaya vardığında sis her şeyi çoktan kaplamıştı, mükemmel manzara tabii.'::text),
(373050,41450,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire az ösvényhez ért, a köd már mindent ..., tökéletes kilátás, persze.'::text,'beborított'::text,'beborított'::text,'beborít'::text,'Mire az ösvényhez ért, a köd már mindent beborított, tökéletes kilátás, persze.'::text),
(373053,41451,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Nebel noch dicker wird, ... er den Pfad komplett. Tolle Aussicht, natürlich.'::text,'verliert'::text,'würde verlieren'::text,'verlor'::text,'Wenn der Nebel noch dicker wird, verliert er den Pfad komplett. Tolle Aussicht, natürlich.'::text),
(373057,41451,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо туман ще згуститься, він ... стежку зовсім. Чудові краєвиди, звісно.'::text,'загубить'::text,'загубив би'::text,'загубив'::text,'Якщо туман ще згуститься, він загубить стежку зовсім. Чудові краєвиди, звісно.'::text),
(373056,41451,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la niebla se vuelve más espesa, ... el sendero por completo. Vistas geniales, obviamente.'::text,'perderá'::text,'perdería'::text,'perdió'::text,'Si la niebla se vuelve más espesa, perderá el sendero por completo. Vistas geniales, obviamente.'::text),
(373055,41451,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le brouillard s''épaissit encore, il ... complètement le sentier. Super vue, évidemment.'::text,'perdra'::text,'perdrait'::text,'a perdu'::text,'Si le brouillard s''épaissit encore, il perdra complètement le sentier. Super vue, évidemment.'::text),
(373058,41451,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sis biraz daha yoğunlaşırsa, patikayı tamamen ..., harika manzara tabii.'::text,'kaybedecek'::text,'kaybederdi'::text,'kaybetti'::text,'Sis biraz daha yoğunlaşırsa, patikayı tamamen kaybedecek, harika manzara tabii.'::text),
(373059,41451,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a köd még sűrűbb lesz, teljesen ... az ösvényt. Remek kilátás, persze.'::text,'elveszíti'::text,'elveszítené'::text,'elveszítette'::text,'Ha a köd még sűrűbb lesz, teljesen elveszíti az ösvényt. Remek kilátás, persze.'::text),
(373062,41452,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich wahrscheinlich, der Pfad ... etwas weniger neblig. Kleines Detail.'::text,'wäre'::text,'wird'::text,'ist'::text,'Er wünscht sich wahrscheinlich, der Pfad wäre etwas weniger neblig. Kleines Detail.'::text),
(373066,41452,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він, мабуть, хотів би, щоб стежка ... трохи менш туманною. Дрібниця.'::text,'була'::text,'буде'::text,'є'::text,'Він, мабуть, хотів би, щоб стежка була трохи менш туманною. Дрібниця.'::text),
(373065,41452,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seguramente desearía que el sendero ... un poco menos neblinoso. Detalle menor.'::text,'fuera'::text,'será'::text,'es'::text,'Seguramente desearía que el sendero fuera un poco menos neblinoso. Detalle menor.'::text),
(373064,41452,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait sûrement que le sentier ... un peu moins brumeux. Petit détail.'::text,'soit'::text,'sera'::text,'est'::text,'Il aimerait sûrement que le sentier soit un peu moins brumeux. Petit détail.'::text),
(373067,41452,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muhtemelen patikanın biraz daha az sisli ... diliyor. Ufak bir detay.'::text,'olmasını'::text,'olacağını'::text,'olduğunu'::text,'Muhtemelen patikanın biraz daha az sisli olmasını diliyor. Ufak bir detay.'::text),
(373068,41452,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Valószínűleg azt szeretné, ha az ösvény ... kicsit kevésbé ködös. Apró részlet.'::text,'lenne'::text,'lesz'::text,NULL::text,'Valószínűleg azt szeretné, ha az ösvény lenne kicsit kevésbé ködös. Apró részlet.'::text),
(373071,41453,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Pfad, ... Ende im Nebel verschwindet, könnte in die totale Katastrophe führen!'::text,'dessen'::text,'der'::text,'wo'::text,'Der Pfad, dessen Ende im Nebel verschwindet, könnte in die totale Katastrophe führen!'::text),
(373075,41453,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стежка, ... кінець зникає в тумані, може привести до повної катастрофи!'::text,'чий'::text,'яка'::text,'де'::text,'Стежка, чий кінець зникає в тумані, може привести до повної катастрофи!'::text),
(373074,41453,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El sendero, ... final desaparece en la niebla, podría llevar al desastre total!'::text,'cuyo'::text,'que'::text,'donde'::text,'¡El sendero, cuyo final desaparece en la niebla, podría llevar al desastre total!'::text),
(373073,41453,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sentier, ... la fin disparaît dans le brouillard, pourrait mener à la catastrophe totale !'::text,'dont'::text,'qui'::text,'où'::text,'Le sentier, dont la fin disparaît dans le brouillard, pourrait mener à la catastrophe totale !'::text),
(373076,41453,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sonu sisin içinde kaybolan patika, tam bir felakete yol açabilir!'::text,''::text,NULL::text,NULL::text,'Sonu sisin içinde kaybolan patika, tam bir felakete yol açabilir!'::text),
(373077,41453,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ösvény, ... vége eltűnik a ködben, teljes katasztrófához vezethet!'::text,'amelynek'::text,'amely'::text,'ahol'::text,'Az ösvény, amelynek vége eltűnik a ködben, teljes katasztrófához vezethet!'::text),
(373080,41454,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der schmale Pfad zum Felsturm besteht aus ..., nicht aus Stein.'::text,'Erde'::text,'einer Erde'::text,'den Erden'::text,'Der schmale Pfad zum Felsturm besteht aus Erde, nicht aus Stein.'::text),
(373084,41454,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вузька стежка до скельної вежі зроблена з ... землі, а не з каменю.'::text,''::text,NULL::text,NULL::text,'Вузька стежка до скельної вежі зроблена з землі, а не з каменю.'::text),
(373083,41454,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El estrecho sendero hacia la torre de roca está hecho de ..., no de piedra.'::text,'tierra'::text,'una tierra'::text,'las tierras'::text,'El estrecho sendero hacia la torre de roca está hecho de tierra, no de piedra.'::text),
(373082,41454,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sentier étroit vers la tour rocheuse est fait de ..., pas de pierre.'::text,'terre'::text,'une terre'::text,'les terres'::text,'Le sentier étroit vers la tour rocheuse est fait de terre, pas de pierre.'::text),
(373085,41454,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaya kulesine giden dar patika taştan değil, ... topraktan yapılmış.'::text,''::text,'bir'::text,NULL::text,'Kaya kulesine giden dar patika taştan değil, topraktan yapılmış.'::text),
(373086,41454,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sziklatoronyhoz vezető keskeny ösvény ..., nem kőből van.'::text,'földből'::text,'egy földből'::text,'a földekből'::text,'A sziklatoronyhoz vezető keskeny ösvény földből, nem kőből van.'::text),
(373098,41456,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag wird er das Ende des Pfads ...'::text,'erreicht haben'::text,'erreichen'::text,'erreicht'::text,'Bis Mittag wird er das Ende des Pfads erreicht haben.'::text),
(373102,41456,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня він ... кінця стежки.'::text,'дійде'::text,'дійде'::text,'доходить'::text,'До полудня він дійде кінця стежки.'::text),
(373101,41456,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, ... al final del sendero.'::text,'habrá llegado'::text,'llegará'::text,'llega'::text,'Para el mediodía, habrá llegado al final del sendero.'::text),
(373100,41456,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, il ... au bout du sentier.'::text,'sera arrivé'::text,'arrivera'::text,'arrive'::text,'D''ici midi, il sera arrivé au bout du sentier.'::text),
(373103,41456,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar patikanın sonuna ...'::text,'varmış olacak'::text,'varacak'::text,'varıyor'::text,'Öğlene kadar patikanın sonuna varmış olacak.'::text),
(373104,41456,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre ... az ösvény végére.'::text,'oda fog érni'::text,'oda fog érni'::text,'odaér'::text,'Délre oda fog érni az ösvény végére.'::text),
(365394,40600,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok also, ich hab gehört, sie ... gerade am See, als die Sonne rauskam.'::text,'lagen'::text,'lagen'::text,'lagen'::text,'Ok also, ich hab gehört, sie lagen gerade am See, als die Sonne rauskam.'::text),
(365398,40600,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що вони ... біля озера, коли вийшло сонце.'::text,'лежали'::text,'лежали'::text,'лежали'::text,'Коротше, я чула, що вони лежали біля озера, коли вийшло сонце.'::text),
(365397,40600,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bueno, oí que ... junto al lago cuando salió el sol.'::text,'estaban tumbados'::text,'se tumbaron'::text,'han estado tumbados'::text,'Bueno, oí que estaban tumbados junto al lago cuando salió el sol.'::text),
(365396,40600,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, j''ai entendu qu''ils ... au bord du lac quand le soleil est sorti.'::text,'étaient allongés'::text,'se sont allongés'::text,'ont été allongés'::text,'Bon alors, j''ai entendu qu''ils étaient allongés au bord du lac quand le soleil est sorti.'::text),
(365399,40600,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, duydum ki güneş çıktığında göl kenarında ...'::text,'uzanıyorlarmış'::text,'uzanmışlar'::text,'uzanmışlar'::text,'Neyse, duydum ki güneş çıktığında göl kenarında uzanıyorlarmış.'::text),
(365400,40600,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt hallottam, hogy éppen a tó partján ..., amikor kisütött a nap.'::text,'feküdtek'::text,'feküdtek'::text,'feküdtek'::text,'Szóval azt hallottam, hogy éppen a tó partján feküdtek, amikor kisütött a nap.'::text),
(365403,40601,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Gras trockener wäre, würden sich mehr Freunde neben den See ...'::text,'legen'::text,'legen'::text,'legen'::text,'Wenn das Gras trockener wäre, würden sich mehr Freunde neben den See legen.'::text),
(365407,40601,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби трава була сухішою, більше друзів ... біля озера.'::text,'лягло б'::text,'ляже'::text,'лягає'::text,'Якби трава була сухішою, більше друзів лягло б біля озера.'::text),
(365406,40601,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la hierba estuviera más seca, más amigos se ... junto al lago.'::text,'tumbarían'::text,'tumbarán'::text,'tumban'::text,'Si la hierba estuviera más seca, más amigos se tumbarían junto al lago.'::text),
(365405,40601,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''herbe était plus sèche, plus d''amis ... à côté du lac.'::text,'s''allongeraient'::text,'s''allongeront'::text,'s''allongent'::text,'Si l''herbe était plus sèche, plus d''amis s''allongeraient à côté du lac.'::text),
(365408,40601,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çimen daha kuru olsaydı, daha fazla arkadaş gölün yanına ...'::text,'uzanırdı'::text,'uzanacak'::text,'uzanıyor'::text,'Çimen daha kuru olsaydı, daha fazla arkadaş gölün yanına uzanırdı.'::text),
(365409,40601,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha szárazabb lenne a fű, több barát ... le a tó mellé.'::text,'feküdne'::text,'fog feküdni'::text,'fekszik'::text,'Ha szárazabb lenne a fű, több barát feküdne le a tó mellé.'::text),
(365421,40603,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fünf junge Männer ... auf dem Rücken neben dem See.'::text,'liegen'::text,'werden gelegen'::text,'liegend'::text,'Fünf junge Männer liegen auf dem Rücken neben dem See.'::text),
(365425,40603,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'П''ятеро юнаків ... на спині біля озера.'::text,'лежать'::text,'лежать'::text,'лежачи'::text,'П''ятеро юнаків лежать на спині біля озера.'::text),
(365424,40603,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cinco chicos ... boca arriba junto al lago.'::text,'están tumbados'::text,'son tumbados'::text,'tumbados'::text,'Cinco chicos están tumbados boca arriba junto al lago.'::text),
(365423,40603,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cinq jeunes hommes ... sur le dos au bord du lac.'::text,'sont allongés'::text,'sont étendus'::text,'allongés'::text,'Cinq jeunes hommes sont allongés sur le dos au bord du lac.'::text),
(365426,40603,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beş genç adam gölün yanında sırt üstü ...'::text,'uzanıyor'::text,'uzatılıyor'::text,'uzanarak'::text,'Beş genç adam gölün yanında sırt üstü uzanıyor.'::text),
(365427,40603,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öt fiatal férfi a hátán ... a tó mellett.'::text,'fekszik'::text,'fekszik'::text,'fekve'::text,'Öt fiatal férfi a hátán fekszik a tó mellett.'::text),
(365430,40604,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ihr ... die entspanntesten Typen überhaupt sein, wie ihr da am See liegt.'::text,'müsst'::text,'könnt nicht'::text,'dürft nicht'::text,'Ehrlich, ihr müsst die entspanntesten Typen überhaupt sein, wie ihr da am See liegt.'::text),
(365434,40604,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ви ... бути найрозслабленішими хлопцями у світі, як отак лежите біля озера.'::text,'мусите'::text,'не можете'::text,'не повинні'::text,'Чесно, ви мусите бути найрозслабленішими хлопцями у світі, як отак лежите біля озера.'::text),
(365433,40604,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... ser los chicos más relajados del mundo, ahí tumbados junto al lago.'::text,'debéis de'::text,'no podéis'::text,'no debéis'::text,'Sinceramente, debéis de ser los chicos más relajados del mundo, ahí tumbados junto al lago.'::text),
(365432,40604,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, vous ... être les mecs les plus détendus du monde, allongés là au bord du lac.'::text,'devez'::text,'ne pouvez pas'::text,'ne devez pas'::text,'Franchement, vous devez être les mecs les plus détendus du monde, allongés là au bord du lac.'::text),
(365435,40604,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, orada gölün kenarında öyle uzanırken dünyanın en rahat çocukları ...'::text,'olmalısınız'::text,'olamazsınız'::text,'olmamalısınız'::text,'Açıkçası, orada gölün kenarında öyle uzanırken dünyanın en rahat çocukları olmalısınız.'::text),
(365436,40604,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ti ... a világ legnyugisabb srácai vagytok, ahogy ott fekszetek a tó mellett.'::text,'biztosan'::text,'biztosan nem'::text,'semmiképp sem'::text,'Őszintén, ti biztosan a világ legnyugisabb srácai vagytok, ahogy ott fekszetek a tó mellett.'::text),
(365439,40605,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hügel, ... sie im Gras lagen, war natürlich ein sehr anstrengender Ort zum Ausruhen.'::text,'wo'::text,'der'::text,'wer'::text,'Der Hügel, wo sie im Gras lagen, war natürlich ein sehr anstrengender Ort zum Ausruhen.'::text),
(365443,40605,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пагорб, ... вони лежали в траві, був, звісно, дуже виснажливим місцем для відпочинку.'::text,'де'::text,'який'::text,'хто'::text,'Пагорб, де вони лежали в траві, був, звісно, дуже виснажливим місцем для відпочинку.'::text),
(365442,40605,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La colina ... estaban tumbados en la hierba era un lugar muy agotador para descansar, obviamente.'::text,'donde'::text,'que'::text,'quien'::text,'La colina donde estaban tumbados en la hierba era un lugar muy agotador para descansar, obviamente.'::text),
(365441,40605,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La colline ... ils étaient allongés dans l''herbe était un endroit très fatigant pour se reposer, évidemment.'::text,'où'::text,'que'::text,'qui'::text,'La colline où ils étaient allongés dans l''herbe était un endroit très fatigant pour se reposer, évidemment.'::text),
(365444,40605,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... çimenlere uzandıkları tepe, tabii ki dinlenmek için çok yorucu bir yerdi.'::text,''::text,NULL::text,NULL::text,'Çimenlere uzandıkları tepe, tabii ki dinlenmek için çok yorucu bir yerdi.'::text),
(365445,40605,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A domb, ... a fűben feküdtek, nyilván nagyon fárasztó hely volt a pihenésre.'::text,'ahol'::text,'amely'::text,'aki'::text,'A domb, ahol a fűben feküdtek, nyilván nagyon fárasztó hely volt a pihenésre.'::text),
(365448,40606,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Freund sagte, sie hätten am Tag davor stundenlang im Gras ...'::text,'gelegen'::text,'gelegt'::text,'gelegen'::text,'Ein Freund sagte, sie hätten am Tag davor stundenlang im Gras gelegen.'::text),
(365452,40606,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Один друг сказав, що напередодні вони ... в траві годинами.'::text,'лежали'::text,'поклали'::text,'лежали'::text,'Один друг сказав, що напередодні вони лежали в траві годинами.'::text),
(365451,40606,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un amigo dijo que el día anterior ... en la hierba durante horas.'::text,'habían estado tumbados'::text,'habían puesto'::text,'han estado tumbados'::text,'Un amigo dijo que el día anterior habían estado tumbados en la hierba durante horas.'::text),
(365450,40606,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un ami a dit qu''ils ... dans l''herbe pendant des heures la veille.'::text,'étaient restés allongés'::text,'avaient posé'::text,'sont restés allongés'::text,'Un ami a dit qu''ils étaient restés allongés dans l''herbe pendant des heures la veille.'::text),
(365453,40606,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir arkadaş, bir önceki gün saatlerce çimende ... söyledi.'::text,'uzandıklarını'::text,'koyduklarını'::text,'uzandıklarını'::text,'Bir arkadaş, bir önceki gün saatlerce çimende uzandıklarını söyledi.'::text),
(365454,40606,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyik barát azt mondta, hogy előző nap órákig ... a fűben.'::text,'feküdtek'::text,'lefektettek'::text,'feküdtek'::text,'Az egyik barát azt mondta, hogy előző nap órákig feküdtek a fűben.'::text),
(365457,40607,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Teenager ... die Freunde jeden Sommer an diesem See.'::text,'lagen'::text,'lagen früher'::text,'waren es gewohnt zu liegen'::text,'Als Teenager lagen die Freunde jeden Sommer an diesem See.'::text),
(365461,40607,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Підлітками друзі ... біля цього озера щоліта.'::text,'лежали'::text,'лежали'::text,'звикли лежати'::text,'Підлітками друзі лежали біля цього озера щоліта.'::text),
(365460,40607,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De adolescentes, los amigos ... tumbarse junto a este lago cada verano.'::text,'solían'::text,'solían'::text,'estaban acostumbrados a'::text,'De adolescentes, los amigos solían tumbarse junto a este lago cada verano.'::text),
(365459,40607,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ados, les amis ... au bord de ce lac chaque été.'::text,'s''allongeaient'::text,'avaient l''habitude de s''allonger'::text,'étaient habitués à s''allonger'::text,'Ados, les amis s''allongeaient au bord de ce lac chaque été.'::text),
(365462,40607,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gençken arkadaşlar her yaz bu gölün kenarına ...'::text,'uzanırlardı'::text,'uzanırlardı'::text,'uzanmaya alışkındılar'::text,'Gençken arkadaşlar her yaz bu gölün kenarına uzanırlardı.'::text),
(365463,40607,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tinédzserként a barátok minden nyáron ennél a tónál ...'::text,'feküdtek'::text,'szoktak feküdni'::text,'hozzá voltak szokva, hogy feküdjenek'::text,'Tinédzserként a barátok minden nyáron ennél a tónál feküdtek.'::text),
(365466,40608,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Freunde genießen es, im hohen Gras über den Feldern ...'::text,'zu liegen'::text,'zu liegen'::text,'zu legen'::text,'Die Freunde genießen es, im hohen Gras über den Feldern zu liegen.'::text),
(365470,40608,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Друзям подобається ... у високій траві над полями.'::text,'лежати'::text,'лежати'::text,'класти'::text,'Друзям подобається лежати у високій траві над полями.'::text),
(365469,40608,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A los amigos les encanta ... en la hierba alta sobre los campos.'::text,'tumbarse'::text,'tumbarse'::text,'poner'::text,'A los amigos les encanta tumbarse en la hierba alta sobre los campos.'::text),
(365468,40608,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les amis adorent ... dans les hautes herbes au-dessus des champs.'::text,'s''allonger'::text,'s''allonger'::text,'poser'::text,'Les amis adorent s''allonger dans les hautes herbes au-dessus des champs.'::text),
(365471,40608,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşlar tarlaların üstündeki uzun çimenlerde ... seviyor.'::text,'uzanmayı'::text,'uzanmayı'::text,'koymayı'::text,'Arkadaşlar tarlaların üstündeki uzun çimenlerde uzanmayı seviyor.'::text),
(365472,40608,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátok élvezik, hogy ... a magas fűben a mezők fölött.'::text,'fekszenek'::text,'fekszenek'::text,'fektetnek'::text,'A barátok élvezik, hogy fekszenek a magas fűben a mezők fölött.'::text),
(365484,40610,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den ganzen Nachmittag im Gras, und niemand bewegte auch nur einen Muskel!'::text,'lagen'::text,'legten'::text,'legten'::text,'Sie lagen den ganzen Nachmittag im Gras, und niemand bewegte auch nur einen Muskel!'::text),
(365488,40610,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... на траві все пообіддя, і ніхто не поворухнув жодним м''язом!'::text,'лежали'::text,'клали'::text,'клали'::text,'Вони лежали на траві все пообіддя, і ніхто не поворухнув жодним м''язом!'::text),
(365487,40610,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... en la hierba toda la tarde y nadie movió ni un músculo!'::text,'Estuvieron tumbados'::text,'Pusieron'::text,'Estaban poniendo'::text,'¡Estuvieron tumbados en la hierba toda la tarde y nadie movió ni un músculo!'::text),
(365486,40610,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... sur l''herbe tout l''après-midi, et personne n''a bougé le moindre muscle !'::text,'sont restés allongés'::text,'ont posé'::text,'posaient'::text,'Ils sont restés allongés sur l''herbe tout l''après-midi, et personne n''a bougé le moindre muscle !'::text),
(365489,40610,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün öğleden sonra çimenlerde ... ve kimse tek bir kasını bile oynatmadı!'::text,'uzandılar'::text,'koydular'::text,'koyuyorlardı'::text,'Bütün öğleden sonra çimenlerde uzandılar ve kimse tek bir kasını bile oynatmadı!'::text),
(365490,40610,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész délután ... a füvön, és senki meg sem moccant!'::text,'feküdtek'::text,'lefektettek'::text,'fektettek'::text,'Egész délután feküdtek a füvön, és senki meg sem moccant!'::text),
(334632,37182,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Waschbär ... schon den ganzen Morgen in der Mülltonne, also ist er jetzt ein Mülltonnen-Waschbär.'::text,'sitzt'::text,'sitzt'::text,'sitzt'::text,'Der Waschbär sitzt schon den ganzen Morgen in der Mülltonne, also ist er jetzt ein Mülltonnen-Waschbär.'::text),
(334636,37182,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Єнот ... у смітнику весь ранок, тож тепер він смітниковий єнот.'::text,'сидить'::text,'сидить'::text,'сидить'::text,'Єнот сидить у смітнику весь ранок, тож тепер він смітниковий єнот.'::text),
(334635,37182,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mapache ... en el cubo de basura toda la mañana, así que ahora es un mapache de cubo.'::text,'ha estado sentado'::text,'está sentado'::text,'se sienta'::text,'El mapache ha estado sentado en el cubo de basura toda la mañana, así que ahora es un mapache de cubo.'::text),
(334634,37182,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le raton laveur ... dans la poubelle depuis ce matin, donc c''est un raton de poubelle maintenant.'::text,'est assis'::text,'est assis'::text,'s''assoit'::text,'Le raton laveur est assis dans la poubelle depuis ce matin, donc c''est un raton de poubelle maintenant.'::text),
(334637,37182,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rakun bütün sabah çöp kutusunda ..., yani artık o bir çöp kutusu rakunu.'::text,'oturuyor'::text,'oturuyor'::text,'oturur'::text,'Rakun bütün sabah çöp kutusunda oturuyor, yani artık o bir çöp kutusu rakunu.'::text),
(334638,37182,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mosómedve egész délelőtt a kukában ..., szóval most már kukamosómedve.'::text,'ül'::text,'ül'::text,'ül'::text,'A mosómedve egész délelőtt a kukában ül, szóval most már kukamosómedve.'::text),
(334641,37183,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stell dir vor, er hat mir erzählt, der Waschbär ... gerade die Wand der Tonne hoch, als er den Deckel anhob.'::text,'kletterte'::text,'kletterte'::text,'klettert'::text,'Stell dir vor, er hat mir erzählt, der Waschbär kletterte gerade die Wand der Tonne hoch, als er den Deckel anhob.'::text),
(334645,37183,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, він сказав мені, що єнот ... по стінці смітника, коли він підняв кришку.'::text,'дерся'::text,'виліз'::text,'виліз'::text,'Уяви, він сказав мені, що єнот дерся по стінці смітника, коли він підняв кришку.'::text),
(334644,37183,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fíjate, me dijo que el mapache ... por la pared del cubo cuando levantó la tapa.'::text,'estaba trepando'::text,'trepó'::text,'ha trepado'::text,'Fíjate, me dijo que el mapache estaba trepando por la pared del cubo cuando levantó la tapa.'::text),
(334643,37183,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute ça, il m''a dit que le raton ... le long de la paroi de la poubelle quand il a soulevé le couvercle.'::text,'grimpait'::text,'a grimpé'::text,'a grimpé'::text,'Écoute ça, il m''a dit que le raton grimpait le long de la paroi de la poubelle quand il a soulevé le couvercle.'::text),
(334646,37183,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şuna bak, kapağı kaldırdığında rakunun çöp kutusunun duvarına ... bana söyledi.'::text,'tırmanmakta olduğunu'::text,'tırmandığını'::text,'tırmandığını'::text,'Şuna bak, kapağı kaldırdığında rakunun çöp kutusunun duvarına tırmanmakta olduğunu bana söyledi.'::text),
(334647,37183,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta, hogy a mosómedve éppen ... a kuka falán, amikor felemelte a fedelet.'::text,'mászott felfelé'::text,'felmászott'::text,'felmászott'::text,'Képzeld, azt mondta, hogy a mosómedve éppen mászott felfelé a kuka falán, amikor felemelte a fedelet.'::text),
(334650,37184,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay also, angeblich hat dieser Waschbär schon dreimal ..., aus der Tonne rauszukommen.'::text,'versucht'::text,'versucht'::text,'versucht'::text,'Okay also, angeblich hat dieser Waschbär schon dreimal versucht, aus der Tonne rauszukommen.'::text),
(334654,37184,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, цей єнот уже тричі ... вибратися зі смітника.'::text,'пробував'::text,'намагався'::text,'пробував'::text,'Коротше, кажуть, цей єнот уже тричі пробував вибратися зі смітника.'::text),
(334653,37184,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bueno, al parecer este mapache ya ... salir del cubo tres veces.'::text,'ha intentado'::text,'ha estado intentando'::text,'intentó'::text,'Bueno, al parecer este mapache ya ha intentado salir del cubo tres veces.'::text),
(334652,37184,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment ce raton ... de sortir de la poubelle déjà trois fois.'::text,'a essayé'::text,'essaie'::text,'a essayé'::text,'Bon alors, apparemment ce raton a essayé de sortir de la poubelle déjà trois fois.'::text),
(334655,37184,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, duyduğuma göre bu rakun çöp kutusundan çıkmayı şimdiden üç kez ...'::text,'denemiş'::text,'deniyormuş'::text,'denedi'::text,'Neyse, duyduğuma göre bu rakun çöp kutusundan çıkmayı şimdiden üç kez denemiş.'::text),
(334656,37184,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag ez a mosómedve már háromszor ... kijutni a kukából.'::text,'próbált'::text,'próbálkozott'::text,'próbált'::text,'Szóval, állítólag ez a mosómedve már háromszor próbált kijutni a kukából.'::text),
(334659,37185,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als jemand in die Tonne schaute, hatte der Waschbär den Müllsack schon ... – entzückend.'::text,'geöffnet'::text,'geöffnet'::text,'geöffnet'::text,'Als jemand in die Tonne schaute, hatte der Waschbär den Müllsack schon geöffnet – entzückend.'::text),
(334663,37185,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли хтось зазирнув у смітник, єнот уже ... пакет зі сміттям. Чарівно.'::text,'відкрив'::text,'відкрив'::text,'відкриває'::text,'Коли хтось зазирнув у смітник, єнот уже відкрив пакет зі сміттям. Чарівно.'::text),
(334662,37185,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando alguien miró en el cubo, el mapache ya ... la bolsa de basura. Encantador.'::text,'había abierto'::text,'ha abierto'::text,'abre'::text,'Para cuando alguien miró en el cubo, el mapache ya había abierto la bolsa de basura. Encantador.'::text),
(334661,37185,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand quelqu''un a regardé dans la poubelle, le raton ... le sac poubelle. Charmant.'::text,'avait ouvert'::text,'a ouvert'::text,'ouvre'::text,'Quand quelqu''un a regardé dans la poubelle, le raton avait ouvert le sac poubelle. Charmant.'::text),
(334664,37185,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri çöp kutusuna baktığında rakun çöp poşetini çoktan ..., ne hoş.'::text,'açmıştı'::text,'açtı'::text,'açıyor'::text,'Biri çöp kutusuna baktığında rakun çöp poşetini çoktan açmıştı, ne hoş.'::text),
(334665,37185,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire valaki belenézett a kukába, a mosómedve már ... a szemeteszsákot. Elbűvölő.'::text,'kinyitotta'::text,'kinyitotta'::text,'kinyitja'::text,'Mire valaki belenézett a kukába, a mosómedve már kinyitotta a szemeteszsákot. Elbűvölő.'::text),
(334668,37186,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn niemand die Tonne umkippt, ... der Waschbär den ganzen Tag drin.'::text,'bleibt'::text,'würde bleiben'::text,'blieb'::text,'Wenn niemand die Tonne umkippt, bleibt der Waschbär den ganzen Tag drin.'::text),
(334672,37186,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ніхто не перекине смітник, єнот ... всередині весь день.'::text,'залишиться'::text,'залишився б'::text,'залишився'::text,'Якщо ніхто не перекине смітник, єнот залишиться всередині весь день.'::text),
(334671,37186,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si nadie vuelca el cubo, el mapache se ... dentro todo el día.'::text,'quedará'::text,'quedaría'::text,'quedó'::text,'Si nadie vuelca el cubo, el mapache se quedará dentro todo el día.'::text),
(334670,37186,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si personne ne renverse la poubelle, le raton ... dedans toute la journée.'::text,'restera'::text,'resterait'::text,'est resté'::text,'Si personne ne renverse la poubelle, le raton restera dedans toute la journée.'::text),
(334673,37186,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse çöp kutusunu devirmezse, rakun bütün gün içeride ...'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Kimse çöp kutusunu devirmezse, rakun bütün gün içeride kalacak.'::text),
(334674,37186,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha senki nem dönti fel a kukát, a mosómedve egész nap bent ...'::text,'marad'::text,'maradna'::text,'maradt'::text,'Ha senki nem dönti fel a kukát, a mosómedve egész nap bent marad.'::text),
(334686,37188,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Tonne wurde gestern Abend auf den Weg ..., und ein Waschbär kletterte hinein.'::text,'gestellt'::text,'gestellt'::text,'gestellt'::text,'Die Tonne wurde gestern Abend auf den Weg gestellt, und ein Waschbär kletterte hinein.'::text),
(334690,37188,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Смітник ... на доріжку вчора ввечері, і туди заліз єнот.'::text,'виставили'::text,'виставив'::text,'виставляють'::text,'Смітник виставили на доріжку вчора ввечері, і туди заліз єнот.'::text),
(334689,37188,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cubo ... en el camino anoche, y un mapache se metió dentro.'::text,'fue sacado'::text,'sacó'::text,'es sacado'::text,'El cubo fue sacado en el camino anoche, y un mapache se metió dentro.'::text),
(334688,37188,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poubelle ... sur le chemin hier soir, et un raton s''est glissé dedans.'::text,'a été sortie'::text,'a sorti'::text,'est sortie'::text,'La poubelle a été sortie sur le chemin hier soir, et un raton s''est glissé dedans.'::text),
(334691,37188,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çöp kutusu dün akşam patikaya ... ve içine bir rakun tırmandı.'::text,'çıkarıldı'::text,'çıkardı'::text,'çıkarılıyor'::text,'Çöp kutusu dün akşam patikaya çıkarıldı ve içine bir rakun tırmandı.'::text),
(334692,37188,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kukát tegnap este ... az útra, és bemászott egy mosómedve.'::text,'kitették'::text,'kitette'::text,'kiteszik'::text,'A kukát tegnap este kitették az útra, és bemászott egy mosómedve.'::text),
(334695,37189,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Exemplar ..., die glatte Innenwand der Tonne hochzuklettern, rutscht aber zurück.'::text,'versucht'::text,'wird versucht'::text,'versuchend'::text,'Das Exemplar versucht, die glatte Innenwand der Tonne hochzuklettern, rutscht aber zurück.'::text),
(334699,37189,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Особина ... вилізти по гладкій внутрішній стінці смітника, але зісковзує назад.'::text,'намагається'::text,'намагається'::text,'намагаючись'::text,'Особина намагається вилізти по гладкій внутрішній стінці смітника, але зісковзує назад.'::text),
(334698,37189,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El espécimen ... trepar por la pared interior lisa del cubo, pero resbala.'::text,'intenta'::text,'es intentado'::text,'intentando'::text,'El espécimen intenta trepar por la pared interior lisa del cubo, pero resbala.'::text),
(334697,37189,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le spécimen ... d''escalader la paroi intérieure lisse de la poubelle, mais glisse.'::text,'tente'::text,'est tenté'::text,'tentant'::text,'Le spécimen tente d''escalader la paroi intérieure lisse de la poubelle, mais glisse.'::text),
(334700,37189,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek çöp kutusunun pürüzsüz iç duvarına tırmanmaya ... ama geri kayıyor.'::text,'çalışıyor'::text,'çalışılıyor'::text,'çalışarak'::text,'Denek çöp kutusunun pürüzsüz iç duvarına tırmanmaya çalışıyor ama geri kayıyor.'::text),
(334701,37189,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A példány ... felmászni a kuka sima belső falán, de visszacsúszik.'::text,'megpróbál'::text,'megpróbáltatik'::text,'próbálva'::text,'A példány megpróbál felmászni a kuka sima belső falán, de visszacsúszik.'::text),
(334704,37190,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Exemplar ... gefangen sein, da die glatte Wand der Tonne keinen Halt bietet.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Das Exemplar muss gefangen sein, da die glatte Wand der Tonne keinen Halt bietet.'::text),
(334708,37190,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Особина ... бути в пастці, бо гладка стінка смітника не дає жодної опори.'::text,'мусить'::text,'не може'::text,'мала б'::text,'Особина мусить бути в пастці, бо гладка стінка смітника не дає жодної опори.'::text),
(334707,37190,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El espécimen ... estar atrapado, ya que la pared lisa del cubo no ofrece agarre.'::text,'debe de'::text,'no puede'::text,'debería'::text,'El espécimen debe de estar atrapado, ya que la pared lisa del cubo no ofrece agarre.'::text),
(334706,37190,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le spécimen ... être piégé, car la paroi lisse de la poubelle n''offre aucune prise.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Le spécimen doit être piégé, car la paroi lisse de la poubelle n''offre aucune prise.'::text),
(334709,37190,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kutunun pürüzsüz duvarı hiç tutunma sağlamadığı için denek mahsur kalmış ...'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Kutunun pürüzsüz duvarı hiç tutunma sağlamadığı için denek mahsur kalmış olmalı.'::text),
(334710,37190,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A példány ... csapdába esett, mivel a kuka sima fala nem ad kapaszkodót.'::text,'biztosan'::text,'nem'::text,'bizonyára'::text,'A példány biztosan csapdába esett, mivel a kuka sima fala nem ad kapaszkodót.'::text),
(334713,37191,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Tonne, ... das Exemplar nun wohnt, wird typischerweise für Hausmüll verwendet.'::text,'wo'::text,'die'::text,'wer'::text,'Die Tonne, wo das Exemplar nun wohnt, wird typischerweise für Hausmüll verwendet.'::text),
(334717,37191,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Смітник, ... тепер мешкає особина, зазвичай використовується для побутових відходів.'::text,'де'::text,'який'::text,'хто'::text,'Смітник, де тепер мешкає особина, зазвичай використовується для побутових відходів.'::text),
(334716,37191,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cubo, ... ahora reside el espécimen, se usa normalmente para residuos domésticos.'::text,'donde'::text,'que'::text,'quien'::text,'El cubo, donde ahora reside el espécimen, se usa normalmente para residuos domésticos.'::text),
(334715,37191,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poubelle, ... réside désormais le spécimen, sert généralement aux déchets ménagers.'::text,'où'::text,'que'::text,'qui'::text,'La poubelle, où réside désormais le spécimen, sert généralement aux déchets ménagers.'::text),
(334718,37191,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... deneğin şu an ikamet ettiği çöp kutusu, genellikle evsel atıklar için kullanılır.'::text,''::text,NULL::text,NULL::text,'Deneğin şu an ikamet ettiği çöp kutusu, genellikle evsel atıklar için kullanılır.'::text),
(334719,37191,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kuka, ... most a példány lakik, általában háztartási hulladékra szolgál.'::text,'ahol'::text,'amely'::text,'aki'::text,'A kuka, ahol most a példány lakik, általában háztartási hulladékra szolgál.'::text),
(348105,38679,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Update: Er verspricht, dass er sich noch 10-mal nach dem Ball ..., bevor das Meeting endet.'::text,'werfen wird'::text,'werfen wird'::text,'wirft'::text,'Update: Er verspricht, dass er sich noch 10-mal nach dem Ball werfen wird, bevor das Meeting endet.'::text),
(348109,38679,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Апдейт: він обіцяє, що ... за м''ячем ще 10 разів до кінця наради.'::text,'кинеться'::text,'кидатиметься'::text,'кидається'::text,'Апдейт: він обіцяє, що кинеться за м''ячем ще 10 разів до кінця наради.'::text),
(348108,38679,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actualización: promete que se ... a por el balón 10 veces más antes de que termine la reunión.'::text,'lanzará'::text,'estará lanzando'::text,'lanza'::text,'Actualización: promete que se lanzará a por el balón 10 veces más antes de que termine la reunión.'::text),
(348107,38679,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mise à jour : il promet qu''il ... sur le ballon encore 10 fois avant la fin de la réunion.'::text,'plongera'::text,'sera en train de plonger'::text,'plonge'::text,'Mise à jour : il promet qu''il plongera sur le ballon encore 10 fois avant la fin de la réunion.'::text),
(348110,38679,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güncelleme: toplantı bitmeden topa 10 kez daha ... söz veriyor.'::text,'atlayacağına'::text,'atlıyor olacağına'::text,'atladığına'::text,'Güncelleme: toplantı bitmeden topa 10 kez daha atlayacağına söz veriyor.'::text),
(348111,38679,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frissítés: megígéri, hogy a megbeszélés vége előtt még tízszer ... a labdáért.'::text,'vetődik'::text,'vetődni fog'::text,'éppen vetődik'::text,'Frissítés: megígéri, hogy a megbeszélés vége előtt még tízszer vetődik a labdáért.'::text),
(348114,38680,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Spieler flach ins Meer hechtet, ... das Wasser in einer großen Fontäne hoch.'::text,'spritzt'::text,'spritzte'::text,'wird'::text,'Wenn ein Spieler flach ins Meer hechtet, spritzt das Wasser in einer großen Fontäne hoch.'::text),
(348118,38680,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо гравець пірнає плазом у море, вода ... вгору великими бризками.'::text,'розлітається'::text,'розлетілася'::text,'розлетиться'::text,'Якщо гравець пірнає плазом у море, вода розлітається вгору великими бризками.'::text),
(348117,38680,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un jugador se lanza en plancha al mar, el agua ... en un gran chapuzón.'::text,'salpica'::text,'salpicó'::text,'salpicará'::text,'Si un jugador se lanza en plancha al mar, el agua salpica en un gran chapuzón.'::text),
(348116,38680,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un joueur plonge à plat dans la mer, l''eau ... en une grande gerbe.'::text,'jaillit'::text,'a jailli'::text,'jaillira'::text,'Si un joueur plonge à plat dans la mer, l''eau jaillit en une grande gerbe.'::text),
(348119,38680,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir oyuncu denize düz atlarsa, su büyük bir şekilde yukarı ...'::text,'sıçrar'::text,'sıçradı'::text,'sıçrayacak'::text,'Bir oyuncu denize düz atlarsa, su büyük bir şekilde yukarı sıçrar.'::text),
(348120,38680,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy játékos hasast ugrik a tengerbe, a víz nagy csobbanással ...'::text,'felfröccsen'::text,'felfröccsent'::text,'fel fog fröccsenni'::text,'Ha egy játékos hasast ugrik a tengerbe, a víz nagy csobbanással felfröccsen.'::text),
(348123,38681,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Freund sagte, dass er sich nach dem Ball ins Wasser ...'::text,'geworfen hatte'::text,'geworfen hat'::text,'wirft'::text,'Sein Freund sagte, dass er sich nach dem Ball ins Wasser geworfen hatte.'::text),
(348127,38681,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його друг сказав, що він ... у воду за м''ячем.'::text,'кинувся'::text,'кинувся'::text,'кидається'::text,'Його друг сказав, що він кинувся у воду за м''ячем.'::text),
(348126,38681,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su amigo dijo que se ... al agua a por el balón.'::text,'había lanzado'::text,'ha lanzado'::text,'lanza'::text,'Su amigo dijo que se había lanzado al agua a por el balón.'::text),
(348125,38681,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son ami a dit qu''il ... dans l''eau pour le ballon.'::text,'avait plongé'::text,'a plongé'::text,'plonge'::text,'Son ami a dit qu''il avait plongé dans l''eau pour le ballon.'::text),
(348128,38681,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşı, onun top için suya ... söyledi.'::text,'atladığını'::text,'atladığını'::text,'atladığını'::text,'Arkadaşı, onun top için suya atladığını söyledi.'::text),
(348129,38681,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátja azt mondta, hogy ... a vízbe a labdáért.'::text,'bevetődött'::text,'bevetődött'::text,'bevetődik'::text,'A barátja azt mondta, hogy bevetődött a vízbe a labdáért.'::text),
(348132,38682,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Jungs ... sie jeden Sommer den ganzen Tag an diesem Strand nach Bällen.'::text,'hechteten'::text,'hechteten früher'::text,'waren es gewohnt zu hechten'::text,'Als Jungs hechteten sie jeden Sommer den ganzen Tag an diesem Strand nach Bällen.'::text),
(348136,38682,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щоліта, ще хлопцями, вони ... за м''ячами на цьому пляжі цілими днями.'::text,'кидалися'::text,'кидалися'::text,'звикли кидатися'::text,'Щоліта, ще хлопцями, вони кидалися за м''ячами на цьому пляжі цілими днями.'::text),
(348135,38682,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada verano, de niños, ... lanzarse a por balones en esta playa todo el día.'::text,'solían'::text,'solían'::text,'estaban acostumbrados a'::text,'Cada verano, de niños, solían lanzarse a por balones en esta playa todo el día.'::text),
(348134,38682,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque été, quand ils étaient gamins, ils ... après les ballons sur cette plage toute la journée.'::text,'plongeaient'::text,'avaient l''habitude de plonger'::text,'étaient habitués à plonger'::text,'Chaque été, quand ils étaient gamins, ils plongeaient après les ballons sur cette plage toute la journée.'::text),
(348137,38682,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken her yaz bu plajda bütün gün toplar için ...'::text,'atlarlardı'::text,'atlarlardı'::text,'atlamaya alışkındılar'::text,'Çocukken her yaz bu plajda bütün gün toplar için atlarlardı.'::text),
(348138,38682,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kisfiúként minden nyáron egész nap ... a labdákért ezen a strandon.'::text,'vetődtek'::text,'vetődni szoktak'::text,'hozzá voltak szokva a vetődéshez'::text,'Kisfiúként minden nyáron egész nap vetődtek a labdákért ezen a strandon.'::text),
(348141,38683,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, er hat mir erzählt, er kann nicht widerstehen, sich nach einem Ball ..., sogar im Meer.'::text,'zu werfen'::text,'zu werfen'::text,'zu werfen'::text,'Rate mal, er hat mir erzählt, er kann nicht widerstehen, sich nach einem Ball zu werfen, sogar im Meer.'::text),
(348145,38683,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, він сказав мені, що не може втриматися, щоб не ... за м''ячем, навіть у морі.'::text,'кинутися'::text,'кинутися'::text,'кинутися'::text,'Уяви, він сказав мені, що не може втриматися, щоб не кинутися за м''ячем, навіть у морі.'::text),
(348144,38683,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, me dijo que no puede resistirse a ... a por un balón, incluso en el mar.'::text,'lanzarse'::text,'lanzarse'::text,'lanzarse'::text,'Adivina qué, me dijo que no puede resistirse a lanzarse a por un balón, incluso en el mar.'::text),
(348143,38683,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, il m''a dit qu''il ne peut pas s''empêcher de ... pour un ballon, même dans la mer.'::text,'plonger'::text,'plonger'::text,'plonger'::text,'Devine quoi, il m''a dit qu''il ne peut pas s''empêcher de plonger pour un ballon, même dans la mer.'::text),
(348146,38683,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, bana bir top için ... karşı koyamadığını söyledi, denizde bile.'::text,'atlamaya'::text,'atlamaya'::text,'atlamaya'::text,'Bil bakalım, bana bir top için atlamaya karşı koyamadığını söyledi, denizde bile.'::text),
(348147,38683,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta, nem tud ellenállni a ... egy labdáért, még a tengerben sem.'::text,'vetődésnek'::text,'vetődésnek'::text,'vetődésnek'::text,'Képzeld, azt mondta, nem tud ellenállni a vetődésnek egy labdáért, még a tengerben sem.'::text),
(348150,38684,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du hast dich wie ein Profi nach dem Ball geworfen, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Respekt, du hast dich wie ein Profi nach dem Ball geworfen, oder?'::text),
(348154,38684,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти кинувся за тим м''ячем як профі, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Респект, ти кинувся за тим м''ячем як профі, так?'::text),
(348153,38684,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, te lanzaste a por ese balón como un pro, ...?'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'Respeto, te lanzaste a por ese balón como un pro, ¿verdad?'::text),
(348152,38684,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, tu as plongé sur ce ballon comme un pro, ... ?'::text,'hein ?'::text,'hein ?'::text,'hein ?'::text,'Respect, tu as plongé sur ce ballon comme un pro, hein ?'::text),
(348155,38684,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygı, o topa profesyonel gibi atladın, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Saygı, o topa profesyonel gibi atladın, değil mi?'::text),
(348156,38684,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, úgy vetődtél arra a labdára, mint egy profi, ...?'::text,'nem?'::text,'nem?'::text,'nem?'::text,'Respekt, úgy vetődtél arra a labdára, mint egy profi, nem?'::text),
(348159,38685,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hattest keine Angst, dich nach dem Ball zu werfen, und dein Kumpel ..., ganz ehrlich.'::text,'auch nicht'::text,'auch'::text,'auch nicht'::text,'Du hattest keine Angst, dich nach dem Ball zu werfen, und dein Kumpel auch nicht, ganz ehrlich.'::text),
(348163,38685,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти не боявся кинутися за тим м''ячем, і твій друг ..., чесно.'::text,'теж ні'::text,'теж'::text,'теж ні'::text,'Ти не боявся кинутися за тим м''ячем, і твій друг теж ні, чесно.'::text),
(348162,38685,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te dio miedo lanzarte a por ese balón, y a tu amigo ..., la verdad.'::text,'tampoco'::text,'también'::text,'tampoco'::text,'No te dio miedo lanzarte a por ese balón, y a tu amigo tampoco, la verdad.'::text),
(348161,38685,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu n''avais pas peur de plonger sur ce ballon, et ton pote ..., sans mentir.'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Tu n''avais pas peur de plonger sur ce ballon, et ton pote non plus, sans mentir.'::text),
(348164,38685,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O top için atlamaktan korkmadın, arkadaşın da ..., yalan yok.'::text,'korkmadı'::text,'korktu'::text,'korkmadı'::text,'O top için atlamaktan korkmadın, arkadaşın da korkmadı, yalan yok.'::text),
(348165,38685,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem féltél vetődni arra a labdára, és a barátod ..., nem hazudok.'::text,'sem félt'::text,'is félt'::text,'sem félt'::text,'Nem féltél vetődni arra a labdára, és a barátod sem félt, nem hazudok.'::text),
(348177,38687,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zum dritten Mal ... er sich für einen einzigen Ball ins Meer. Spitzenleistung.'::text,'wirft'::text,'wirft'::text,'wirft'::text,'Zum dritten Mal wirft er sich für einen einzigen Ball ins Meer. Spitzenleistung.'::text),
(348181,38687,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це вже втретє він ... в море за одним м''ячем. Пік продуктивності.'::text,'кидається'::text,'кидається'::text,'кидається'::text,'Це вже втретє він кидається в море за одним м''ячем. Пік продуктивності.'::text),
(348180,38687,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es la tercera vez que se ... al mar por un solo balón. Rendimiento máximo.'::text,'ha lanzado'::text,'está lanzando'::text,'lanza'::text,'Es la tercera vez que se ha lanzado al mar por un solo balón. Rendimiento máximo.'::text),
(348179,38687,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est la troisième fois qu''il ... dans la mer pour un seul ballon. Performance au top.'::text,'plonge'::text,'plonge'::text,'plonge'::text,'C''est la troisième fois qu''il plonge dans la mer pour un seul ballon. Performance au top.'::text),
(348182,38687,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tek bir top için denize üçüncü kez ..., zirve performans.'::text,'atlıyor'::text,'atlıyor'::text,'atlar'::text,'Tek bir top için denize üçüncü kez atlıyor, zirve performans.'::text),
(348183,38687,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már harmadszor ... a tengerbe egyetlen labdáért. Csúcsteljesítmény.'::text,'vetődik'::text,'vetődik'::text,'vetődik'::text,'Már harmadszor vetődik a tengerbe egyetlen labdáért. Csúcsteljesítmény.'::text),
(348186,38688,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, er ... sich ins Wasser und haute dann einen Fallrückzieher raus, einfach krank.'::text,'warf'::text,'warf'::text,'warf gerade'::text,'Yo, er warf sich ins Wasser und haute dann einen Fallrückzieher raus, einfach krank.'::text),
(348190,38688,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, він ... у воду, а потім зробив ножиці — реально легенда.'::text,'кинувся'::text,'кинувся'::text,'кидався'::text,'Йо, він кинувся у воду, а потім зробив ножиці — реально легенда.'::text),
(348189,38688,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, se ... al agua y luego se marcó una chilena, un crack total.'::text,'lanzó'::text,'había lanzado'::text,'estaba lanzando'::text,'Ey, se lanzó al agua y luego se marcó una chilena, un crack total.'::text),
(348188,38688,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, il ... dans l''eau et puis il a sorti un retourné, trop fort.'::text,'a plongé'::text,'avait plongé'::text,'plongeait'::text,'Yo, il a plongé dans l''eau et puis il a sorti un retourné, trop fort.'::text),
(348191,38688,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, suya ..., sonra bir rövaşata çekti, resmen efsane.'::text,'atladı'::text,'atlamıştı'::text,'atlıyordu'::text,'Yo, suya atladı, sonra bir rövaşata çekti, resmen efsane.'::text),
(348192,38688,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... a vízbe, aztán bedobott egy ollózást, tök királyság.'::text,'bevetődött'::text,'bevetődött'::text,'vetődött'::text,'Tesó, bevetődött a vízbe, aztán bedobott egy ollózást, tök királyság.'::text),
(351165,39019,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist erschöpft, weil er den ganzen Nachmittag ...'::text,'gelaufen ist'::text,'läuft'::text,'läuft'::text,'Er ist erschöpft, weil er den ganzen Nachmittag gelaufen ist.'::text),
(351169,39019,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він виснажений, бо ... все пообіддя.'::text,'бігав'::text,'біжить'::text,'бігає'::text,'Він виснажений, бо бігав все пообіддя.'::text),
(351168,39019,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está agotado porque ... toda la tarde.'::text,'ha estado corriendo'::text,'está corriendo'::text,'corre'::text,'Está agotado porque ha estado corriendo toda la tarde.'::text),
(351167,39019,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est épuisé parce qu''il ... tout l''après-midi.'::text,'a couru'::text,'court'::text,'court'::text,'Il est épuisé parce qu''il a couru tout l''après-midi.'::text),
(351170,39019,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün öğleden sonra ... için bitkin.'::text,'koştuğu'::text,'koşuyor'::text,'koşar'::text,'Bütün öğleden sonra koştuğu için bitkin.'::text),
(351171,39019,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimerült, mert egész délután ...'::text,'futott'::text,'fut'::text,'fut'::text,'Kimerült, mert egész délután futott.'::text),
(351174,39020,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der erschöpfte Mann ... sein Sweatshirt aus, rannte ins Wasser und ließ sich mit dem Gesicht nach unten fallen.'::text,'zog'::text,'zog gerade'::text,'zog'::text,'Der erschöpfte Mann zog sein Sweatshirt aus, rannte ins Wasser und ließ sich mit dem Gesicht nach unten fallen.'::text),
(351178,39020,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Виснажений чоловік ... світшот, забіг у воду й упав обличчям донизу.'::text,'стягнув'::text,'стягував'::text,'стягнув'::text,'Виснажений чоловік стягнув світшот, забіг у воду й упав обличчям донизу.'::text),
(351177,39020,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre agotado se ... la sudadera, corrió al agua y se dejó caer boca abajo.'::text,'quitó'::text,'estaba quitando'::text,'ha quitado'::text,'El hombre agotado se quitó la sudadera, corrió al agua y se dejó caer boca abajo.'::text),
(351176,39020,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme épuisé ... son sweat-shirt, a couru dans l''eau et s''est laissé tomber à plat ventre.'::text,'a retiré'::text,'retirait'::text,'a retiré'::text,'L''homme épuisé a retiré son sweat-shirt, a couru dans l''eau et s''est laissé tomber à plat ventre.'::text),
(351179,39020,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bitkin adam sweatshirt''ünü ..., suya koştu ve yüzüstü düştü.'::text,'çıkardı'::text,'çıkarıyordu'::text,'çıkardı'::text,'Bitkin adam sweatshirt''ünü çıkardı, suya koştu ve yüzüstü düştü.'::text),
(351180,39020,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kimerült férfi ... a pulcsiját, beszaladt a vízbe, és hasra vágódott.'::text,'lehúzta'::text,'húzta le'::text,'lehúzta'::text,'A kimerült férfi lehúzta a pulcsiját, beszaladt a vízbe, és hasra vágódott.'::text),
(351183,39021,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre er nicht so erschöpft gewesen, hätte er seine Sneaker ..., bevor er sich ins Meer legte.'::text,'ausgezogen'::text,'ausziehen'::text,'auszog'::text,'Wäre er nicht so erschöpft gewesen, hätte er seine Sneaker ausgezogen, bevor er sich ins Meer legte.'::text),
(351187,39021,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не був таким виснаженим, він ... кросівки, перш ніж лягти в море.'::text,'зняв би'::text,'зняв би'::text,'зняв'::text,'Якби він не був таким виснаженим, він зняв би кросівки, перш ніж лягти в море.'::text),
(351186,39021,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera estado tan agotado, se ... las zapatillas antes de tumbarse en el mar.'::text,'habría quitado'::text,'quitaría'::text,'quitó'::text,'Si no hubiera estado tan agotado, se habría quitado las zapatillas antes de tumbarse en el mar.'::text),
(351185,39021,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas été si épuisé, il ... ses baskets avant de s''allonger dans la mer.'::text,'aurait enlevé'::text,'enlèverait'::text,'a enlevé'::text,'S''il n''avait pas été si épuisé, il aurait enlevé ses baskets avant de s''allonger dans la mer.'::text),
(351188,39021,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kadar bitkin olmasaydı, denize uzanmadan önce spor ayakkabılarını ...'::text,'çıkarırdı'::text,'çıkarırdı'::text,'çıkardı'::text,'Bu kadar bitkin olmasaydı, denize uzanmadan önce spor ayakkabılarını çıkarırdı.'::text),
(351189,39021,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem lett volna ennyire kimerült, ... a cipőjét, mielőtt belefeküdt a tengerbe.'::text,'levette volna'::text,'levenné'::text,'levette'::text,'Ha nem lett volna ennyire kimerült, levette volna a cipőjét, mielőtt belefeküdt a tengerbe.'::text),
(351192,39022,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er gab zu, nach der schlimmsten Woche seines Lebens völlig erschöpft ...!'::text,'zu sein'::text,'zu sein'::text,'war'::text,'Er gab zu, nach der schlimmsten Woche seines Lebens völlig erschöpft zu sein!'::text),
(351196,39022,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зізнався, що ... цілком виснажений після найгіршого тижня в житті!'::text,'був'::text,'бути'::text,'був'::text,'Він зізнався, що був цілком виснажений після найгіршого тижня в житті!'::text),
(351195,39022,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Admitió ... completamente agotado después de la peor semana de su vida!'::text,'estar'::text,'estar'::text,'estaba'::text,'¡Admitió estar completamente agotado después de la peor semana de su vida!'::text),
(351194,39022,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a avoué ... complètement épuisé après la pire semaine de sa vie !'::text,'être'::text,'être'::text,'était'::text,'Il a avoué être complètement épuisé après la pire semaine de sa vie !'::text),
(351197,39022,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayatının en kötü haftasından sonra tamamen bitkin ... itiraf etti!'::text,'olduğunu'::text,'olmayı'::text,'olduğunu'::text,'Hayatının en kötü haftasından sonra tamamen bitkin olduğunu itiraf etti!'::text),
(351198,39022,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevallotta, hogy teljesen kimerült ... élete legrosszabb hete után!'::text,'volt'::text,'lenni'::text,'volt'::text,'Bevallotta, hogy teljesen kimerült volt élete legrosszabb hete után!'::text),
(351201,39023,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hätte diesen Marathon nicht ...! Jetzt liegt er völlig erschöpft im Meer!'::text,'laufen sollen'::text,'laufen dürfen'::text,'laufen können'::text,'Er hätte diesen Marathon nicht laufen sollen! Jetzt liegt er völlig erschöpft im Meer!'::text),
(351205,39023,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... той марафон! Тепер лежить у морі, повністю виснажений!'::text,'не мав бігти'::text,'не мав права бігти'::text,'не міг бігти'::text,'Він не мав бігти той марафон! Тепер лежить у морі, повністю виснажений!'::text),
(351204,39023,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... ese maratón! ¡Ahora está tumbado en el mar, completamente agotado!'::text,'No debería haber corrido'::text,'No debió correr'::text,'No pudo correr'::text,'¡No debería haber corrido ese maratón! ¡Ahora está tumbado en el mar, completamente agotado!'::text),
(351203,39023,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... ce marathon ! Maintenant il est allongé dans la mer, complètement épuisé !'::text,'n''aurait pas dû courir'::text,'n''avait pas le droit de courir'::text,'ne pouvait pas courir'::text,'Il n''aurait pas dû courir ce marathon ! Maintenant il est allongé dans la mer, complètement épuisé !'::text),
(351206,39023,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O maratonu ...! Şimdi denizde yatıyor, tamamen bitkin!'::text,'koşmamalıydı'::text,'koşmamalıydı'::text,'koşamazdı'::text,'O maratonu koşmamalıydı! Şimdi denizde yatıyor, tamamen bitkin!'::text),
(351207,39023,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... azt a maratont! Most ott fekszik a tengerben, teljesen kimerülten!'::text,'Nem kellett volna lefutnia'::text,'Nem lett volna szabad lefutnia'::text,'Nem tudta lefutni'::text,'Nem kellett volna lefutnia azt a maratont! Most ott fekszik a tengerben, teljesen kimerülten!'::text),
(351210,39024,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Babe, er hat mir erzählt, sein Coach hat ihn zehn Kilometer ... lassen, also war er erschöpft.'::text,'laufen'::text,'laufen'::text,'lief'::text,'Babe, er hat mir erzählt, sein Coach hat ihn zehn Kilometer laufen lassen, also war er erschöpft.'::text),
(351214,39024,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що тренер змусив його ... десять кілометрів, тож він був виснажений.'::text,'пробігти'::text,'пробігти'::text,'пробіг'::text,'Подруго, він сказав мені, що тренер змусив його пробігти десять кілометрів, тож він був виснажений.'::text),
(351213,39024,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que su entrenador le hizo ... diez kilómetros, así que estaba agotado.'::text,'correr'::text,'correr'::text,'corrió'::text,'Tía, me dijo que su entrenador le hizo correr diez kilómetros, así que estaba agotado.'::text),
(351212,39024,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit que son coach lui a fait ... dix kilomètres, donc il était épuisé.'::text,'courir'::text,'courir'::text,'couru'::text,'Meuf, il m''a dit que son coach lui a fait courir dix kilomètres, donc il était épuisé.'::text),
(351215,39024,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana antrenörünün ona on kilometre ... söyledi, o yüzden bitkinmiş.'::text,'koşturduğunu'::text,'koşturduğunu'::text,'koştuğunu'::text,'Kızım, bana antrenörünün ona on kilometre koşturduğunu söyledi, o yüzden bitkinmiş.'::text),
(351216,39024,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, az edzője tíz kilométert ... vele, ezért volt kimerült.'::text,'futtatott'::text,'futtatott'::text,'futott'::text,'Csajszi, azt mondta, az edzője tíz kilométert futtatott vele, ezért volt kimerült.'::text),
(351219,39025,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich wünscht er sich, er ... weniger erschöpft, damit er den Sonnenuntergang genießen könnte.'::text,'wäre'::text,'ist'::text,'wird'::text,'Bestie, angeblich wünscht er sich, er wäre weniger erschöpft, damit er den Sonnenuntergang genießen könnte.'::text),
(351223,39025,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бесті, кажуть, він хотів би ... менш виснаженим, щоб насолодитися заходом сонця.'::text,'бути'::text,'бути'::text,'бути'::text,'Бесті, кажуть, він хотів би бути менш виснаженим, щоб насолодитися заходом сонця.'::text),
(351222,39025,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, al parecer desearía ... menos agotado para poder disfrutar del atardecer.'::text,'estar'::text,'está'::text,'estará'::text,'Bestie, al parecer desearía estar menos agotado para poder disfrutar del atardecer.'::text),
(351221,39025,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment il aimerait ... moins épuisé pour pouvoir profiter du coucher de soleil.'::text,'être'::text,'est'::text,'sera'::text,'Bestie, apparemment il aimerait être moins épuisé pour pouvoir profiter du coucher de soleil.'::text),
(351224,39025,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre gün batımının tadını çıkarabilmek için daha az bitkin ... diliyor.'::text,'olmayı'::text,'olduğunu'::text,'olacağını'::text,'Kanka, duyduğuma göre gün batımının tadını çıkarabilmek için daha az bitkin olmayı diliyor.'::text),
(351225,39025,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag azt szeretné, ha ... kevésbé kimerült, hogy élvezhesse a naplementét.'::text,'lenne'::text,NULL::text,'lesz'::text,'Csajszi, állítólag azt szeretné, ha lenne kevésbé kimerült, hogy élvezhesse a naplementét.'::text),
(351228,39026,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dieser Typ, ... Energie komplett weg ist, ist lowkey zu erschöpft zum Stehen.'::text,'dessen'::text,'der'::text,'welcher'::text,'Bro, dieser Typ, dessen Energie komplett weg ist, ist lowkey zu erschöpft zum Stehen.'::text),
(351232,39026,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, цей чувак, ... енергія повністю зникла, реально надто виснажений, щоб стояти.'::text,'чия'::text,'який'::text,'котрий'::text,'Бро, цей чувак, чия енергія повністю зникла, реально надто виснажений, щоб стояти.'::text),
