(366993,40777,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy autó több mint 200 000 euróba ..., az értékesítési jelentés luxusmodellként tünteti fel.'::text,'kerül'::text,'kerülne'::text,'fog kerülni'::text,'Ha egy autó több mint 200 000 euróba kerül, az értékesítési jelentés luxusmodellként tünteti fel.'::text),
(366996,40778,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er den Startknopf drückt, ... das Luxusauto, weil das der Job des Knopfs ist.'::text,'startet'::text,'würde starten'::text,'startete'::text,'Wenn er den Startknopf drückt, startet das Luxusauto, weil das der Job des Knopfs ist.'::text),
(367000,40778,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він натисне кнопку запуску, розкішне авто ..., бо це робота кнопки.'::text,'заведеться'::text,'завелося б'::text,'завелося'::text,'Якщо він натисне кнопку запуску, розкішне авто заведеться, бо це робота кнопки.'::text),
(366999,40778,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si pulsa el botón de arranque, el coche de lujo ..., porque ese es el trabajo del botón.'::text,'arrancará'::text,'arrancaría'::text,'arrancó'::text,'Si pulsa el botón de arranque, el coche de lujo arrancará, porque ese es el trabajo del botón.'::text),
(366998,40778,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il appuie sur le bouton de démarrage, la voiture de luxe ..., parce que c''est le job du bouton.'::text,'démarrera'::text,'démarrerait'::text,'a démarré'::text,'S''il appuie sur le bouton de démarrage, la voiture de luxe démarrera, parce que c''est le job du bouton.'::text),
(367001,40778,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Start düğmesine basarsa lüks araba ..., çünkü düğmenin işi bu.'::text,'çalışacak'::text,'çalışırdı'::text,'çalıştı'::text,'Start düğmesine basarsa lüks araba çalışacak, çünkü düğmenin işi bu.'::text),
(367002,40778,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha megnyomja az indítógombot, a luxusautó ..., mert ez a gomb dolga.'::text,'beindul'::text,'beindulna'::text,'beindult'::text,'Ha megnyomja az indítógombot, a luxusautó beindul, mert ez a gomb dolga.'::text),
(367005,40779,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Fahrzeug weniger ..., würde es typischerweise nicht als Luxusgut eingestuft.'::text,'kostete'::text,'kostet'::text,'kosten würde'::text,'Wenn das Fahrzeug weniger kostete, würde es typischerweise nicht als Luxusgut eingestuft.'::text),
(367009,40779,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби транспортний засіб ... менше, його зазвичай не класифікували б як предмет розкоші.'::text,'коштував'::text,'коштує'::text,'коштував би'::text,'Якби транспортний засіб коштував менше, його зазвичай не класифікували б як предмет розкоші.'::text),
(367008,40779,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el vehículo ... menos, normalmente no se clasificaría como artículo de lujo.'::text,'costara'::text,'cuesta'::text,'costaría'::text,'Si el vehículo costara menos, normalmente no se clasificaría como artículo de lujo.'::text),
(367007,40779,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le véhicule ... moins, il ne serait généralement pas classé comme article de luxe.'::text,'coûtait'::text,'coûte'::text,'coûterait'::text,'Si le véhicule coûtait moins, il ne serait généralement pas classé comme article de luxe.'::text),
(367010,40779,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araç daha az ..., genellikle lüks ürün olarak sınıflandırılmazdı.'::text,'tutsaydı'::text,'tutuyor'::text,'tutardı'::text,'Araç daha az tutsaydı, genellikle lüks ürün olarak sınıflandırılmazdı.'::text),
(367011,40779,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a jármű kevesebbe ..., jellemzően nem sorolnák a luxuscikkek közé.'::text,'kerülne'::text,'kerül'::text,'kerülne'::text,'Ha a jármű kevesebbe kerülne, jellemzően nem sorolnák a luxuscikkek közé.'::text),
(367014,40780,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das rote Luxusauto ... allein auf dem leeren Dach.'::text,'wurde zurückgelassen'::text,'ließ zurück'::text,'fährt weg'::text,'Das rote Luxusauto wurde zurückgelassen allein auf dem leeren Dach.'::text),
(367018,40780,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Червоне розкішне авто ... саме на порожньому даху.'::text,'залишили'::text,'залишило'::text,'від''їжджає'::text,'Червоне розкішне авто залишили саме на порожньому даху.'::text),
(367017,40780,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche de lujo rojo ... solo en la azotea vacía.'::text,'fue dejado'::text,'dejó'::text,'está saliendo'::text,'El coche de lujo rojo fue dejado solo en la azotea vacía.'::text),
(367016,40780,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture de luxe rouge ... seule sur le toit vide.'::text,'a été laissée'::text,'a laissé'::text,'est en train de partir'::text,'La voiture de luxe rouge a été laissée seule sur le toit vide.'::text),
(367019,40780,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kırmızı lüks araba boş çatıda yalnız ...'::text,'bırakıldı'::text,'bıraktı'::text,'ayrılıyor'::text,'Kırmızı lüks araba boş çatıda yalnız bırakıldı.'::text),
(367020,40780,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piros luxusautót egyedül ... az üres tetőn.'::text,'hagyták'::text,'hagyta'::text,'indul el'::text,'A piros luxusautót egyedül hagyták az üres tetőn.'::text),
(367023,40781,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... in den roten Ledersitz des Luxusautos.'::text,'lässt sich sinken'::text,'wird gesenkt'::text,'sinkend'::text,'Der Mann lässt sich sinken in den roten Ledersitz des Luxusautos.'::text),
(367027,40781,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... в червоне шкіряне сидіння розкішного авто.'::text,'опускається'::text,'опускають'::text,'опускаючись'::text,'Чоловік опускається в червоне шкіряне сидіння розкішного авто.'::text),
(367026,40781,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... en el asiento de cuero rojo del coche de lujo.'::text,'se deja caer'::text,'es bajado'::text,'dejándose caer'::text,'El hombre se deja caer en el asiento de cuero rojo del coche de lujo.'::text),
(367025,40781,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... dans le siège en cuir rouge de la voiture de luxe.'::text,'se glisse'::text,'est descendu'::text,'se glissant'::text,'L''homme se glisse dans le siège en cuir rouge de la voiture de luxe.'::text),
(367028,40781,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam lüks arabanın kırmızı deri koltuğuna ...'::text,'yerleşiyor'::text,'indiriliyor'::text,'yerleşerek'::text,'Adam lüks arabanın kırmızı deri koltuğuna yerleşiyor.'::text),
(367029,40781,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi ... a luxusautó piros bőrülésébe.'::text,'beereszkedik'::text,'leeresztik'::text,'beereszkedve'::text,'A férfi beereszkedik a luxusautó piros bőrülésébe.'::text),
(358185,39799,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das riesige Auge des Riesen ist offen, also schläft er ...'::text,'sicher nicht'::text,'sicher'::text,'auf keinen Fall'::text,'Das riesige Auge des Riesen ist offen, also schläft er sicher nicht.'::text),
(358189,39799,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Величезне око велетня відкрите, тож він ... спати.'::text,'не може'::text,'мусить'::text,'не повинен'::text,'Величезне око велетня відкрите, тож він не може спати.'::text),
(358188,39799,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El enorme ojo del gigante está abierto, así que ... estar dormido.'::text,'no puede'::text,'debe de'::text,'no debe'::text,'El enorme ojo del gigante está abierto, así que no puede estar dormido.'::text),
(358187,39799,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''énorme œil du géant est ouvert, donc il ... dormir.'::text,'ne peut pas'::text,'doit'::text,'ne doit pas'::text,'L''énorme œil du géant est ouvert, donc il ne peut pas dormir.'::text),
(358190,39799,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devin kocaman gözü açık, yani uyuyor ...'::text,'olamaz'::text,'olmalı'::text,'olmamalı'::text,'Devin kocaman gözü açık, yani uyuyor olamaz.'::text),
(358191,39799,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az óriás hatalmas szeme nyitva van, szóval ... alszik.'::text,'biztosan nem'::text,'biztosan'::text,'semmiképp sem'::text,'Az óriás hatalmas szeme nyitva van, szóval biztosan nem alszik.'::text),
(358194,39800,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, angeblich hat der Riese, auf ... Kopf es gelandet ist, im See geschlafen.'::text,'dessen'::text,'der'::text,'welcher'::text,'Rate mal, angeblich hat der Riese, auf dessen Kopf es gelandet ist, im See geschlafen.'::text),
(358198,39800,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, велетень, на ... голову воно впало, спав в озері.'::text,'чию'::text,'який'::text,'котрий'::text,'Уяви, кажуть, велетень, на чию голову воно впало, спав в озері.'::text),
(358197,39800,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, al parecer el gigante sobre ... cabeza aterrizó estaba durmiendo en el lago.'::text,'cuya'::text,'quien'::text,'el cual'::text,'Adivina qué, al parecer el gigante sobre cuya cabeza aterrizó estaba durmiendo en el lago.'::text),
(358196,39800,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment le géant sur la tête ... il a atterri dormait dans le lac.'::text,'duquel'::text,'de qui'::text,'lequel'::text,'Devine quoi, apparemment le géant sur la tête duquel il a atterri dormait dans le lac.'::text),
(358199,39800,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, duyduğuma göre ... kafasına düştüğü dev, gölde uyuyormuş.'::text,''::text,NULL::text,NULL::text,'Bil bakalım, duyduğuma göre kafasına düştüğü dev, gölde uyuyormuş.'::text),
(358200,39800,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag az óriás, ... fejére ráesett, a tóban aludt.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Képzeld, állítólag az óriás, akinek a fejére ráesett, a tóban aludt.'::text),
(358203,39801,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das kleine Tier sagte, dass der Riese die ganze Zeit ..., dann schrie es natürlich.'::text,'geschlafen hatte'::text,'geschlafen hat'::text,'schläft'::text,'Das kleine Tier sagte, dass der Riese die ganze Zeit geschlafen hatte, dann schrie es natürlich.'::text),
(358207,39801,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маленька тваринка сказала, що велетень ... весь час. Потім вона, звісно, закричала.'::text,'спав'::text,'спав'::text,'спить'::text,'Маленька тваринка сказала, що велетень спав весь час. Потім вона, звісно, закричала.'::text),
(358206,39801,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El animalito dijo que el gigante ... dormido todo el tiempo. Luego gritó, obviamente.'::text,'había estado'::text,'ha estado'::text,'está'::text,'El animalito dijo que el gigante había estado dormido todo el tiempo. Luego gritó, obviamente.'::text),
(358205,39801,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le petit animal a dit que le géant ... endormi tout ce temps. Puis il a hurlé, évidemment.'::text,'avait été'::text,'a été'::text,'est'::text,'Le petit animal a dit que le géant avait été endormi tout ce temps. Puis il a hurlé, évidemment.'::text),
(358208,39801,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük hayvan devin başından beri uyuyor ... söyledi. Sonra tabii ki çığlık attı.'::text,'olduğunu'::text,'olduğunu'::text,'olduğunu'::text,'Küçük hayvan devin başından beri uyuyor olduğunu söyledi. Sonra tabii ki çığlık attı.'::text),
(358209,39801,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kis állat azt mondta, hogy az óriás egész végig ..., aztán persze felsikított.'::text,'aludt'::text,'aludt'::text,'alszik'::text,'A kis állat azt mondta, hogy az óriás egész végig aludt, aztán persze felsikított.'::text),
(358212,39802,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das kleine Tier ... früher, Riesen wären nur Geschichten. Wirklich tolles Timing für eine neue Idee.'::text,'dachte'::text,'dachte'::text,'war gewohnt zu denken'::text,'Das kleine Tier dachte früher, Riesen wären nur Geschichten. Wirklich tolles Timing für eine neue Idee.'::text),
(358216,39802,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маленька тваринка ... думала, що велетні — лише казки. Справді чудовий момент для нової ідеї.'::text,'колись'::text,'бувало'::text,'звикла'::text,'Маленька тваринка колись думала, що велетні — лише казки. Справді чудовий момент для нової ідеї.'::text),
(358215,39802,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El animalito ... pensar que los gigantes eran solo cuentos. Un momento realmente genial para una idea nueva.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'El animalito solía pensar que los gigantes eran solo cuentos. Un momento realmente genial para una idea nueva.'::text),
(358214,39802,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le petit animal ... que les géants n''étaient que des histoires. Vraiment le moment parfait pour une nouvelle idée.'::text,'croyait autrefois'::text,'croyait'::text,'était habitué à croire'::text,'Le petit animal croyait autrefois que les géants n''étaient que des histoires. Vraiment le moment parfait pour une nouvelle idée.'::text),
(358217,39802,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük hayvan eskiden devlerin sadece hikâye olduğunu ..., yeni bir fikir için gerçekten harika zamanlama.'::text,'düşünürdü'::text,'düşünürdü'::text,'düşünmeye alışkındı'::text,'Küçük hayvan eskiden devlerin sadece hikâye olduğunu düşünürdü, yeni bir fikir için gerçekten harika zamanlama.'::text),
(358218,39802,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kis állat ... azt hitte, hogy az óriások csak mesék. Igazán remek időzítés egy új ötlethez.'::text,'régen'::text,'régebben'::text,'megszokásból'::text,'A kis állat régen azt hitte, hogy az óriások csak mesék. Igazán remek időzítés egy új ötlethez.'::text),
(358221,39803,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, es hat einfach nur weiter ..., als es das Auge des Riesen sah, ohne Witz.'::text,'geschrien'::text,'geschrien'::text,'geschrien'::text,'Bro, es hat einfach nur weiter geschrien, als es das Auge des Riesen sah, ohne Witz.'::text),
(358225,39803,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, воно просто не переставало ..., коли побачило око велетня, без приколів.'::text,'кричати'::text,'кричати'::text,'кричати'::text,'Бро, воно просто не переставало кричати, коли побачило око велетня, без приколів.'::text),
(358224,39803,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, no paraba de ... cuando vio el ojo del gigante, en serio.'::text,'gritar'::text,'gritar'::text,'gritar'::text,'Bro, no paraba de gritar cuando vio el ojo del gigante, en serio.'::text),
(358223,39803,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il n''arrêtait pas de ... quand il a vu l''œil du géant, sans mentir.'::text,'crier'::text,'crier'::text,'crier'::text,'Frérot, il n''arrêtait pas de crier quand il a vu l''œil du géant, sans mentir.'::text),
(358226,39803,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, devin gözünü görünce durmadan ..., yemin ederim.'::text,'çığlık attı'::text,'çığlık attı'::text,'çığlık attı'::text,'Kanka, devin gözünü görünce durmadan çığlık attı, yemin ederim.'::text),
(358227,39803,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, csak ... tovább, amikor meglátta az óriás szemét, komolyan.'::text,'sikított'::text,'sikított'::text,'sikított'::text,'Tesó, csak sikított tovább, amikor meglátta az óriás szemét, komolyan.'::text),
(358239,39805,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das kleine Tier hat den Riesen nicht erwartet, und die Zuschauer ...'::text,'auch nicht'::text,'auch'::text,'auch nicht'::text,'Das kleine Tier hat den Riesen nicht erwartet, und die Zuschauer auch nicht.'::text),
(358243,39805,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маленька тваринка не очікувала велетня, і глядачі ...'::text,'теж ні'::text,'теж'::text,'теж ні'::text,'Маленька тваринка не очікувала велетня, і глядачі теж ні.'::text),
(358242,39805,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El animalito no esperaba al gigante, y los espectadores ...'::text,'tampoco'::text,'también'::text,'tampoco'::text,'El animalito no esperaba al gigante, y los espectadores tampoco.'::text),
(358241,39805,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le petit animal ne s''attendait pas au géant, et les spectateurs ...'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Le petit animal ne s''attendait pas au géant, et les spectateurs non plus.'::text),
(358244,39805,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük hayvan devi beklemiyordu, izleyiciler de ...'::text,'beklemiyordu'::text,'bekliyordu'::text,'değildi'::text,'Küçük hayvan devi beklemiyordu, izleyiciler de beklemiyordu.'::text),
(358245,39805,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kis állat nem számított az óriásra, és a nézők ...'::text,'sem'::text,'is'::text,'sem'::text,'A kis állat nem számított az óriásra, és a nézők sem.'::text),
(358248,39806,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Riese ... jahrhundertelang in diesem See, bevor diese winzige Bestie auf ihm landete. Katastrophe!'::text,'schlief'::text,'schläft'::text,'schlief'::text,'Der Riese schlief jahrhundertelang in diesem See, bevor diese winzige Bestie auf ihm landete. Katastrophe!'::text),
(358252,39806,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велетень ... в тому озері століттями, поки на нього не впало це крихітне створіння. Катастрофа!'::text,'спав'::text,'спить'::text,'спав'::text,'Велетень спав в тому озері століттями, поки на нього не впало це крихітне створіння. Катастрофа!'::text),
(358251,39806,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gigante ... en ese lago durante siglos antes de que esta diminuta bestia aterrizara sobre él. ¡Catástrofe!'::text,'llevaba durmiendo'::text,'lleva durmiendo'::text,'estaba durmiendo'::text,'El gigante llevaba durmiendo en ese lago durante siglos antes de que esta diminuta bestia aterrizara sobre él. ¡Catástrofe!'::text),
(358250,39806,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le géant ... dans ce lac depuis des siècles avant que cette minuscule bête atterrisse sur lui. Catastrophe !'::text,'dormait'::text,'dort'::text,'dormait'::text,'Le géant dormait dans ce lac depuis des siècles avant que cette minuscule bête atterrisse sur lui. Catastrophe !'::text),
(358253,39806,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu minik canavar üstüne düşmeden önce dev yüzyıllardır o gölde ..., felaket!'::text,'uyuyordu'::text,'uyuyor'::text,'uyuyordu'::text,'Bu minik canavar üstüne düşmeden önce dev yüzyıllardır o gölde uyuyordu, felaket!'::text),
(358254,39806,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az óriás évszázadok óta ... abban a tóban, mielőtt ez az apró szörny rápottyant. Katasztrófa!'::text,'aludt'::text,'alszik'::text,'aludt'::text,'Az óriás évszázadok óta aludt abban a tóban, mielőtt ez az apró szörny rápottyant. Katasztrófa!'::text),
(358257,39807,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang wird der Riese aus Rache den ganzen Wald ...!'::text,'zerstört haben'::text,'zerstören'::text,'zerstört'::text,'Bis Sonnenuntergang wird der Riese aus Rache den ganzen Wald zerstört haben!'::text),
(358261,39807,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця велетень ... весь ліс із помсти!'::text,'знищить'::text,'знищить'::text,'знищує'::text,'До заходу сонця велетень знищить весь ліс із помсти!'::text),
(358260,39807,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el atardecer, el gigante ... todo el bosque por venganza!'::text,'habrá destruido'::text,'destruirá'::text,'destruye'::text,'¡Para el atardecer, el gigante habrá destruido todo el bosque por venganza!'::text),
(358259,39807,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, le géant ... toute la forêt pour se venger !'::text,'aura détruit'::text,'détruira'::text,'détruit'::text,'D''ici le coucher du soleil, le géant aura détruit toute la forêt pour se venger !'::text),
(358262,39807,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar dev intikam için bütün ormanı ...!'::text,'yok etmiş olacak'::text,'yok edecek'::text,'yok ediyor'::text,'Gün batımına kadar dev intikam için bütün ormanı yok etmiş olacak!'::text),
(358263,39807,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplementére az óriás bosszúból ... az egész erdőt!'::text,'elpusztítja'::text,'el fogja pusztítani'::text,'pusztítja'::text,'Naplementére az óriás bosszúból elpusztítja az egész erdőt!'::text),
(358266,39808,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Abend ... der Riese schon hundert Jahre im nebligen See.'::text,'treibt'::text,'treibt'::text,'treibt'::text,'Heute Abend treibt der Riese schon hundert Jahre im nebligen See.'::text),
(358270,39808,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні ввечері велетень ... в туманному озері вже сто років.'::text,'дрейфуватиме'::text,'дрейфуватиме'::text,'дрейфуватиме'::text,'Сьогодні ввечері велетень дрейфуватиме в туманному озері вже сто років.'::text),
(358269,39808,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche, el gigante ... en el lago brumoso durante cien años.'::text,'habrá estado flotando'::text,'estará flotando'::text,'flotará'::text,'Para esta noche, el gigante habrá estado flotando en el lago brumoso durante cien años.'::text),
(358268,39808,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce soir, le géant ... dans le lac brumeux depuis cent ans.'::text,'flottera'::text,'flottera'::text,'flottera'::text,'Ce soir, le géant flottera dans le lac brumeux depuis cent ans.'::text),
(358271,39808,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşam itibarıyla dev yüz yıldır sisli gölde ...'::text,'süzülüyor olacak'::text,'süzülüyor olacak'::text,'süzülecek'::text,'Bu akşam itibarıyla dev yüz yıldır sisli gölde süzülüyor olacak.'::text),
(358272,39808,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma estére az óriás már száz éve ... a ködös tóban.'::text,'fog lebegni'::text,'fog lebegni'::text,'fog lebegni'::text,'Ma estére az óriás már száz éve fog lebegni a ködös tóban.'::text),
(390189,43355,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, das Auto ... gerade die Straße entlang, als die Kamera seine goldenen Felgen erwischte, echt.'::text,'raste'::text,'raste'::text,'raste'::text,'Yo, das Auto raste gerade die Straße entlang, als die Kamera seine goldenen Felgen erwischte, echt.'::text),
(390193,43355,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, машина ... дорогою, коли камера зловила її золоті диски, реально.'::text,'мчала'::text,'промчала'::text,'промчала'::text,'Йо, машина мчала дорогою, коли камера зловила її золоті диски, реально.'::text),
(390192,43355,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, el coche ... por la carretera cuando la cámara pilló sus llantas doradas, en serio.'::text,'iba a toda velocidad'::text,'pasó a toda velocidad'::text,'ha pasado a toda velocidad'::text,'Ey, el coche iba a toda velocidad por la carretera cuando la cámara pilló sus llantas doradas, en serio.'::text),
(390191,43355,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, la voiture ... sur la route quand la caméra a chopé ses jantes dorées, sérieux.'::text,'filait'::text,'a filé'::text,'a filé'::text,'Yo, la voiture filait sur la route quand la caméra a chopé ses jantes dorées, sérieux.'::text),
(390194,43355,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, kamera altın jantlarını yakaladığında araba yolda ..., cidden.'::text,'hız yapıyordu'::text,'hız yaptı'::text,'hız yaptı'::text,'Yo, kamera altın jantlarını yakaladığında araba yolda hız yapıyordu, cidden.'::text),
(390195,43355,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, az autó éppen ... az úton, amikor a kamera elkapta az arany felniit, komolyan.'::text,'száguldott'::text,'elszáguldott'::text,'elszáguldott'::text,'Figyu, az autó éppen száguldott az úton, amikor a kamera elkapta az arany felniit, komolyan.'::text),
(390198,43356,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dieses Auto ... schon den ganzen Tag über Landstraßen, ohne Witz.'::text,'rast'::text,'rast'::text,'rast'::text,'Bro, dieses Auto rast schon den ganzen Tag über Landstraßen, ohne Witz.'::text),
(390202,43356,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ця машина ... сільськими дорогами весь день, без приколів.'::text,'мчить'::text,'мчить'::text,'мчить'::text,'Бро, ця машина мчить сільськими дорогами весь день, без приколів.'::text),
(390201,43356,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, este coche ... por carreteras comarcales todo el día, en serio.'::text,'ha estado corriendo'::text,'está corriendo'::text,'corre'::text,'Bro, este coche ha estado corriendo por carreteras comarcales todo el día, en serio.'::text),
(390200,43356,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, cette voiture ... sur les routes de campagne toute la journée, sans mentir.'::text,'fonce'::text,'fonce'::text,'fonce'::text,'Frérot, cette voiture fonce sur les routes de campagne toute la journée, sans mentir.'::text),
(390203,43356,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu araba bütün gün köy yollarında ..., yemin ederim.'::text,'hız yapıyor'::text,'hız yapıyor'::text,'hız yapar'::text,'Kanka, bu araba bütün gün köy yollarında hız yapıyor, yemin ederim.'::text),
(390204,43356,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez az autó egész nap ... a vidéki utakon, komolyan.'::text,'száguld'::text,'száguld'::text,'száguld'::text,'Tesó, ez az autó egész nap száguld a vidéki utakon, komolyan.'::text),
(390207,43357,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Auto ... um 9:00 die Straße entlang, als der Kunde anrief.'::text,'raste'::text,'raste'::text,'raste'::text,'Das Auto raste um 9:00 die Straße entlang, als der Kunde anrief.'::text),
(390211,43357,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Машина ... дорогою о 9:00, коли подзвонив клієнт.'::text,'мчала'::text,'промчала'::text,'промчала'::text,'Машина мчала дорогою о 9:00, коли подзвонив клієнт.'::text),
(390210,43357,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche ... por la carretera a las 9:00 cuando llamó el cliente.'::text,'iba a toda velocidad'::text,'pasó a toda velocidad'::text,'ha pasado a toda velocidad'::text,'El coche iba a toda velocidad por la carretera a las 9:00 cuando llamó el cliente.'::text),
(390209,43357,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture ... sur la route à 9 h 00 quand le client a appelé.'::text,'filait'::text,'a filé'::text,'a filé'::text,'La voiture filait sur la route à 9 h 00 quand le client a appelé.'::text),
(390212,43357,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri aradığında saat 9:00''da araba yolda ...'::text,'hız yapıyordu'::text,'hız yaptı'::text,'hız yaptı'::text,'Müşteri aradığında saat 9:00''da araba yolda hız yapıyordu.'::text),
(390213,43357,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autó 9:00-kor éppen ... az úton, amikor a kliens hívott.'::text,'száguldott'::text,'elszáguldott'::text,'elszáguldott'::text,'Az autó 9:00-kor éppen száguldott az úton, amikor a kliens hívott.'::text),
(390216,43358,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Auto ... seit zehn Minuten diese Straße entlang, also ist es seit zehn Minuten schnell.'::text,'rast'::text,'raste'::text,'raste'::text,'Das Auto rast seit zehn Minuten diese Straße entlang, also ist es seit zehn Minuten schnell.'::text),
(390220,43358,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Машина ... цією дорогою десять хвилин, тож вона швидка вже десять хвилин.'::text,'мчить'::text,'мчала'::text,'мчала'::text,'Машина мчить цією дорогою десять хвилин, тож вона швидка вже десять хвилин.'::text),
(390219,43358,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche ... por esta carretera desde hace diez minutos, así que lleva diez minutos siendo rápido.'::text,'ha estado corriendo'::text,'ha corrido'::text,'corrió'::text,'El coche ha estado corriendo por esta carretera desde hace diez minutos, así que lleva diez minutos siendo rápido.'::text),
(390218,43358,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture ... sur cette route depuis dix minutes, donc elle est rapide depuis dix minutes.'::text,'fonce'::text,'a foncé'::text,'a foncé'::text,'La voiture fonce sur cette route depuis dix minutes, donc elle est rapide depuis dix minutes.'::text),
(390221,43358,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araba on dakikadır bu yolda ..., yani on dakikadır hızlı.'::text,'hız yapıyor'::text,'hız yaptı'::text,'hız yaptı'::text,'Araba on dakikadır bu yolda hız yapıyor, yani on dakikadır hızlı.'::text),
(390222,43358,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autó tíz perce ... ezen az úton, szóval tíz perce gyors.'::text,'száguld'::text,'száguldott'::text,'száguldott'::text,'Az autó tíz perce száguld ezen az úton, szóval tíz perce gyors.'::text),
(390234,43360,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du wieder die Küste entlangrast, ... dich die Kamera perfekt.'::text,'erwischt'::text,'würde erwischen'::text,'erwischte'::text,'Ehrlich, wenn du wieder die Küste entlangrast, erwischt dich die Kamera perfekt.'::text),
(390238,43360,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, якщо ти знову мчатимеш узбережжям, камера ... тебе ідеально.'::text,'зловить'::text,'зловила б'::text,'зловила'::text,'Не брехатиму, якщо ти знову мчатимеш узбережжям, камера зловить тебе ідеально.'::text),
(390237,43360,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, si vuelves a correr por la costa, la cámara te ... perfecto.'::text,'captará'::text,'captaría'::text,'captó'::text,'No voy a mentir, si vuelves a correr por la costa, la cámara te captará perfecto.'::text),
(390236,43360,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, si tu refonces le long de la côte, la caméra te ... parfaitement.'::text,'captera'::text,'capterait'::text,'a capté'::text,'Sans mentir, si tu refonces le long de la côte, la caméra te captera parfaitement.'::text),
(390239,43360,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, yine sahil boyunca hız yaparsan kamera seni mükemmel ...'::text,'yakalayacak'::text,'yakalardı'::text,'yakaladı'::text,'Yalan yok, yine sahil boyunca hız yaparsan kamera seni mükemmel yakalayacak.'::text),
(390240,43360,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ha megint végigszáguldasz a parton, a kamera tökéletesen ... téged.'::text,'elkap'::text,'elkapna'::text,'elkapott'::text,'Nem hazudok, ha megint végigszáguldasz a parton, a kamera tökéletesen elkap téged.'::text),
(390243,43361,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn ich dein Auto hätte, würde ich auch diese Straße ...'::text,'runterrasen'::text,'runterrasen'::text,'runterrasen'::text,'Ehrlich, wenn ich dein Auto hätte, würde ich auch diese Straße runterrasen.'::text),
(390247,43361,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби в мене була твоя машина, я теж ... тією дорогою.'::text,'мчав би'::text,'мчатиму'::text,'мчу'::text,'Чесно, якби в мене була твоя машина, я теж мчав би тією дорогою.'::text),
(390246,43361,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si tuviera tu coche, yo también ... por esa carretera.'::text,'correría'::text,'correré'::text,'corro'::text,'Sinceramente, si tuviera tu coche, yo también correría por esa carretera.'::text),
(390245,43361,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si j''avais ta voiture, moi aussi je ... sur cette route.'::text,'foncerais'::text,'foncerai'::text,'fonce'::text,'Franchement, si j''avais ta voiture, moi aussi je foncerais sur cette route.'::text),
(390248,43361,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, senin araban bende olsaydı ben de o yolda ...'::text,'hız yapardım'::text,'hız yapacağım'::text,'hız yapıyorum'::text,'Açıkçası, senin araban bende olsaydı ben de o yolda hız yapardım.'::text),
(390249,43361,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha nekem lenne a kocsid, én is ... azon az úton.'::text,'száguldanék'::text,'száguldani fogok'::text,'száguldok'::text,'Őszintén, ha nekem lenne a kocsid, én is száguldanék azon az úton.'::text),
(390252,43362,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du wünschst dir eindeutig, du ... für immer diese Straße entlangrasen, und ehrlich, Respekt.'::text,'könntest'::text,'kannst'::text,'wirst'::text,'Du wünschst dir eindeutig, du könntest für immer diese Straße entlangrasen, und ehrlich, Respekt.'::text),
(390256,43362,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти явно хотів би, щоб ... тією дорогою вічно, і чесно, респект.'::text,'міг мчати'::text,'можеш мчати'::text,'мчатимеш'::text,'Ти явно хотів би, щоб міг мчати тією дорогою вічно, і чесно, респект.'::text),
(390255,43362,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está claro que desearías ... por esa carretera para siempre, y la verdad, respeto.'::text,'poder correr'::text,'puedes correr'::text,'correrás'::text,'Está claro que desearías poder correr por esa carretera para siempre, y la verdad, respeto.'::text),
(390254,43362,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu aimerais clairement ... le long de cette route pour toujours, et franchement, respect.'::text,'pouvoir foncer'::text,'peux foncer'::text,'fonceras'::text,'Tu aimerais clairement pouvoir foncer le long de cette route pour toujours, et franchement, respect.'::text),
(390257,43362,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki o yolda sonsuza kadar hız ... diliyorsun, ve açıkçası saygı.'::text,'yapabilmeyi'::text,'yapabildiğini'::text,'yapacağını'::text,'Belli ki o yolda sonsuza kadar hız yapabilmeyi diliyorsun, ve açıkçası saygı.'::text),
(390258,43362,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen azt szeretnéd, ha örökké ... azon az úton, és őszintén, respekt.'::text,'száguldhatnál'::text,'száguldhatsz'::text,'száguldani fogsz'::text,'Egyértelműen azt szeretnéd, ha örökké száguldhatnál azon az úton, és őszintén, respekt.'::text),
(390270,43364,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Auto raste die Straße entlang ... der engen Kurven.'::text,'trotz'::text,'obwohl'::text,'weil'::text,'Das Auto raste die Straße entlang trotz der engen Kurven.'::text),
(390274,43364,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Машина мчала дорогою ... вузькі повороти.'::text,'попри'::text,'хоча'::text,'бо'::text,'Машина мчала дорогою попри вузькі повороти.'::text),
(390273,43364,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche corrió por la carretera ... las curvas estrechas.'::text,'a pesar de'::text,'aunque'::text,'porque'::text,'El coche corrió por la carretera a pesar de las curvas estrechas.'::text),
(390272,43364,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture a filé sur la route ... les virages serrés.'::text,'malgré'::text,'bien que'::text,'parce que'::text,'La voiture a filé sur la route malgré les virages serrés.'::text),
(390275,43364,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araba dar virajlara ... yolda hızla ilerledi.'::text,'rağmen'::text,'her ne kadar'::text,'çünkü'::text,'Araba dar virajlara rağmen yolda hızla ilerledi.'::text),
(390276,43364,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autó a szűk kanyarok ... végigszáguldott az úton.'::text,'ellenére'::text,'habár'::text,'mert'::text,'Az autó a szűk kanyarok ellenére végigszáguldott az úton.'::text),
(390279,43365,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang wird das Auto über jede Straße an der Küste ...'::text,'gerast sein'::text,'rasen'::text,'rast'::text,'Bis Sonnenuntergang wird das Auto über jede Straße an der Küste gerast sein.'::text),
(390283,43365,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця машина ... кожною дорогою біля узбережжя.'::text,'промчить'::text,'мчатиме'::text,'мчить'::text,'До заходу сонця машина промчить кожною дорогою біля узбережжя.'::text),
(390282,43365,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, el coche ... por todas las carreteras cerca de la costa.'::text,'habrá corrido'::text,'correrá'::text,'corre'::text,'Para el atardecer, el coche habrá corrido por todas las carreteras cerca de la costa.'::text),
(390281,43365,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, la voiture ... sur toutes les routes près de la côte.'::text,'aura filé'::text,'filera'::text,'file'::text,'D''ici le coucher du soleil, la voiture aura filé sur toutes les routes près de la côte.'::text),
(390284,43365,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar araba sahile yakın her yolda ...'::text,'hız yapmış olacak'::text,'hız yapacak'::text,'hız yapıyor'::text,'Gün batımına kadar araba sahile yakın her yolda hız yapmış olacak.'::text),
(390285,43365,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplementére az autó a part közelében minden úton ...'::text,'végigszáguld'::text,'száguldani fog'::text,'száguld'::text,'Naplementére az autó a part közelében minden úton végigszáguld.'::text),
(400485,44499,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Rampe ... nach unten, weil sie nicht nach oben ging, und das Fahrzeug war drin.'::text,'ging gerade'::text,'ging'::text,'ging'::text,'Die Rampe ging gerade nach unten, weil sie nicht nach oben ging, und das Fahrzeug war drin.'::text),
(400489,44499,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рампа ... вниз, бо не йшла вгору, а транспортний засіб був усередині.'::text,'опускалася'::text,'опустилася'::text,'опустилася'::text,'Рампа опускалася вниз, бо не йшла вгору, а транспортний засіб був усередині.'::text),
(400488,44499,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rampa ... hacia abajo porque no iba hacia arriba, y el vehículo estaba dentro.'::text,'iba'::text,'fue'::text,'ha ido'::text,'La rampa iba hacia abajo porque no iba hacia arriba, y el vehículo estaba dentro.'::text),
(400487,44499,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rampe ... vers le bas parce qu''elle ne montait pas, et le véhicule était à l''intérieur.'::text,'descendait'::text,'est descendue'::text,'est descendue'::text,'La rampe descendait vers le bas parce qu''elle ne montait pas, et le véhicule était à l''intérieur.'::text),
(400490,44499,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rampa aşağı ..., çünkü yukarı gitmiyordu, ve araç içerideydi.'::text,'iniyordu'::text,'indi'::text,'indi'::text,'Rampa aşağı iniyordu, çünkü yukarı gitmiyordu, ve araç içerideydi.'::text),
(400491,44499,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rámpa ... lefelé, mert nem felfelé ment, és a jármű bent volt.'::text,'ment'::text,'ment'::text,'ment'::text,'A rámpa ment lefelé, mert nem felfelé ment, és a jármű bent volt.'::text),
(400503,44501,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Fahrzeug wurde von einem schwarzen Anhänger hierher ..., und niemand hat es gesehen!'::text,'gebracht'::text,'gebracht'::text,'bringend'::text,'Das Fahrzeug wurde von einem schwarzen Anhänger hierher gebracht, und niemand hat es gesehen!'::text),
(400507,44501,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Транспортний засіб ... сюди чорним причепом, і ніхто цього не бачив!'::text,'привезли'::text,'привіз'::text,'привозячи'::text,'Транспортний засіб привезли сюди чорним причепом, і ніхто цього не бачив!'::text),
(400506,44501,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El vehículo ... hasta aquí en un remolque negro, y nadie lo vio!'::text,'fue traído'::text,'trajo'::text,'trayendo'::text,'¡El vehículo fue traído hasta aquí en un remolque negro, y nadie lo vio!'::text),
(400505,44501,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le véhicule ... ici par une remorque noire, et personne ne l''a vu !'::text,'a été amené'::text,'a amené'::text,'amenant'::text,'Le véhicule a été amené ici par une remorque noire, et personne ne l''a vu !'::text),
(400508,44501,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araç buraya siyah bir römorkla ... ve kimse görmedi!'::text,'getirildi'::text,'getirdi'::text,'getirerek'::text,'Araç buraya siyah bir römorkla getirildi ve kimse görmedi!'::text),
(400509,44501,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A járművet egy fekete utánfutón ... ide, és senki sem látta!'::text,'hozták'::text,'hozta'::text,'hozva'::text,'A járművet egy fekete utánfutón hozták ide, és senki sem látta!'::text),
(400512,44502,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok also, ich hab gehört, das Fahrzeug im Anhänger ... brandneu sein, aber wer weiß.'::text,'könnte'::text,'muss'::text,'sollte'::text,'Ok also, ich hab gehört, das Fahrzeug im Anhänger könnte brandneu sein, aber wer weiß.'::text),
(400516,44502,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що транспортний засіб у причепі ... бути новеньким, але хто знає.'::text,'може'::text,'мусить'::text,'має'::text,'Коротше, я чула, що транспортний засіб у причепі може бути новеньким, але хто знає.'::text),
(400515,44502,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bueno, oí que el vehículo del remolque ... ser nuevecito, pero quién sabe.'::text,'podría'::text,'debe de'::text,'debería'::text,'Bueno, oí que el vehículo del remolque podría ser nuevecito, pero quién sabe.'::text),
(400514,44502,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, j''ai entendu que le véhicule dans la remorque ... être tout neuf, mais qui sait.'::text,'pourrait'::text,'doit'::text,'devrait'::text,'Bon alors, j''ai entendu que le véhicule dans la remorque pourrait être tout neuf, mais qui sait.'::text),
(400517,44502,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, römorktaki aracın yepyeni ... duydum, ama kim bilir.'::text,'olabileceğini'::text,'olması gerektiğini'::text,'olması gerektiğini'::text,'Neyse, römorktaki aracın yepyeni olabileceğini duydum, ama kim bilir.'::text),
(400518,44502,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, azt hallottam, hogy az utánfutóban lévő jármű ... vadonatúj, de ki tudja.'::text,'talán'::text,'biztosan'::text,'elvileg'::text,'Szóval, azt hallottam, hogy az utánfutóban lévő jármű talán vadonatúj, de ki tudja.'::text),
(400521,44503,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Anhänger, ... Rampe sich so langsam öffnete, versteckte eindeutig das aufregendste Fahrzeug aller Zeiten.'::text,'dessen'::text,'der'::text,'wer'::text,'Der Anhänger, dessen Rampe sich so langsam öffnete, versteckte eindeutig das aufregendste Fahrzeug aller Zeiten.'::text),
(400525,44503,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Причіп, ... рампа відкривалася так повільно, явно ховав найзахопливіший транспортний засіб у світі.'::text,'чия'::text,'який'::text,'хто'::text,'Причіп, чия рампа відкривалася так повільно, явно ховав найзахопливіший транспортний засіб у світі.'::text),
(400524,44503,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El remolque, ... rampa se abrió tan despacio, claramente escondía el vehículo más emocionante de la historia.'::text,'cuya'::text,'que'::text,'quien'::text,'El remolque, cuya rampa se abrió tan despacio, claramente escondía el vehículo más emocionante de la historia.'::text),
(400523,44503,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La remorque, ... la rampe s''est ouverte si lentement, cachait clairement le véhicule le plus excitant de tous les temps.'::text,'dont'::text,'qui'::text,'qui'::text,'La remorque, dont la rampe s''est ouverte si lentement, cachait clairement le véhicule le plus excitant de tous les temps.'::text),
(400526,44503,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... rampası o kadar yavaş açılan römork, belli ki gelmiş geçmiş en heyecan verici aracı saklıyordu.'::text,''::text,NULL::text,NULL::text,'Rampası o kadar yavaş açılan römork, belli ki gelmiş geçmiş en heyecan verici aracı saklıyordu.'::text),
(400527,44503,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utánfutó, ... rámpája olyan lassan nyílt ki, nyilván minden idők legizgalmasabb járművét rejtette.'::text,'amelynek a'::text,'amely'::text,'aki'::text,'Az utánfutó, amelynek a rámpája olyan lassan nyílt ki, nyilván minden idők legizgalmasabb járművét rejtette.'::text),
(400530,44504,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er meinte, dass das Fahrzeug direkt ..., aber nee, es blieb einfach da.'::text,'rausfahren würde'::text,'rausfahren wird'::text,'rausfährt'::text,'Bro, er meinte, dass das Fahrzeug direkt rausfahren würde, aber nee, es blieb einfach da.'::text),
(400534,44504,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він сказав, що машина одразу ..., але ні, вона просто там стояла.'::text,'виїде'::text,'виїде'::text,'виїжджає'::text,'Бро, він сказав, що машина одразу виїде, але ні, вона просто там стояла.'::text),
(400533,44504,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dijo que el vehículo ... directamente, pero nah, se quedó ahí.'::text,'saldría'::text,'saldrá'::text,'sale'::text,'Bro, dijo que el vehículo saldría directamente, pero nah, se quedó ahí.'::text),
(400532,44504,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il a dit que le véhicule ... direct, mais non, il est juste resté là.'::text,'sortirait'::text,'sortira'::text,'sort'::text,'Frérot, il a dit que le véhicule sortirait direct, mais non, il est juste resté là.'::text),
(400535,44504,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, aracın direkt dışarı ... söyledi ama yok, öylece orada kaldı.'::text,'çıkacağını'::text,'çıkacağını'::text,'çıktığını'::text,'Kanka, aracın direkt dışarı çıkacağını söyledi ama yok, öylece orada kaldı.'::text),
(400536,44504,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azt mondta, hogy a jármű egyből ..., de nem, csak ott maradt.'::text,'kigurul'::text,'ki fog gurulni'::text,'kigurul'::text,'Tesó, azt mondta, hogy a jármű egyből kigurul, de nem, csak ott maradt.'::text),
(400539,44505,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Anhänger ... früher leer, bevor er dieses Fahrzeug transportierte.'::text,'war'::text,'war'::text,'war es gewohnt zu sein'::text,'Dieser Anhänger war früher leer, bevor er dieses Fahrzeug transportierte.'::text),
(400543,44505,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей причіп ... порожнім, поки в ньому не з''явився цей транспортний засіб.'::text,'був раніше'::text,'бував'::text,'звик бути'::text,'Цей причіп був раніше порожнім, поки в ньому не з''явився цей транспортний засіб.'::text),
(400542,44505,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este remolque ... estar vacío antes de llevar este vehículo.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Este remolque solía estar vacío antes de llevar este vehículo.'::text),
(400541,44505,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette remorque ... vide avant de transporter ce véhicule.'::text,'était autrefois'::text,'était'::text,'avait l''habitude d''être'::text,'Cette remorque était autrefois vide avant de transporter ce véhicule.'::text),
(400544,44505,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu römork, bu aracı taşımadan önce eskiden ...'::text,'boştu'::text,'boş olurdu'::text,'boş olmaya alışkındı'::text,'Bu römork, bu aracı taşımadan önce eskiden boştu.'::text),
(400545,44505,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez az utánfutó ... üres volt, mielőtt ezt a járművet szállította.'::text,'régen'::text,'régebben'::text,'megszokásból'::text,'Ez az utánfutó régen üres volt, mielőtt ezt a járművet szállította.'::text),
(400548,44506,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Rampe ist tief genug, um das Fahrzeug direkt ...'::text,'rauszufahren'::text,'rauszufahren'::text,'rauszufahren'::text,'Die Rampe ist tief genug, um das Fahrzeug direkt rauszufahren.'::text),
(400552,44506,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рампа достатньо низька, щоб ... машину прямо назовні.'::text,'вигнати'::text,'виганяння'::text,'вигнати'::text,'Рампа достатньо низька, щоб вигнати машину прямо назовні.'::text),
(400551,44506,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rampa está lo bastante baja como para ... el vehículo directamente.'::text,'sacar'::text,'sacando'::text,'sacar'::text,'La rampa está lo bastante baja como para sacar el vehículo directamente.'::text),
(400550,44506,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rampe est assez basse pour ... le véhicule directement.'::text,'sortir'::text,'sortant'::text,'sortir'::text,'La rampe est assez basse pour sortir le véhicule directement.'::text),
(400553,44506,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rampa, aracı doğrudan dışarı ... yeterince alçak.'::text,'sürmek için'::text,'sürerek'::text,'sürmek için'::text,'Rampa, aracı doğrudan dışarı sürmek için yeterince alçak.'::text),
(400554,44506,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rámpa elég alacsony ahhoz, hogy a járművel egyenesen ...'::text,'kihajtsanak'::text,'kihajtás'::text,'kihajtsanak'::text,'A rámpa elég alacsony ahhoz, hogy a járművel egyenesen kihajtsanak.'::text),
(400566,44508,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Fahrzeug ... nun seit ungefähr einer Minute im dunklen Anhänger.'::text,'steht'::text,'steht'::text,'steht'::text,'Das Fahrzeug steht nun seit ungefähr einer Minute im dunklen Anhänger.'::text),
(400570,44508,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Транспортний засіб ... в темному причепі вже приблизно хвилину.'::text,'стоїть'::text,'стоїть'::text,'стоїть'::text,'Транспортний засіб стоїть в темному причепі вже приблизно хвилину.'::text),
(400569,44508,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vehículo ... en el remolque oscuro desde hace aproximadamente un minuto.'::text,'ha estado'::text,'está'::text,'está'::text,'El vehículo ha estado en el remolque oscuro desde hace aproximadamente un minuto.'::text),
(400568,44508,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le véhicule ... dans la remorque sombre depuis environ une minute.'::text,'se trouve'::text,'se trouve'::text,'se trouve'::text,'Le véhicule se trouve dans la remorque sombre depuis environ une minute.'::text),
(400571,44508,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araç yaklaşık bir dakikadır karanlık römorkta ...'::text,'duruyor'::text,'duruyor'::text,'durur'::text,'Araç yaklaşık bir dakikadır karanlık römorkta duruyor.'::text),
(400572,44508,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jármű már körülbelül egy perce ... a sötét utánfutóban.'::text,'áll'::text,'áll'::text,'áll'::text,'A jármű már körülbelül egy perce áll a sötét utánfutóban.'::text),
(400575,44509,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor die Rampe herunterkam, ... niemand das Fahrzeug darin.'::text,'sah'::text,'sah'::text,'sieht'::text,'Bevor die Rampe herunterkam, sah niemand das Fahrzeug darin.'::text),
(400579,44509,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки рампа не опустилася, ніхто ... машини всередині.'::text,'не бачив'::text,'не бачив'::text,'не бачить'::text,'Поки рампа не опустилася, ніхто не бачив машини всередині.'::text),
(400578,44509,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que bajara la rampa, nadie ... el vehículo dentro.'::text,'había visto'::text,'ha visto'::text,'ve'::text,'Antes de que bajara la rampa, nadie había visto el vehículo dentro.'::text),
(400577,44509,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant que la rampe descende, personne ... le véhicule à l''intérieur.'::text,'n''avait vu'::text,'n''a vu'::text,'ne voit'::text,'Avant que la rampe descende, personne n''avait vu le véhicule à l''intérieur.'::text),
(400580,44509,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rampa inmeden önce kimse içerideki aracı ...'::text,'görmemişti'::text,'görmedi'::text,'görmüyor'::text,'Rampa inmeden önce kimse içerideki aracı görmemişti.'::text),
(400581,44509,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt a rámpa leereszkedett, senki ... a járművet odabent.'::text,'nem látta'::text,'nem látta'::text,'nem látja'::text,'Mielőtt a rámpa leereszkedett, senki nem látta a járművet odabent.'::text),
(330870,36764,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziemlich beeindruckend: Du ... den Roboter heute dreimal, als er sich der Kamera näherte.'::text,'fingst'::text,'fingst'::text,'fängst'::text,'Ziemlich beeindruckend: Du fingst den Roboter heute dreimal, als er sich der Kamera näherte.'::text),
(330874,36764,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досить вражає: ти сьогодні ... робота тричі, коли він наближався до камери.'::text,'зловив'::text,'ловив'::text,'ловиш'::text,'Досить вражає: ти сьогодні зловив робота тричі, коли він наближався до камери.'::text),
(330873,36764,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bastante impresionante: hoy ... al robot tres veces mientras se acercaba a la cámara.'::text,'has atrapado'::text,'has estado atrapando'::text,'estás atrapando'::text,'Bastante impresionante: hoy has atrapado al robot tres veces mientras se acercaba a la cámara.'::text),
(330872,36764,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plutôt impressionnant : tu ... le robot trois fois aujourd''hui pendant qu''il s''approchait de la caméra.'::text,'as rattrapé'::text,'rattrapais'::text,'rattrapes'::text,'Plutôt impressionnant : tu as rattrapé le robot trois fois aujourd''hui pendant qu''il s''approchait de la caméra.'::text),
(330875,36764,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oldukça etkileyici: robot kameraya yaklaşırken onu bugün üç kez ...'::text,'yakaladın'::text,'yakalıyordun'::text,'yakalıyorsun'::text,'Oldukça etkileyici: robot kameraya yaklaşırken onu bugün üç kez yakaladın.'::text),
(330876,36764,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elég lenyűgöző: ma háromszor ... el a robotot, ahogy a kamerához közeledett.'::text,'kaptad'::text,'kaptad'::text,'kapod'::text,'Elég lenyűgöző: ma háromszor kaptad el a robotot, ahogy a kamerához közeledett.'::text),
(330879,36765,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor er sich der Kamera näherte, ... der Roboter zweimal das Gleichgewicht. Makellose Technik.'::text,'verlor'::text,'verlor'::text,'verliert'::text,'Bevor er sich der Kamera näherte, verlor der Roboter zweimal das Gleichgewicht. Makellose Technik.'::text),
(330883,36765,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж наблизитися до камери, робот двічі ... рівновагу. Бездоганна інженерія.'::text,'втратив'::text,'втратив'::text,'втрачає'::text,'Перш ніж наблизитися до камери, робот двічі втратив рівновагу. Бездоганна інженерія.'::text),
(330882,36765,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de acercarse a la cámara, el robot ... el equilibrio dos veces. Ingeniería impecable.'::text,'había perdido'::text,'ha perdido'::text,'pierde'::text,'Antes de acercarse a la cámara, el robot había perdido el equilibrio dos veces. Ingeniería impecable.'::text),
(330881,36765,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant de s''approcher de la caméra, le robot ... l''équilibre deux fois. Ingénierie parfaite.'::text,'avait perdu'::text,'a perdu'::text,'perd'::text,'Avant de s''approcher de la caméra, le robot avait perdu l''équilibre deux fois. Ingénierie parfaite.'::text),
(330884,36765,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kameraya yaklaşmadan önce robot iki kez dengesini ..., kusursuz mühendislik.'::text,'kaybetmişti'::text,'kaybetti'::text,'kaybediyor'::text,'Kameraya yaklaşmadan önce robot iki kez dengesini kaybetmişti, kusursuz mühendislik.'::text),
(330885,36765,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt a kamerához közeledett, a robot kétszer ... az egyensúlyát. Hibátlan mérnöki munka.'::text,'elvesztette'::text,'elvesztette'::text,'elveszíti'::text,'Mielőtt a kamerához közeledett, a robot kétszer elvesztette az egyensúlyát. Hibátlan mérnöki munka.'::text),
(330888,36766,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Roboter sich der Kamera zu schnell nähert, ... er wieder.'::text,'stürzt'::text,'würde stürzen'::text,'stürzte'::text,'Wenn der Roboter sich der Kamera zu schnell nähert, stürzt er wieder.'::text),
(330892,36766,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо робот наблизиться до камери надто швидко, він знову ...'::text,'впаде'::text,'впав би'::text,'впав'::text,'Якщо робот наблизиться до камери надто швидко, він знову впаде.'::text),
(330891,36766,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el robot se acerca a la cámara demasiado rápido, se ... otra vez.'::text,'caerá'::text,'caería'::text,'cayó'::text,'Si el robot se acerca a la cámara demasiado rápido, se caerá otra vez.'::text),
(330890,36766,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le robot s''approche trop vite de la caméra, il ... encore.'::text,'tombera'::text,'tomberait'::text,'est tombé'::text,'Si le robot s''approche trop vite de la caméra, il tombera encore.'::text),
(330893,36766,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Robot kameraya çok hızlı yaklaşırsa yine ...'::text,'düşecek'::text,'düşerdi'::text,'düştü'::text,'Robot kameraya çok hızlı yaklaşırsa yine düşecek.'::text),
(330894,36766,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a robot túl gyorsan közelít a kamerához, megint ...'::text,'elesik'::text,'elesne'::text,'elesett'::text,'Ha a robot túl gyorsan közelít a kamerához, megint elesik.'::text),
(330897,36767,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sich der Roboter langsamer näherte, ... der Mann nicht hechten, um ihn zu fangen.'::text,'müsste'::text,'muss'::text,'musste'::text,'Wenn sich der Roboter langsamer näherte, müsste der Mann nicht hechten, um ihn zu fangen.'::text),
(330901,36767,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби робот наближався повільніше, чоловікові ..., щоб його зловити.'::text,'не довелося б кидатися'::text,'не доведеться кидатися'::text,'не довелося кидатися'::text,'Якби робот наближався повільніше, чоловікові не довелося б кидатися, щоб його зловити.'::text),
(330900,36767,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el robot se acercara más despacio, el hombre ... para atraparlo.'::text,'no tendría que lanzarse'::text,'no tendrá que lanzarse'::text,'no tuvo que lanzarse'::text,'Si el robot se acercara más despacio, el hombre no tendría que lanzarse para atraparlo.'::text),
(330899,36767,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le robot s''approchait plus lentement, l''homme ... pour le rattraper.'::text,'n''aurait pas besoin de plonger'::text,'n''aura pas besoin de plonger'::text,'n''a pas eu besoin de plonger'::text,'Si le robot s''approchait plus lentement, l''homme n''aurait pas besoin de plonger pour le rattraper.'::text),
(330902,36767,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Robot daha yavaş yaklaşsaydı, adam onu yakalamak için ...'::text,'atlamak zorunda kalmazdı'::text,'atlamak zorunda kalmayacak'::text,'atlamak zorunda kalmadı'::text,'Robot daha yavaş yaklaşsaydı, adam onu yakalamak için atlamak zorunda kalmazdı.'::text),
(330903,36767,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a robot lassabban közeledne, a férfinak ..., hogy elkapja.'::text,'nem kellene vetődnie'::text,'nem kell majd vetődnie'::text,'nem kellett vetődnie'::text,'Ha a robot lassabban közeledne, a férfinak nem kellene vetődnie, hogy elkapja.'::text),
(330906,36768,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sich der Roboter der Kamera näherte, ... er vom Mann, kurz bevor er fiel.'::text,'wurde aufgefangen'::text,'fing auf'::text,'wird aufgefangen'::text,'Als sich der Roboter der Kamera näherte, wurde aufgefangen er vom Mann, kurz bevor er fiel.'::text),
(330910,36768,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли робот наближався до камери, його ... чоловік якраз перед падінням.'::text,'зловив'::text,'зловив'::text,'ловить'::text,'Коли робот наближався до камери, його зловив чоловік якраз перед падінням.'::text),
(330909,36768,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando el robot se acercaba a la cámara, ... por el hombre justo antes de caer.'::text,'fue atrapado'::text,'atrapó'::text,'es atrapado'::text,'Cuando el robot se acercaba a la cámara, fue atrapado por el hombre justo antes de caer.'::text),
(330908,36768,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alors que le robot s''approchait de la caméra, il ... par l''homme juste avant de tomber.'::text,'a été rattrapé'::text,'a rattrapé'::text,'est rattrapé'::text,'Alors que le robot s''approchait de la caméra, il a été rattrapé par l''homme juste avant de tomber.'::text),
(330911,36768,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Robot kameraya yaklaşırken, düşmeden hemen önce adam tarafından ...'::text,'yakalandı'::text,'yakaladı'::text,'yakalanıyor'::text,'Robot kameraya yaklaşırken, düşmeden hemen önce adam tarafından yakalandı.'::text),
(330912,36768,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahogy a robot a kamerához közeledett, a férfi ... közvetlenül azelőtt, hogy elesett.'::text,'elkapta'::text,'elkapta'::text,'elkapja'::text,'Ahogy a robot a kamerához közeledett, a férfi elkapta közvetlenül azelőtt, hogy elesett.'::text),
(330915,36769,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Roboter ... sich der Kamera, dann brach er zusammen und hätte sich fast zerstört!'::text,'näherte'::text,'wurde genähert'::text,'nähernd'::text,'Der Roboter näherte sich der Kamera, dann brach er zusammen und hätte sich fast zerstört!'::text),
(330919,36769,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Робот ... до камери, потім упав і ледь не знищив себе!'::text,'наблизився'::text,'був наближений'::text,'наближаючись'::text,'Робот наблизився до камери, потім упав і ледь не знищив себе!'::text),
(330918,36769,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El robot se ... a la cámara, luego se desplomó y casi se destruye!'::text,'acercó'::text,'fue acercado'::text,'acercando'::text,'¡El robot se acercó a la cámara, luego se desplomó y casi se destruye!'::text),
(330917,36769,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le robot ... de la caméra, puis il s''est effondré et a failli se détruire !'::text,'s''est approché'::text,'a été approché'::text,'s''approchant'::text,'Le robot s''est approché de la caméra, puis il s''est effondré et a failli se détruire !'::text),
(330920,36769,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Robot kameraya ..., sonra çöktü ve neredeyse kendini parçaladı!'::text,'yaklaştı'::text,'yaklaşıldı'::text,'yaklaşarak'::text,'Robot kameraya yaklaştı, sonra çöktü ve neredeyse kendini parçaladı!'::text),
(330921,36769,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A robot ... a kamerához, aztán összeesett, és majdnem tönkretette magát!'::text,'odament'::text,'odavitték'::text,'odamenve'::text,'A robot odament a kamerához, aztán összeesett, és majdnem tönkretette magát!'::text),
(330924,36770,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schnapp ihn dir! Der Roboter nähert sich dem Rand und ... jede Sekunde zusammenbrechen!'::text,'könnte'::text,'muss'::text,'muss'::text,'Schnapp ihn dir! Der Roboter nähert sich dem Rand und könnte jede Sekunde zusammenbrechen!'::text),
(330928,36770,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хапай його! Робот наближається до краю і ... впасти будь-якої секунди!'::text,'може'::text,'мусить'::text,'має'::text,'Хапай його! Робот наближається до краю і може впасти будь-якої секунди!'::text),
(330927,36770,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Agárralo! El robot se acerca al borde, ¡y ... desplomarse en cualquier momento!'::text,'podría'::text,'debe'::text,'necesita'::text,'¡Agárralo! El robot se acerca al borde, ¡y podría desplomarse en cualquier momento!'::text),
(330926,36770,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attrape-le ! Le robot s''approche du bord, et il ... s''effondrer d''une seconde à l''autre !'::text,'pourrait'::text,'doit'::text,'a besoin de'::text,'Attrape-le ! Le robot s''approche du bord, et il pourrait s''effondrer d''une seconde à l''autre !'::text),
(330929,36770,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yakala onu! Robot kenara yaklaşıyor ve her an ...!'::text,'çökebilir'::text,'çökmeli'::text,'çökmesi gerekiyor'::text,'Yakala onu! Robot kenara yaklaşıyor ve her an çökebilir!'::text),
(330930,36770,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapd el! A robot a széléhez közeledik, és bármelyik pillanatban ...!'::text,'összeeshet'::text,'össze kell esnie'::text,'össze kell esnie'::text,'Kapd el! A robot a széléhez közeledik, és bármelyik pillanatban összeeshet!'::text),
(330933,36771,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich hat der Typ, ... gefilmt hat, geschrien, als der Roboter näherkam.'::text,'der'::text,'welches'::text,'dessen'::text,'Hör zu, angeblich hat der Typ, der gefilmt hat, geschrien, als der Roboter näherkam.'::text),
(330937,36771,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, хлопець, ... знімав, кричав, коли робот наближався.'::text,'який'::text,'котрий'::text,'чий'::text,'Слухай, кажуть, хлопець, який знімав, кричав, коли робот наближався.'::text),
(330936,36771,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, al parecer el chico ... estaba grabando gritó cuando se acercó el robot.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Escucha, al parecer el chico que estaba grabando gritó cuando se acercó el robot.'::text),
(330935,36771,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment le mec ... filmait a crié quand le robot s''est approché.'::text,'qui'::text,'lequel'::text,'dont'::text,'Écoute, apparemment le mec qui filmait a crié quand le robot s''est approché.'::text),
(330938,36771,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre ... çeken adam robot yaklaşınca bağırmış.'::text,''::text,NULL::text,NULL::text,'Dinle, duyduğuma göre çeken adam robot yaklaşınca bağırmış.'::text),
(330939,36771,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a srác, ... filmezett, kiabált, amikor a robot közeledett.'::text,'aki'::text,'amely'::text,'akinek'::text,'Figyelj, állítólag a srác, aki filmezett, kiabált, amikor a robot közeledett.'::text),
(330942,36772,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Babe, er hat mir erzählt, dass der Roboter zweimal ..., bevor er sich der Kamera näherte.'::text,'hingefallen war'::text,'hingefallen ist'::text,'hinfällt'::text,'Babe, er hat mir erzählt, dass der Roboter zweimal hingefallen war, bevor er sich der Kamera näherte.'::text),
(330946,36772,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що робот ... двічі, перш ніж наблизився до камери.'::text,'впав'::text,'впав'::text,'падає'::text,'Подруго, він сказав мені, що робот впав двічі, перш ніж наблизився до камери.'::text),
(330945,36772,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que el robot se ... dos veces antes de acercarse a la cámara.'::text,'había caído'::text,'ha caído'::text,'cae'::text,'Tía, me dijo que el robot se había caído dos veces antes de acercarse a la cámara.'::text),
(330944,36772,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit que le robot ... deux fois avant de s''approcher de la caméra.'::text,'était tombé'::text,'est tombé'::text,'tombe'::text,'Meuf, il m''a dit que le robot était tombé deux fois avant de s''approcher de la caméra.'::text),
(330947,36772,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana robotun kameraya yaklaşmadan önce iki kez ... söyledi.'::text,'düştüğünü'::text,'düştüğünü'::text,'düştüğünü'::text,'Kızım, bana robotun kameraya yaklaşmadan önce iki kez düştüğünü söyledi.'::text),
(330948,36772,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy a robot kétszer ..., mielőtt a kamerához közeledett.'::text,'elesett'::text,'elesett'::text,'elesik'::text,'Csajszi, azt mondta, hogy a robot kétszer elesett, mielőtt a kamerához közeledett.'::text),
(330960,36774,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast nicht gezögert, ..., als der Roboter näherkam und zu fallen begann. Respekt.'::text,'zu hechten'::text,'zu hechten'::text,'zu hechten'::text,'Du hast nicht gezögert, zu hechten, als der Roboter näherkam und zu fallen begann. Respekt.'::text),
(330964,36774,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти не вагався ..., коли робот наблизився й почав падати. Респект.'::text,'кинутися'::text,'кинутися'::text,'кинутися'::text,'Ти не вагався кинутися, коли робот наблизився й почав падати. Респект.'::text),
(330963,36774,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No dudaste en ... cuando el robot se acercó y empezó a caerse. Respeto.'::text,'lanzarte'::text,'lanzarte'::text,'lanzarte'::text,'No dudaste en lanzarte cuando el robot se acercó y empezó a caerse. Respeto.'::text),
(330962,36774,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu n''as pas hésité à ... quand le robot s''est approché et a commencé à tomber. Respect.'::text,'plonger'::text,'plonger'::text,'plonger'::text,'Tu n''as pas hésité à plonger quand le robot s''est approché et a commencé à tomber. Respect.'::text),
(330965,36774,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Robot yaklaşıp düşmeye başladığında ... tereddüt etmedin. Saygı.'::text,'atlamaktan'::text,'atlamaktan'::text,'atlamaktan'::text,'Robot yaklaşıp düşmeye başladığında atlamaktan tereddüt etmedin. Saygı.'::text),
(330966,36774,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem haboztál ..., amikor a robot közeledett és elkezdett eldőlni. Respekt.'::text,'vetődni'::text,'vetődni'::text,'vetődni'::text,'Nem haboztál vetődni, amikor a robot közeledett és elkezdett eldőlni. Respekt.'::text),
(378012,42002,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Läufer sollen seit über 20 Jahren durch diese Allee ...'::text,'rennen'::text,'rennen'::text,'rennen'::text,'Die Läufer sollen seit über 20 Jahren durch diese Allee rennen.'::text),
(378016,42002,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що бігуни ... цією алеєю вже понад 20 років.'::text,'бігають'::text,'бігають'::text,'біг'::text,'Кажуть, що бігуни бігають цією алеєю вже понад 20 років.'::text),
(378015,42002,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que los corredores ... por esta avenida desde hace más de 20 años.'::text,'han estado corriendo'::text,'corren'::text,'corriendo'::text,'Se dice que los corredores han estado corriendo por esta avenida desde hace más de 20 años.'::text),
(378014,42002,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que les coureurs ... dans cette avenue depuis plus de 20 ans.'::text,'courent'::text,'courent'::text,'courant'::text,'On dit que les coureurs courent dans cette avenue depuis plus de 20 ans.'::text),
(378017,42002,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koşucuların 20 yılı aşkın süredir bu caddede ... söyleniyor.'::text,'yarıştığı'::text,'yarıştığı'::text,'yarışarak'::text,'Koşucuların 20 yılı aşkın süredir bu caddede yarıştığı söyleniyor.'::text),
(378018,42002,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, a futók több mint 20 éve ... ezen a fasoron.'::text,'versenyeznek'::text,'versenyeznek'::text,'versenyezve'::text,'Azt mondják, a futók több mint 20 éve versenyeznek ezen a fasoron.'::text),
(378021,42003,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Veranstalter rieten den Läufern, vorsichtig an der Frau auf der Straße ...'::text,'vorbeizurennen'::text,'vorbeizurennen'::text,'vorbeigerannt'::text,'Die Veranstalter rieten den Läufern, vorsichtig an der Frau auf der Straße vorbeizurennen.'::text),
(378025,42003,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Організатори порадили бігунам ... обережно повз жінку на дорозі.'::text,'бігти'::text,'біг'::text,'бігли'::text,'Організатори порадили бігунам бігти обережно повз жінку на дорозі.'::text),
(378024,42003,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los organizadores aconsejaron a los corredores ... con cuidado al pasar junto a la mujer en la carretera.'::text,'correr'::text,'corriendo'::text,'corrieron'::text,'Los organizadores aconsejaron a los corredores correr con cuidado al pasar junto a la mujer en la carretera.'::text),
(378023,42003,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les organisateurs ont conseillé aux coureurs de ... prudemment devant la femme sur la route.'::text,'courir'::text,'courir'::text,'couru'::text,'Les organisateurs ont conseillé aux coureurs de courir prudemment devant la femme sur la route.'::text),
(378026,42003,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Organizatörler koşuculara yoldaki kadının yanından dikkatle ... tavsiye etti.'::text,'koşmalarını'::text,'koşmayı'::text,'koştular'::text,'Organizatörler koşuculara yoldaki kadının yanından dikkatle koşmalarını tavsiye etti.'::text),
(378027,42003,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szervezők azt tanácsolták a futóknak, hogy óvatosan ... el az úton álló nő mellett.'::text,'fussanak'::text,'futás'::text,'futottak'::text,'A szervezők azt tanácsolták a futóknak, hogy óvatosan fussanak el az úton álló nő mellett.'::text),
(378030,42004,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Läufer ... sie gesehen haben, weil alle um sie herumrannten, ohne sie zu berühren.'::text,'müssen'::text,'hätten sollen'::text,'können nicht'::text,'Die Läufer müssen sie gesehen haben, weil alle um sie herumrannten, ohne sie zu berühren.'::text),
(378034,42004,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бігуни ... її бачити, бо всі оббігли її, не торкнувшись.'::text,'мусили'::text,'мали'::text,'не могли'::text,'Бігуни мусили її бачити, бо всі оббігли її, не торкнувшись.'::text),
(378033,42004,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los corredores ... haberla visto, porque todos la rodearon sin tocarla.'::text,'deben de'::text,'deberían'::text,'no pueden'::text,'Los corredores deben de haberla visto, porque todos la rodearon sin tocarla.'::text),
(378032,42004,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les coureurs ... l''avoir vue, parce qu''ils l''ont tous contournée sans la toucher.'::text,'doivent'::text,'auraient dû'::text,'ne peuvent pas'::text,'Les coureurs doivent l''avoir vue, parce qu''ils l''ont tous contournée sans la toucher.'::text),
(378035,42004,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koşucular onu görmüş ..., çünkü hepsi ona dokunmadan etrafından koştu.'::text,'olmalı'::text,'olmalıydı'::text,'olamaz'::text,'Koşucular onu görmüş olmalı, çünkü hepsi ona dokunmadan etrafından koştu.'::text),
(378036,42004,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A futók ... látták őt, mert mindannyian megkerülték anélkül, hogy hozzáértek volna.'::text,'biztosan'::text,'elvileg'::text,'biztosan nem'::text,'A futók biztosan látták őt, mert mindannyian megkerülték anélkül, hogy hozzáértek volna.'::text),
(378039,42005,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht ein einziges Mal ... sich, als Hunderte Läufer vorbeirannten. Absolut furchtlos!'::text,'bewegte sie'::text,'sie bewegte'::text,'sie bewegte nicht'::text,'Nicht ein einziges Mal bewegte sie sich, als Hunderte Läufer vorbeirannten. Absolut furchtlos!'::text),
(378043,42005,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жодного разу ..., коли сотні бігунів мчали повз. Абсолютно безстрашна!'::text,'вона не поворухнулася'::text,'вона поворухнулася'::text,'вона не поворухнулася'::text,'Жодного разу вона не поворухнулася, коли сотні бігунів мчали повз. Абсолютно безстрашна!'::text),
(378042,42005,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ni una sola vez ... mientras cientos de corredores pasaban corriendo. ¡Totalmente valiente!'::text,'se movió'::text,'se movió'::text,'no se movió'::text,'Ni una sola vez se movió mientras cientos de corredores pasaban corriendo. ¡Totalmente valiente!'::text),
(378041,42005,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pas une seule fois ... quand des centaines de coureurs sont passés. Totalement intrépide !'::text,'n''a-t-elle bougé'::text,'elle a bougé'::text,'elle n''a pas bougé'::text,'Pas une seule fois n''a-t-elle bougé quand des centaines de coureurs sont passés. Totalement intrépide !'::text),
(378044,42005,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüzlerce koşucu yanından geçerken bir kez bile ..., tamamen korkusuz!'::text,'kıpırdamadı'::text,'kıpırdadı'::text,'kıpırdamadı'::text,'Yüzlerce koşucu yanından geçerken bir kez bile kıpırdamadı, tamamen korkusuz!'::text),
(378045,42005,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyszer sem ..., miközben száz meg száz futó száguldott el mellette. Teljesen rettenthetetlen!'::text,'mozdult meg'::text,'mozdult meg'::text,'nem mozdult meg'::text,'Egyszer sem mozdult meg, miközben száz meg száz futó száguldott el mellette. Teljesen rettenthetetlen!'::text),
(378048,42006,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, angeblich hat sie ihre Freundin am Abend vor dem Rennen das Schild ... lassen.'::text,'schreiben'::text,'schreiben'::text,'geschrieben'::text,'Omg, angeblich hat sie ihre Freundin am Abend vor dem Rennen das Schild schreiben lassen.'::text),
(378052,42006,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Боже, кажуть, вона попросила подругу ... табличку ввечері перед забігом.'::text,'написати'::text,'написати'::text,'написану'::text,'Боже, кажуть, вона попросила подругу написати табличку ввечері перед забігом.'::text),
(378051,42006,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dios, al parecer hizo que su amiga ... el cartel la noche antes de la carrera.'::text,'escribiera'::text,'escribiera'::text,'escrito'::text,'Dios, al parecer hizo que su amiga escribiera el cartel la noche antes de la carrera.'::text),
(378050,42006,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, apparemment elle a fait ... la pancarte à son amie la veille de la course.'::text,'écrire'::text,'écrire'::text,'écrit'::text,'Omg, apparemment elle a fait écrire la pancarte à son amie la veille de la course.'::text),
(378053,42006,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aman tanrım, duyduğuma göre tabelayı yarıştan önceki gece arkadaşına ...'::text,'yazdırmış'::text,'yazdırmış'::text,'yazılmış'::text,'Aman tanrım, duyduğuma göre tabelayı yarıştan önceki gece arkadaşına yazdırmış.'::text),
(378054,42006,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úristen, állítólag a barátnőjével ... meg a táblát a verseny előtti este.'::text,'íratta'::text,'íratta'::text,'megírt'::text,'Úristen, állítólag a barátnőjével íratta meg a táblát a verseny előtti este.'::text),
(378057,42007,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Babe, sie hat mir erzählt, sie wünscht sich, sie ... mit ihnen rennen, statt nur das Schild zu halten.'::text,'könnte'::text,'kann'::text,'würde'::text,'Babe, sie hat mir erzählt, sie wünscht sich, sie könnte mit ihnen rennen, statt nur das Schild zu halten.'::text),
(378061,42007,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що хотіла б, щоб ... з ними, а не просто тримати табличку.'::text,'могла бігти'::text,'може бігти'::text,'біжить'::text,'Подруго, вона сказала мені, що хотіла б, щоб могла бігти з ними, а не просто тримати табличку.'::text),
(378060,42007,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que desearía ... con ellos en vez de solo sujetar el cartel.'::text,'poder correr'::text,'puede correr'::text,'corre'::text,'Tía, me dijo que desearía poder correr con ellos en vez de solo sujetar el cartel.'::text),
(378059,42007,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle m''a dit qu''elle aimerait ... avec eux au lieu de juste tenir la pancarte.'::text,'pouvoir courir'::text,'peut courir'::text,'court'::text,'Meuf, elle m''a dit qu''elle aimerait pouvoir courir avec eux au lieu de juste tenir la pancarte.'::text),
(378062,42007,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana sadece tabelayı tutmak yerine onlarla ... dilediğini söyledi.'::text,'yarışabilmeyi'::text,'yarışabildiğini'::text,'yarıştığını'::text,'Kızım, bana sadece tabelayı tutmak yerine onlarla yarışabilmeyi dilediğini söyledi.'::text),
(378063,42007,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, azt szeretné, ha ... velük, ahelyett hogy csak a táblát tartja.'::text,'versenyezhetne'::text,'versenyezhet'::text,'versenyez'::text,'Csajszi, azt mondta, azt szeretné, ha versenyezhetne velük, ahelyett hogy csak a táblát tartja.'::text),
(378066,42008,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, die Frau, ... Schild alle gelesen haben, rennt angeblich selbst nie.'::text,'deren'::text,'die'::text,'welche'::text,'Hör zu, die Frau, deren Schild alle gelesen haben, rennt angeblich selbst nie.'::text),
(378070,42008,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, жінка, ... табличку всі читали, кажуть, сама ніколи не бігає.'::text,'чию'::text,'яка'::text,'котра'::text,'Слухай, жінка, чию табличку всі читали, кажуть, сама ніколи не бігає.'::text),
(378069,42008,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, la mujer, ... cartel leía todo el mundo, al parecer nunca corre.'::text,'cuyo'::text,'que'::text,'la cual'::text,'Escucha, la mujer, cuyo cartel leía todo el mundo, al parecer nunca corre.'::text),
(378068,42008,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, la femme, ... tout le monde lisait la pancarte, ne court apparemment jamais elle-même.'::text,'dont'::text,'qui'::text,'laquelle'::text,'Écoute, la femme, dont tout le monde lisait la pancarte, ne court apparemment jamais elle-même.'::text),
(378071,42008,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, ... herkesin tabelasını okuduğu kadın, duyduğuma göre kendisi hiç koşmuyormuş.'::text,''::text,NULL::text,NULL::text,'Dinle, herkesin tabelasını okuduğu kadın, duyduğuma göre kendisi hiç koşmuyormuş.'::text),
(378072,42008,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, az a nő, ... tábláját mindenki olvasta, állítólag maga sosem fut.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Figyelj, az a nő, akinek a tábláját mindenki olvasta, állítólag maga sosem fut.'::text),
(378075,42009,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Läufer rannten ... des nassen Laubs auf der Straße weiter.'::text,'trotz'::text,'obwohl'::text,'weil'::text,'Die Läufer rannten trotz des nassen Laubs auf der Straße weiter.'::text),
(378079,42009,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бігуни продовжували бігти ... мокре листя на дорозі.'::text,'попри'::text,'хоча'::text,'бо'::text,'Бігуни продовжували бігти попри мокре листя на дорозі.'::text),
(378078,42009,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los corredores siguieron corriendo ... las hojas mojadas de la carretera.'::text,'a pesar de'::text,'aunque'::text,'porque'::text,'Los corredores siguieron corriendo a pesar de las hojas mojadas de la carretera.'::text),
(378077,42009,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les coureurs ont continué à courir ... les feuilles mouillées sur la route.'::text,'malgré'::text,'bien que'::text,'parce que'::text,'Les coureurs ont continué à courir malgré les feuilles mouillées sur la route.'::text),
(378080,42009,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koşucular yoldaki ıslak yapraklara ... koşmaya devam etti.'::text,'rağmen'::text,'her ne kadar'::text,'çünkü'::text,'Koşucular yoldaki ıslak yapraklara rağmen koşmaya devam etti.'::text),
(378081,42009,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A futók az úton lévő nedves levelek ... tovább futottak.'::text,'ellenére'::text,'habár'::text,'mert'::text,'A futók az úton lévő nedves levelek ellenére tovább futottak.'::text),
(378084,42010,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du wusstest, dass sie direkt an dir ..., und du bliebst so ruhig.'::text,'vorbeirennen würden'::text,'vorbeirennen werden'::text,'vorbeirennen'::text,'Respekt, du wusstest, dass sie direkt an dir vorbeirennen würden, und du bliebst so ruhig.'::text),
(378088,42010,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти знала, що вони ... прямо повз тебе, і залишалася такою спокійною.'::text,'промчать'::text,'промчать'::text,'мчать'::text,'Респект, ти знала, що вони промчать прямо повз тебе, і залишалася такою спокійною.'::text),
(378087,42010,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, sabías que ... justo a tu lado, y te quedaste tan tranquila.'::text,'pasarían corriendo'::text,'pasarán corriendo'::text,'están pasando corriendo'::text,'Respeto, sabías que pasarían corriendo justo a tu lado, y te quedaste tan tranquila.'::text),
(378086,42010,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, tu savais qu''ils ... juste à côté de toi, et tu es restée si calme.'::text,'fonceraient'::text,'fonceront'::text,'foncent'::text,'Respect, tu savais qu''ils fonceraient juste à côté de toi, et tu es restée si calme.'::text),
(378089,42010,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygı, hemen yanından hızla ... biliyordun ve çok sakin kaldın.'::text,'geçeceklerini'::text,'geçeceklerini'::text,'geçtiklerini'::text,'Saygı, hemen yanından hızla geçeceklerini biliyordun ve çok sakin kaldın.'::text),
(378090,42010,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, tudtad, hogy egyenesen melletted ..., és olyan nyugodt maradtál.'::text,'fognak elszáguldani'::text,'fognak elszáguldani'::text,'száguldanak el'::text,'Respekt, tudtad, hogy egyenesen melletted fognak elszáguldani, és olyan nyugodt maradtál.'::text),
(378093,42011,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hunderte Läufer ... gerade an ihr vorbei, und sie hat sich nicht bewegt. Makelloses Versteck.'::text,'rennen'::text,'rennen'::text,'sind gerannt'::text,'Hunderte Läufer rennen gerade an ihr vorbei, und sie hat sich nicht bewegt. Makelloses Versteck.'::text),
(378097,42011,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сотні бігунів ... повз неї просто зараз, а вона не поворухнулася. Бездоганна схованка.'::text,'мчать'::text,'мчать'::text,'промчали'::text,'Сотні бігунів мчать повз неї просто зараз, а вона не поворухнулася. Бездоганна схованка.'::text),
(378096,42011,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cientos de corredores ... junto a ella ahora mismo, y no se ha movido. Escondite perfecto.'::text,'están pasando'::text,'pasan'::text,'han pasado'::text,'Cientos de corredores están pasando junto a ella ahora mismo, y no se ha movido. Escondite perfecto.'::text),
(378095,42011,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des centaines de coureurs ... devant elle en ce moment, et elle n''a pas bougé. Cachette parfaite.'::text,'foncent'::text,'foncent'::text,'ont foncé'::text,'Des centaines de coureurs foncent devant elle en ce moment, et elle n''a pas bougé. Cachette parfaite.'::text),
(378098,42011,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüzlerce koşucu şu anda yanından ... ve o hiç kıpırdamadı. Kusursuz saklanma yeri.'::text,'geçiyor'::text,'geçer'::text,'geçti'::text,'Yüzlerce koşucu şu anda yanından geçiyor ve o hiç kıpırdamadı. Kusursuz saklanma yeri.'::text),
(378099,42011,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Száz meg száz futó ... el mellette épp most, és ő meg sem mozdult. Hibátlan búvóhely.'::text,'száguld'::text,'száguld'::text,'száguldott'::text,'Száz meg száz futó száguld el mellette épp most, és ő meg sem mozdult. Hibátlan búvóhely.'::text),
(358068,39786,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Otter ... sich an der Bambusstange fest, als der riesige Fisch unter ihm abtauchte.'::text,'hielt'::text,'hielt'::text,'hielt'::text,'Der Otter hielt sich an der Bambusstange fest, als der riesige Fisch unter ihm abtauchte.'::text),
(358072,39786,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Видра ... за бамбукову жердину, коли велетенська риба опустилася під неї.'::text,'трималася'::text,'вчепилася'::text,'вчепилася'::text,'Видра трималася за бамбукову жердину, коли велетенська риба опустилася під неї.'::text),
(358071,39786,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La nutria ... al palo de bambú cuando el pez gigante se hundió debajo de ella.'::text,'estaba aferrada'::text,'se aferró'::text,'se ha aferrado'::text,'La nutria estaba aferrada al palo de bambú cuando el pez gigante se hundió debajo de ella.'::text),
(358070,39786,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La loutre ... au bâton de bambou quand le poisson géant a coulé sous elle.'::text,'s''accrochait'::text,'s''est accrochée'::text,'s''est accrochée'::text,'La loutre s''accrochait au bâton de bambou quand le poisson géant a coulé sous elle.'::text),
(358073,39786,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev balık altına battığında su samuru bambu direğe ...'::text,'tutunuyordu'::text,'tutundu'::text,'tutundu'::text,'Dev balık altına battığında su samuru bambu direğe tutunuyordu.'::text),
(358074,39786,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vidra éppen ... a bambuszrúdba, amikor az óriási hal alámerült alatta.'::text,'kapaszkodott'::text,'belekapaszkodott'::text,'belekapaszkodott'::text,'A vidra éppen kapaszkodott a bambuszrúdba, amikor az óriási hal alámerült alatta.'::text),
(358077,39787,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der riesige Fisch ... schon seit mehreren Minuten hinter dem Otter.'::text,'treibt'::text,'treibt'::text,'treibt'::text,'Der riesige Fisch treibt schon seit mehreren Minuten hinter dem Otter.'::text),
(358081,39787,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велетенська риба ... позаду видри вже кілька хвилин.'::text,'плаває'::text,'плаває'::text,'плаває'::text,'Велетенська риба плаває позаду видри вже кілька хвилин.'::text),
(358080,39787,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pez gigante ... detrás de la nutria desde hace varios minutos.'::text,'ha estado flotando'::text,'está flotando'::text,'flota'::text,'El pez gigante ha estado flotando detrás de la nutria desde hace varios minutos.'::text),
(358079,39787,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poisson géant ... derrière la loutre depuis plusieurs minutes.'::text,'flotte'::text,'flotte'::text,'flotte'::text,'Le poisson géant flotte derrière la loutre depuis plusieurs minutes.'::text),
(358082,39787,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev balık birkaç dakikadır su samurunun arkasında ...'::text,'süzülüyor'::text,'süzülüyor'::text,'süzülür'::text,'Dev balık birkaç dakikadır su samurunun arkasında süzülüyor.'::text),
(358083,39787,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az óriási hal már percek óta ... a vidra mögött.'::text,'lebeg'::text,'lebeg'::text,'lebeg'::text,'Az óriási hal már percek óta lebeg a vidra mögött.'::text),
(358086,39788,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der riesige Fisch ... unter Wasser und kam dann grinsend wieder hoch.'::text,'tauchte'::text,'tauchte gerade'::text,'tauchte'::text,'Der riesige Fisch tauchte unter Wasser und kam dann grinsend wieder hoch.'::text),
(358090,39788,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велетенська риба ... під воду, а потім, усміхаючись, повернулася нагору.'::text,'пірнула'::text,'пірнала'::text,'пірнула'::text,'Велетенська риба пірнула під воду, а потім, усміхаючись, повернулася нагору.'::text),
(358089,39788,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pez gigante se ... bajo el agua y luego volvió a subir sonriendo.'::text,'hundió'::text,'estaba hundiendo'::text,'ha hundido'::text,'El pez gigante se hundió bajo el agua y luego volvió a subir sonriendo.'::text),
(358088,39788,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poisson géant ... sous l''eau puis est remonté en souriant.'::text,'a coulé'::text,'coulait'::text,'a coulé'::text,'Le poisson géant a coulé sous l''eau puis est remonté en souriant.'::text),
(358091,39788,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev balık suyun altına ... ve sonra sırıtarak geri çıktı.'::text,'battı'::text,'batıyordu'::text,'battı'::text,'Dev balık suyun altına battı ve sonra sırıtarak geri çıktı.'::text),
(358092,39788,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az óriási hal ... a víz alá, aztán vigyorogva visszajött.'::text,'lemerült'::text,'merült'::text,'lemerült'::text,'Az óriási hal lemerült a víz alá, aztán vigyorogva visszajött.'::text),
(358095,39789,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der riesige Fisch ... im Beobachtungszeitraum dreimal an die Oberfläche.'::text,'stieg'::text,'stieg'::text,'steigt'::text,'Der riesige Fisch stieg im Beobachtungszeitraum dreimal an die Oberfläche.'::text),
(358099,39789,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велетенська риба ... на поверхню тричі за період спостереження.'::text,'піднялася'::text,'піднімалася'::text,'піднімається'::text,'Велетенська риба піднялася на поверхню тричі за період спостереження.'::text),
(358098,39789,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pez gigante ... a la superficie tres veces en el periodo observado.'::text,'ha subido'::text,'ha estado subiendo'::text,'sube'::text,'El pez gigante ha subido a la superficie tres veces en el periodo observado.'::text),
(358097,39789,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poisson géant ... à la surface trois fois pendant la période observée.'::text,'est remonté'::text,'remontait'::text,'remonte'::text,'Le poisson géant est remonté à la surface trois fois pendant la période observée.'::text),
(358100,39789,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev balık gözlem süresi boyunca üç kez yüzeye ...'::text,'çıktı'::text,'çıkıyordu'::text,'çıkar'::text,'Dev balık gözlem süresi boyunca üç kez yüzeye çıktı.'::text),
(358101,39789,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az óriási hal a megfigyelt időszakban háromszor ... a felszínre.'::text,'jött fel'::text,'jött fel'::text,'jön fel'::text,'Az óriási hal a megfigyelt időszakban háromszor jött fel a felszínre.'::text),
(358104,39790,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der riesige Fisch wieder auftauchte, ... der Otter seinen Griff an der Stange erheblich.'::text,'verstärkte'::text,'verstärkte'::text,'verstärkt'::text,'Als der riesige Fisch wieder auftauchte, verstärkte der Otter seinen Griff an der Stange erheblich.'::text),
(358108,39790,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли велетенська риба знову з''явилася, видра значно ... хватку на жердині.'::text,'посилила'::text,'посилила'::text,'посилює'::text,'Коли велетенська риба знову з''явилася, видра значно посилила хватку на жердині.'::text),
(358107,39790,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el pez gigante reapareció, la nutria ... considerablemente su agarre al palo.'::text,'había reforzado'::text,'ha reforzado'::text,'refuerza'::text,'Para cuando el pez gigante reapareció, la nutria había reforzado considerablemente su agarre al palo.'::text),
(358106,39790,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le poisson géant est réapparu, la loutre ... considérablement sa prise sur le bâton.'::text,'avait resserré'::text,'a resserré'::text,'resserre'::text,'Quand le poisson géant est réapparu, la loutre avait resserré considérablement sa prise sur le bâton.'::text),
(358109,39790,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev balık yeniden ortaya çıktığında su samuru direği önemli ölçüde daha sıkı ...'::text,'kavramıştı'::text,'kavradı'::text,'kavrıyor'::text,'Dev balık yeniden ortaya çıktığında su samuru direği önemli ölçüde daha sıkı kavramıştı.'::text),
(358110,39790,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire az óriási hal újra felbukkant, a vidra jelentősen ... a szorítását a rúdon.'::text,'megerősítette'::text,'megerősítette'::text,'erősíti'::text,'Mire az óriási hal újra felbukkant, a vidra jelentősen megerősítette a szorítását a rúdon.'::text),
(358113,39791,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der riesige Fisch wieder auftaucht, ... sich das Exemplar fest an die Stange.'::text,'klammert'::text,'würde klammern'::text,'klammerte'::text,'Wenn der riesige Fisch wieder auftaucht, klammert sich das Exemplar fest an die Stange.'::text),
(358117,39791,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо велетенська риба знову спливе, особина міцно ... за жердину.'::text,'учепиться'::text,'учепилася б'::text,'учепилася'::text,'Якщо велетенська риба знову спливе, особина міцно учепиться за жердину.'::text),
(358116,39791,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el pez gigante vuelve a salir, el espécimen se ... con fuerza al palo.'::text,'aferrará'::text,'aferraría'::text,'aferró'::text,'Si el pez gigante vuelve a salir, el espécimen se aferrará con fuerza al palo.'::text),
(358115,39791,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le poisson géant refait surface, le spécimen ... fermement au bâton.'::text,'s''accrochera'::text,'s''accrocherait'::text,'s''est accroché'::text,'Si le poisson géant refait surface, le spécimen s''accrochera fermement au bâton.'::text),
(358118,39791,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev balık yeniden yüzeye çıkarsa, denek direğe sıkıca ...'::text,'tutunacak'::text,'tutunurdu'::text,'tutundu'::text,'Dev balık yeniden yüzeye çıkarsa, denek direğe sıkıca tutunacak.'::text),
(358119,39791,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az óriási hal újra felbukkan, a példány szorosan ... a rúdba.'::text,'kapaszkodik'::text,'kapaszkodna'::text,'kapaszkodott'::text,'Ha az óriási hal újra felbukkan, a példány szorosan kapaszkodik a rúdba.'::text),
(358122,39792,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Fisch klein wäre, ... er nicht riesig, weil klein nicht riesig ist.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn der Fisch klein wäre, wäre er nicht riesig, weil klein nicht riesig ist.'::text),
(358126,39792,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби риба була маленькою, вона ... велетенською, бо маленьке — не велетенське.'::text,'не була б'::text,'не буде'::text,'не є'::text,'Якби риба була маленькою, вона не була б велетенською, бо маленьке — не велетенське.'::text),
(358125,39792,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el pez fuera pequeño, ... gigante, porque pequeño no es gigante.'::text,'no sería'::text,'no será'::text,'no es'::text,'Si el pez fuera pequeño, no sería gigante, porque pequeño no es gigante.'::text),
(358124,39792,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le poisson était petit, il ... géant, parce que petit, ce n''est pas géant.'::text,'ne serait pas'::text,'ne sera pas'::text,'n''est pas'::text,'Si le poisson était petit, il ne serait pas géant, parce que petit, ce n''est pas géant.'::text),
(358127,39792,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Balık küçük olsaydı, dev ..., çünkü küçük dev değildir.'::text,'olmazdı'::text,'olmayacak'::text,'değil'::text,'Balık küçük olsaydı, dev olmazdı, çünkü küçük dev değildir.'::text),
(358128,39792,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a hal kicsi lenne, ... óriási, mert a kicsi nem óriási.'::text,'nem lenne'::text,'nem lesz'::text,'nem'::text,'Ha a hal kicsi lenne, nem lenne óriási, mert a kicsi nem óriási.'::text),
(358131,39793,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Otter ... von einem riesigen Fisch beobachtet, also war er nicht allein.'::text,'wurde'::text,'beobachtete'::text,'wird'::text,'Der Otter wurde von einem riesigen Fisch beobachtet, also war er nicht allein.'::text),
(358135,39793,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'За видрою ... велетенська риба, тож вона була не сама.'::text,'спостерігала'::text,'спостерігала'::text,'спостерігає'::text,'За видрою спостерігала велетенська риба, тож вона була не сама.'::text),
(358134,39793,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La nutria ... por un pez gigante, así que no estaba sola.'::text,'era observada'::text,'observaba'::text,'es observada'::text,'La nutria era observada por un pez gigante, así que no estaba sola.'::text),
(358133,39793,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La loutre ... par un poisson géant, donc elle n''était pas seule.'::text,'était observée'::text,'observait'::text,'est observée'::text,'La loutre était observée par un poisson géant, donc elle n''était pas seule.'::text),
(358136,39793,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su samuru dev bir balık tarafından ..., yani yalnız değildi.'::text,'izleniyordu'::text,'izliyordu'::text,'izleniyor'::text,'Su samuru dev bir balık tarafından izleniyordu, yani yalnız değildi.'::text),
(358137,39793,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vidrát egy óriási hal ..., így nem volt egyedül.'::text,'figyelte'::text,'figyelte'::text,'figyeli'::text,'A vidrát egy óriási hal figyelte, így nem volt egyedül.'::text),
(358158,39796,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend wird dieser riesige Fisch den Otter noch hundertmal ..., ein ruhiger Tag, natürlich.'::text,'erschreckt haben'::text,'erschrecken'::text,'erschreckt'::text,'Bis heute Abend wird dieser riesige Fisch den Otter noch hundertmal erschreckt haben, ein ruhiger Tag, natürlich.'::text),
(358162,39796,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора та велетенська риба ... видру ще сто разів. Спокійний день, звісно.'::text,'налякає'::text,'налякає'::text,'лякає'::text,'До вечора та велетенська риба налякає видру ще сто разів. Спокійний день, звісно.'::text),
(358161,39796,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche, ese pez gigante ... a la nutria cien veces más. Un día tranquilo, obviamente.'::text,'habrá asustado'::text,'asustará'::text,'asusta'::text,'Para esta noche, ese pez gigante habrá asustado a la nutria cien veces más. Un día tranquilo, obviamente.'::text),
(358160,39796,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, ce poisson géant ... la loutre encore cent fois. Une journée calme, évidemment.'::text,'aura effrayé'::text,'effraiera'::text,'effraie'::text,'D''ici ce soir, ce poisson géant aura effrayé la loutre encore cent fois. Une journée calme, évidemment.'::text),
(358163,39796,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar o dev balık su samurunu yüz kez daha ..., sakin bir gün tabii.'::text,'korkutmuş olacak'::text,'korkutacak'::text,'korkutuyor'::text,'Bu akşama kadar o dev balık su samurunu yüz kez daha korkutmuş olacak, sakin bir gün tabii.'::text),
(358164,39796,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére az az óriási hal még százszor ... a vidrát. Nyugis nap, persze.'::text,'megijeszti'::text,'meg fogja ijeszteni'::text,'ijesztgeti'::text,'Estére az az óriási hal még százszor megijeszti a vidrát. Nyugis nap, persze.'::text),
(375024,41670,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit werden wieder Vögel über dem Platz ..., wie sie es in der Dämmerung typischerweise tun.'::text,'kreisen'::text,'kreisen'::text,'kreisen'::text,'Morgen um diese Zeit werden wieder Vögel über dem Platz kreisen, wie sie es in der Dämmerung typischerweise tun.'::text),
(375028,41670,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час птахи знову ... над площею, як вони зазвичай роблять у сутінках.'::text,'кружлятимуть'::text,'кружлятимуть'::text,'кружляють'::text,'Завтра в цей час птахи знову кружлятимуть над площею, як вони зазвичай роблять у сутінках.'::text),
(375027,41670,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, los pájaros ... de nuevo sobre la plaza, como suelen hacer al anochecer.'::text,'estarán volando en círculos'::text,'volarán en círculos'::text,'vuelan en círculos'::text,'Mañana a esta hora, los pájaros estarán volando en círculos de nuevo sobre la plaza, como suelen hacer al anochecer.'::text),
(375026,41670,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, des oiseaux ... de nouveau au-dessus de la place, comme ils le font généralement au crépuscule.'::text,'tourneront'::text,'tourneront'::text,'tournent'::text,'Demain à la même heure, des oiseaux tourneront de nouveau au-dessus de la place, comme ils le font généralement au crépuscule.'::text),
(375029,41670,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte kuşlar, alacakaranlıkta genelde yaptıkları gibi, yine meydanın üzerinde ...'::text,'dönüyor olacak'::text,'dönecek'::text,'dönüyor'::text,'Yarın bu saatte kuşlar, alacakaranlıkta genelde yaptıkları gibi, yine meydanın üzerinde dönüyor olacak.'::text),
(375030,41670,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a madarak újra ... a tér fölött, ahogy szürkületkor jellemzően teszik.'::text,'körözni fognak'::text,'körözni fognak'::text,'köröznek'::text,'Holnap ilyenkor a madarak újra körözni fognak a tér fölött, ahogy szürkületkor jellemzően teszik.'::text),
(375033,41671,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das nasse Pflaster des Platzes ... innerhalb von etwa zwei Stunden vollständig.'::text,'trocknet'::text,'trocknet'::text,'trocknet gerade'::text,'Das nasse Pflaster des Platzes trocknet innerhalb von etwa zwei Stunden vollständig.'::text),
(375037,41671,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мокра бруківка площі повністю ... приблизно за дві години.'::text,'висохне'::text,'сохнутиме'::text,'сохне'::text,'Мокра бруківка площі повністю висохне приблизно за дві години.'::text),
(375036,41671,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pavimento mojado de la plaza se ... por completo en aproximadamente dos horas.'::text,'secará'::text,'estará secando'::text,'está secando'::text,'El pavimento mojado de la plaza se secará por completo en aproximadamente dos horas.'::text),
(375035,41671,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pavé mouillé de la place ... complètement en environ deux heures.'::text,'séchera'::text,'sera en train de sécher'::text,'est en train de sécher'::text,'Le pavé mouillé de la place séchera complètement en environ deux heures.'::text),
(375038,41671,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meydanın ıslak taşları yaklaşık iki saat içinde tamamen ...'::text,'kuruyacak'::text,'kuruyor olacak'::text,'kuruyor'::text,'Meydanın ıslak taşları yaklaşık iki saat içinde tamamen kuruyacak.'::text),
(375039,41671,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tér nedves burkolata körülbelül két órán belül teljesen ...'::text,'megszárad'::text,'száradni fog'::text,'szárad'::text,'A tér nedves burkolata körülbelül két órán belül teljesen megszárad.'::text),
(375042,41672,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn Regen auf das Steinpflaster ..., reflektiert der Platz das Abendlicht.'::text,'fällt'::text,'fiel'::text,'fallen wird'::text,'Wenn Regen auf das Steinpflaster fällt, reflektiert der Platz das Abendlicht.'::text),
(375046,41672,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли дощ ... на кам''яну бруківку, площа відбиває вечірнє світло.'::text,'падає'::text,'падав'::text,'падатиме'::text,'Коли дощ падає на кам''яну бруківку, площа відбиває вечірнє світло.'::text),
(375045,41672,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la lluvia ... sobre el pavimento de piedra, la plaza refleja la luz de la tarde.'::text,'cae'::text,'caía'::text,'caerá'::text,'Si la lluvia cae sobre el pavimento de piedra, la plaza refleja la luz de la tarde.'::text),
(375044,41672,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la pluie ... sur le pavé de pierre, la place reflète la lumière du soir.'::text,'tombe'::text,'tombait'::text,'tombera'::text,'Si la pluie tombe sur le pavé de pierre, la place reflète la lumière du soir.'::text),
(375047,41672,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Taş zemine yağmur ..., meydan akşam ışığını yansıtır.'::text,'yağarsa'::text,'yağsaydı'::text,'yağacaksa'::text,'Taş zemine yağmur yağarsa, meydan akşam ışığını yansıtır.'::text),
(375048,41672,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha eső ... a kőburkolatra, a tér visszatükrözi az esti fényt.'::text,'esik'::text,'esett'::text,'fog esni'::text,'Ha eső esik a kőburkolatra, a tér visszatükrözi az esti fényt.'::text),
(375051,41673,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Auto steht allein auf dem Platz, also ... der Besitzer irgendwo in der Nähe sein.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Das Auto steht allein auf dem Platz, also muss der Besitzer irgendwo in der Nähe sein.'::text),
(375055,41673,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Машина на площі сама, тож власник ... бути десь поруч.'::text,'мусить'::text,'не може'::text,'не повинен'::text,'Машина на площі сама, тож власник мусить бути десь поруч.'::text),
(375054,41673,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche está solo en la plaza, así que el dueño ... estar cerca.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'El coche está solo en la plaza, así que el dueño debe de estar cerca.'::text),
(375053,41673,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture est seule sur la place, donc le propriétaire ... être quelque part tout près.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'La voiture est seule sur la place, donc le propriétaire doit être quelque part tout près.'::text),
(375056,41673,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araba meydanda yalnız, yani sahibi yakınlarda bir yerde ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Araba meydanda yalnız, yani sahibi yakınlarda bir yerde olmalı.'::text),
(375057,41673,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autó egyedül áll a téren, szóval a tulajdonos ... valahol a közelben van.'::text,'biztosan'::text,'biztosan nem'::text,'semmiképp sem'::text,'Az autó egyedül áll a téren, szóval a tulajdonos biztosan valahol a közelben van.'::text),
(375069,41675,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Besitzer schwor, dass er sein Auto nie wieder allein auf diesem furchtbaren Platz ...!'::text,'lassen würde'::text,'lassen wird'::text,'lässt'::text,'Der Besitzer schwor, dass er sein Auto nie wieder allein auf diesem furchtbaren Platz lassen würde!'::text),
(375073,41675,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Власник поклявся, що більше ніколи не ... свою машину саму на тій жахливій площі!'::text,'залишить'::text,'залишить'::text,'залишає'::text,'Власник поклявся, що більше ніколи не залишить свою машину саму на тій жахливій площі!'::text),
(375072,41675,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El dueño juró que ... su coche solo en esa plaza aterradora!'::text,'nunca más dejaría'::text,'nunca más dejará'::text,'nunca más deja'::text,'¡El dueño juró que nunca más dejaría su coche solo en esa plaza aterradora!'::text),
(375071,41675,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le propriétaire a juré qu''il ... plus jamais sa voiture seule sur cette place terrifiante !'::text,'ne laisserait'::text,'ne laissera'::text,'ne laisse'::text,'Le propriétaire a juré qu''il ne laisserait plus jamais sa voiture seule sur cette place terrifiante !'::text),
(375074,41675,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahibi, arabasını o korkunç meydanda bir daha asla yalnız ... yemin etti!'::text,'bırakmayacağına'::text,'bırakmayacağına'::text,'bırakmadığına'::text,'Sahibi, arabasını o korkunç meydanda bir daha asla yalnız bırakmayacağına yemin etti!'::text),
(375075,41675,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tulajdonos megesküdött, hogy soha többé nem ... egyedül az autóját azon a félelmetes téren!'::text,'hagyja'::text,'fogja hagyni'::text,'hagyja'::text,'A tulajdonos megesküdött, hogy soha többé nem hagyja egyedül az autóját azon a félelmetes téren!'::text),
(375078,41676,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Platz ... früher voller Menschen. Jetzt ist er komplett leer!'::text,'war'::text,'war'::text,'war es gewohnt zu sein'::text,'Dieser Platz war früher voller Menschen. Jetzt ist er komplett leer!'::text),
(375082,41676,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця площа ... повною людей. Тепер вона зовсім порожня!'::text,'колись була'::text,'бувала'::text,'звикла бути'::text,'Ця площа колись була повною людей. Тепер вона зовсім порожня!'::text),
(375081,41676,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esta plaza ... estar llena de gente! ¡Ahora está completamente vacía!'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'¡Esta plaza solía estar llena de gente! ¡Ahora está completamente vacía!'::text),
(375080,41676,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette place ... pleine de monde. Maintenant, elle est complètement vide !'::text,'était autrefois'::text,'était'::text,'avait l''habitude d''être'::text,'Cette place était autrefois pleine de monde. Maintenant, elle est complètement vide !'::text),
(375083,41676,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu meydan eskiden insanlarla dolu ..., şimdiyse tamamen boş!'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Bu meydan eskiden insanlarla dolu olurdu, şimdiyse tamamen boş!'::text),
(375084,41676,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a tér ... tele volt emberekkel. Most teljesen üres!'::text,'régen'::text,'régebben'::text,'megszokásból'::text,'Ez a tér régen tele volt emberekkel. Most teljesen üres!'::text),
(375087,41677,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kamera ... sich weiter seitlich am Auto auf dem Platz vorbei.'::text,'bewegt'::text,'bewegt'::text,'bewegt'::text,'Die Kamera bewegt sich weiter seitlich am Auto auf dem Platz vorbei.'::text),
(375091,41677,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Камера продовжує ... боком повз машину на площі.'::text,'рухатися'::text,'рухатися'::text,'рухатися'::text,'Камера продовжує рухатися боком повз машину на площі.'::text),
(375090,41677,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cámara sigue ... de lado junto al coche en la plaza.'::text,'moviéndose'::text,'moverse'::text,'mover'::text,'La cámara sigue moviéndose de lado junto al coche en la plaza.'::text),
(375089,41677,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La caméra continue de ... latéralement devant la voiture sur la place.'::text,'glisser'::text,'glisser'::text,'glisser'::text,'La caméra continue de glisser latéralement devant la voiture sur la place.'::text),
(375092,41677,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera meydandaki arabanın yanından yana doğru ... devam ediyor.'::text,'kaymaya'::text,'kaymaya'::text,'kaymaya'::text,'Kamera meydandaki arabanın yanından yana doğru kaymaya devam ediyor.'::text),
(375093,41677,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kamera tovább ... oldalirányban az autó mellett a téren.'::text,'mozog'::text,'mozog'::text,'mozog'::text,'A kamera tovább mozog oldalirányban az autó mellett a téren.'::text),
(375096,41678,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das alte Auto steht bei ... allein auf dem Platz, und niemand geht daran vorbei.'::text,'Sonnenuntergang'::text,'einem Sonnenuntergang'::text,'den Sonnenuntergängen'::text,'Das alte Auto steht bei Sonnenuntergang allein auf dem Platz, und niemand geht daran vorbei.'::text),
(375100,41678,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стара машина стоїть сама на площі на ... заході сонця, і ніхто не проходить повз неї.'::text,''::text,NULL::text,NULL::text,'Стара машина стоїть сама на площі на заході сонця, і ніхто не проходить повз неї.'::text),
(375099,41678,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche viejo está solo en la plaza ..., y nadie pasa junto a él.'::text,'al atardecer'::text,'en un atardecer'::text,'en los atardeceres'::text,'El coche viejo está solo en la plaza al atardecer, y nadie pasa junto a él.'::text),
(375098,41678,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La vieille voiture est seule sur la place ..., et personne ne passe à côté.'::text,'au coucher du soleil'::text,'à un coucher du soleil'::text,'aux couchers du soleil'::text,'La vieille voiture est seule sur la place au coucher du soleil, et personne ne passe à côté.'::text),
(375101,41678,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eski araba ... gün batımında meydanda tek başına duruyor ve kimse yanından geçmiyor.'::text,''::text,'bir'::text,NULL::text,'Eski araba gün batımında meydanda tek başına duruyor ve kimse yanından geçmiyor.'::text),
(375102,41678,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A régi autó ... egyedül áll a téren, és senki sem megy el mellette.'::text,'naplementekor'::text,'egy naplementekor'::text,'a naplementékkor'::text,'A régi autó naplementekor egyedül áll a téren, és senki sem megy el mellette.'::text),
(375105,41679,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Auto ... schon seit einer Stunde mitten auf dem Platz.'::text,'steht'::text,'steht'::text,'steht'::text,'Das Auto steht schon seit einer Stunde mitten auf dem Platz.'::text),
(375109,41679,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Машина ... посеред площі вже годину.'::text,'стоїть'::text,'стоїть'::text,'стоїть'::text,'Машина стоїть посеред площі вже годину.'::text),
(375108,41679,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche ... en medio de la plaza desde hace una hora.'::text,'ha estado'::text,'está'::text,'está'::text,'El coche ha estado en medio de la plaza desde hace una hora.'::text),
(375107,41679,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture ... au milieu de la place depuis une heure.'::text,'se trouve'::text,'se trouve'::text,'se trouve'::text,'La voiture se trouve au milieu de la place depuis une heure.'::text),
(375110,41679,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araba bir saattir meydanın ortasında ...'::text,'duruyor'::text,'duruyor'::text,'durur'::text,'Araba bir saattir meydanın ortasında duruyor.'::text),
(375111,41679,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autó már egy órája ... a tér közepén.'::text,'áll'::text,'áll'::text,'áll'::text,'Az autó már egy órája áll a tér közepén.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
